import React from "react"
import dayjs from "dayjs"
import {
    Bar,
    BarChart,
    CartesianGrid,
    ResponsiveContainer,
    Tooltip,
    XAxis,
    YAxis,
} from "recharts"
import { AsyncContent } from "@sb-components/composites/async/AsyncContent/AsyncContent"
import { SurfaceCard, SurfaceCardList, type SurfaceCardListItem } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { Chip, type ChipTone } from "@sb-components/atoms/chips/Chip/Chip"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"
import { StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `AiQuotaHistoryPanel` — the "History" tab body inside `AiQuotaModal`: a 7-day
 * usage bar chart plus a scrollable, bordered list of recent AI charges.
 * `isLoading` swaps the whole `ChargesList` region for its shimmer mirror; an
 * empty `items` array renders the list's own empty state. The chart draws from
 * `chartPoints` regardless of either.
 */

/** What an AI charge was for — the block owns the display label per surface. */
export type AiQuotaHistorySurface = "grade" | "interview" | "chatbot"

/** {@link AiQuotaHistorySurface} → its display label. The block's own vocabulary (§14d.1). */
const PURPOSE_LABEL: Record<AiQuotaHistorySurface, string> = {
    grade: "Challenge grading",
    interview: "Interview grading",
    chatbot: "AI chat",
}

/** Fallback row title when a charge carries no specific model name. */
const AUTO_MODEL_LABEL = "Automatic model (free)"

/** Unit suffix on every credit-delta chip. */
const CREDITS_UNIT = "credit"

/** One day-bucket plotted on the usage chart. */
export interface AiQuotaHistoryChartPoint {
    /** X-axis label, already formatted (e.g. `"12/07"`). */
    day: string
    /** Credits consumed that day. */
    credits: number
}

/** One row of the recent-charges list. */
export interface AiQuotaHistoryChargeItem {
    /** Stable React key. */
    key: string
    /** Model name, when the charge names one specifically. Falls back to {@link AUTO_MODEL_LABEL}. */
    model?: string
    /** What the charge was for — drives the block-owned {@link PURPOSE_LABEL}. */
    surface: AiQuotaHistorySurface
    /** When the charge happened — the block formats this itself (`HH:mm DD/MM`). */
    occurredAt: string | number | Date
    /** Credit delta for this charge. Sign drives the trailing chip's tone (see judgement call 4). */
    credits: number
}

/** Props for {@link AiQuotaHistoryPanel}. */
export interface AiQuotaHistoryPanelProps {
    /** The 7 day-buckets for the chart. Defaults to an empty plot when omitted. */
    chartPoints?: Array<AiQuotaHistoryChartPoint>
    /** Recent charges, most recent first. `undefined` while the first load is still running. */
    items?: Array<AiQuotaHistoryChargeItem>
    /** `true` while the charges list's first load is running (drives ONLY the `ChargesList` leaf). */
    isLoading: boolean
    /** Where this sits inside its parent. Appearance is not passable — it is already a prop. */
    classNames?: Array<AllowedClassName>
}

/** How many placeholder rows the loading mirror shows — matches the source's 3-row skeleton. */
const SKELETON_ROW_COUNT = 3

/** Chip tone for a credit delta — see judgement call 4 in the file header: ported verbatim. */
const deltaTone = (credits: number): ChipTone => (credits > 0 ? "warning" : "success")

const toListItem = (item: AiQuotaHistoryChargeItem): SurfaceCardListItem => ({
    key: item.key,
    title: item.model ?? AUTO_MODEL_LABEL,
    subtitle: `${PURPOSE_LABEL[item.surface]} · ${dayjs(item.occurredAt).format("HH:mm DD/MM")}`,
    meta: () => <Chip tone={deltaTone(item.credits)} text={`${item.credits} ${CREDITS_UNIT}`} />,
})

/** Placeholder rows for the loading mirror — same row shape, shimmer chip in the meta slot. */
const skeletonItems = (): Array<SurfaceCardListItem> => Array.from({ length: SKELETON_ROW_COUNT }, (_, index) => ({
    key: `skeleton-${index}`,
    title: "Model",
    subtitle: "Purpose · Time",
    meta: () => <Chip isSkeleton />,
}))

/**
 * History tab body of `AiQuotaModal` — usage chart + recent-charges list.
 *
 * @param props - {@link AiQuotaHistoryPanelProps}
 */
export const AiQuotaHistoryPanel = ({
    chartPoints = [],
    items,
    isLoading,
    classNames,
}: AiQuotaHistoryPanelProps) => {
    const isEmpty = !isLoading && (items?.length ?? 0) === 0

    const chart = (
        <StackV gap={4} principle="card-caption"
            explain="Holds caption text under card media so the caption stays attached to the image above it."
            items={[
                () => <Typography size="sm" weight="medium" text="Credits used per day (last 7 days)" />,
                () => (
                    <SurfaceCard
                        variant="nested"
                        padding={4}

                        body={() => (
                            <div className="h-44 w-full text-accent-soft-foreground">
                                <ResponsiveContainer width="100%" height="100%">
                                    <BarChart data={chartPoints} margin={{ top: 8, right: 8, bottom: 0, left: -16 }}>
                                        <CartesianGrid
                                            strokeDasharray="3 3"
                                            stroke="currentColor"
                                            className="text-divider"
                                            vertical={false}
                                        />
                                        <XAxis dataKey="day" tick={{ fontSize: 10 }} interval={0} tickLine={false} axisLine={false} />
                                        <YAxis allowDecimals={false} tick={{ fontSize: 10 }} tickLine={false} axisLine={false} width={28} />
                                        <Tooltip
                                            cursor={{ fill: "currentColor", opacity: 0.08 }}
                                            formatter={(value) => [`${value} ${CREDITS_UNIT}`, ""]}
                                        />
                                        <Bar dataKey="credits" fill="currentColor" radius={[4, 4, 0, 0]} />
                                    </BarChart>
                                </ResponsiveContainer>
                            </div>
                        )}
                    />
                ),
            ]} />
    )

    const chargesList = (
        <StackV gap={4} items={[
            () => <Typography size="sm" weight="medium" text="AI usage history" />,
            () => (
                <div className="max-h-64 overflow-y-auto">
                    <AsyncContent
                        isLoading={isLoading}
                        skeleton={() => <SurfaceCardList variant="nested" items={skeletonItems()} isSkeleton />}
                        isEmpty={isEmpty}
                        emptyContent={{
                            title: "No AI usage yet.",

                        }}
                        content={() => <SurfaceCardList variant="nested" items={(items ?? []).map((item) => toListItem(item))} />}

                    />
                </div>
            ),
        ]} />
    )

    return (
        <div>
            <StackV gap={6} classNames={classNames} items={[() => chart, () => chargesList]} />
        </div>
    )
}

import React from "react"
import { QuotaBar } from "@sb-components/starci/blocks/ai/QuotaBar/QuotaBar"
import { StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `AiQuotaLane` — one lane's pair of rolling-window quota bars ("next 5 hours"
 * above "this week"), shared by the Auto tab and the Premium branch of the
 * Subscription tab inside `AiQuotaModal`. Both rows are the same `QuotaBar`
 * composition reading a different window. Unset `data`/`isLoading` shimmers
 * both bars.
 */

/** One rolling-window quota reading, ready to draw as a single {@link ProgressBar}. */
export interface AiQuotaWindow {
    /** Amount consumed in this window. */
    used: number
    /** Cap for this window (`0` reads as "no allowance"). */
    limit: number
    /** Reset line under the bar (e.g. `"Resets at 18:50 on 06/01"`). `null`/unset → no line. */
    resetLabel?: string | null
}

/** The two rolling windows one {@link AiQuotaLane} tracks. */
export interface AiQuotaLaneData {
    /** Next-5-hours rolling window. */
    window5h: AiQuotaWindow
    /** This-week rolling window. */
    windowWeek: AiQuotaWindow
}

/** Props for {@link AiQuotaLane}. */
export interface AiQuotaLaneProps {
    /** The lane's two windows. Unset while `isLoading` (or before the first fetch lands). */
    data?: AiQuotaLaneData
    /** `true` → this lane's own fetch is in flight; both bars draw their skeleton mirror. */
    isLoading: boolean
}

/**
 * The lane's two bars. See the file header for what it owns (window labels)
 * and what it deliberately does not (fetching — `data` is a plain prop, never
 * an internal SWR call — and the fill-tone ramp, which `QuotaBar` owns).
 *
 * @param props - {@link AiQuotaLaneProps}
 */
const AiQuotaLane = ({ data, isLoading }: AiQuotaLaneProps) => {
    const showSkeleton = isLoading || !data

    return (
        <div>
            <StackV gap={4} items={[
                () => (
                    <QuotaBar
                        label="Next 5 hours"
                        used={data?.window5h.used ?? 0}
                        limit={data?.window5h.limit ?? 0}
                        resetLabel={data?.window5h.resetLabel}
                        isSkeleton={showSkeleton}


                    />
                ),
                () => (
                    <QuotaBar
                        label="This week"
                        used={data?.windowWeek.used ?? 0}
                        limit={data?.windowWeek.limit ?? 0}
                        resetLabel={data?.windowWeek.resetLabel}
                        isSkeleton={showSkeleton}


                    />
                ),
            ]} />
        </div>
    )
}

export { AiQuotaLane }

import React from "react"
import { ArrowRightIcon } from "@phosphor-icons/react"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { SurfaceCard } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { AiQuotaLane, type AiQuotaLaneData } from "@sb-components/starci/blocks/ai/AiQuotaLane/AiQuotaLane"
import { StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `AiQuotaSubscriptionPanel` — the "Plan" tab body inside `AiQuotaModal`. The
 * Premium branch reuses `AiQuotaLane` unchanged; this panel owns the switch on
 * `tier` (no plan: CTA-in-a-card; active plan: lane-plus-caption) and the
 * surrounding CTA/caption wording.
 */

/** Paid AI subscription tier (mirrors `src`'s `AiSubTier`). */
export type AiQuotaTier = "plus" | "pro" | "max"

/** {@link AiQuotaTier} → its display code in the "active tier" caption. */
const TIER_LABEL: Record<AiQuotaTier, string> = {
    plus: "PLUS",
    pro: "PRO",
    max: "MAX",
}

/** The Premium `AiQuotaLane` feed — same shape {@link AiQuotaLane} itself takes, passed straight through. */
export interface AiQuotaSubscriptionPanelPremiumLane {
    /** The lane's two windows. Unset while `isLoading` (or before the first fetch lands). */
    data?: AiQuotaLaneData
    /** `true` → the Premium lane's own fetch is in flight. */
    isLoading: boolean
}

/** Props {@link AiQuotaSubscriptionPanel} carries regardless of loading state. */
interface AiQuotaSubscriptionPanelOwnProps {
    /** Fired when the reader taps the CTA on the no-tier leaf. */
    onSubscribe: () => void
    /** Extra classes on the root. */
    className?: string
}

/**
 * Props for {@link AiQuotaSubscriptionPanel}. `tier`/`premiumLane` are REQUIRED
 * unless `isSkeleton` (§12b) — which of the two leaves to show isn't known
 * before the subscription fetch resolves.
 */
export type AiQuotaSubscriptionPanelProps = AiQuotaSubscriptionPanelOwnProps &
    (
        | { isSkeleton: true; tier?: AiQuotaTier | null; premiumLane?: AiQuotaSubscriptionPanelPremiumLane }
        | {
            isSkeleton?: false
            /** Active paid tier, or `null` on the free lane — picks the leaf. */
            tier: AiQuotaTier | null
            /** Premium lane data, only rendered once `tier` is set. */
            premiumLane: AiQuotaSubscriptionPanelPremiumLane
        }
    )

/**
 * Subscription tab body of `AiQuotaModal`. See the file header for the full
 * contract and the two leaves.
 *
 * @param props - {@link AiQuotaSubscriptionPanelProps}
 */
const AiQuotaSubscriptionPanel = ({
    tier,
    premiumLane,
    onSubscribe,
    isSkeleton = false,
    className,
}: AiQuotaSubscriptionPanelProps) => {
    if (isSkeleton) {
        return (
            <div className={className}>
                <AiQuotaLane isLoading />
            </div>
        )
    }
    if (tier == null) {
        return (
            <div className={className}>
                <SurfaceCard
                    variant="nested"
                    padding={4}


                    body={() => (
                        <StackV gap={4} principle="content-row"
                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                            align="start" isSkeleton={isSkeleton} items={[
                                () => (
                                    <Typography
                                        size="sm"
                                        color="muted"
                                        isSkeleton={isSkeleton}
                                        text="You don't have a paid plan yet. Upgrade to unlock Premium credit and get graded with premium models."

                                    />
                                ),
                                () => (
                                    <Button
                                        label="Subscribe to a paid plan"
                                        variant="primary"
                                        size="lg"
                                        suffixIcon={ArrowRightIcon}
                                        iconSlide
                                        isSkeleton={isSkeleton}
                                        onPress={onSubscribe}
                                    />
                                ),
                            ]} />
                    )}
                />
            </div>
        )
    }

    return (
        <div className={className}>
            <StackV gap={4} isSkeleton={isSkeleton} items={[
                () => (
                    <AiQuotaLane
                        data={premiumLane?.data}
                        isLoading={premiumLane?.isLoading ?? false}


                    />
                ),
                () => (
                    <Typography
                        size="sm"
                        color="muted"
                        isSkeleton={isSkeleton}
                        text={`You're on the ${TIER_LABEL[tier]} plan.`}

                    />
                ),
            ]} />
        </div>
    )
}

export { AiQuotaSubscriptionPanel }

import React from "react"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { ProgressBar, type ProgressColor } from "@sb-components/atoms/display/Progress/Progress"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"

/**
 * BLOCK — `QuotaBar`: one labelled used/limit AI-credit row whose fill colour
 * steps through a 3-tier ramp (accent ≤75% · warning >75% · danger >90%) as the
 * window fills up, with an optional reset-time caption underneath.
 *
 * Two of these stack inside `QuotaLane` (a 5-hour window, a 7-day window), which
 * itself sits inside the `AiQuotaModal` overlay.
 *
 * LEAF by STRUCTURE: the fill tone, the unit suffix, and the reset caption are all
 * DATA ⇒ states of one leaf. The caller flipping `isSkeleton` is its own leaf, same
 * convention as `RatingBar`/`PriceTag`.
 */

/** Usage ratio above which the bar shows warning colour (>75%). */
const WARNING_USAGE_RATIO = 0.75

/** Usage ratio above which the bar shows danger colour (>90%). */
const DANGER_USAGE_RATIO = 0.9

/**
 * Map consumed share to a progress-bar colour tier. Ported verbatim (same
 * thresholds, same `limit <= 0` edge case) from
 * `src`'s `resolveQuotaBarFillTone`.
 * @param ratio - Consumed share, already clamped to `[0, 1]`.
 * @returns `"accent"` (≤75%), `"warning"` (>75%), or `"danger"` (>90%).
 */
const resolveQuotaBarFillTone = (ratio: number): ProgressColor => {
    if (ratio > DANGER_USAGE_RATIO) {
        return "danger"
    }
    if (ratio > WARNING_USAGE_RATIO) {
        return "warning"
    }
    return "accent"
}

/** Props for {@link QuotaBar}. */
export interface QuotaBarProps {
    /** Window label (e.g. "Next 5 hours"). Block carries no i18n — caller localises. */
    label: string
    /** Amount consumed in the window. */
    used: number
    /** Cap for the window (`0` means "no allowance"). */
    limit: number
    /** Unit suffix appended after the counts when {@link QuotaBarProps.showUnit} is true. */
    unit?: string
    /** `true` → append {@link QuotaBarProps.unit} after the used/limit counts. */
    showUnit?: boolean
    /** Reset time shown under the bar (e.g. "Resets at 18:50 01/06"). `null`/omitted hides the row. */
    resetLabel?: string | null
    /** `true` → the block draws its own row mirror (label, bar, caption all shimmer). */
    isSkeleton?: boolean
    /** Where this sits inside its parent. Appearance is not passable — it is already a prop. */
    classNames?: Array<AllowedClassName>
}

/**
 * The quota usage row. See the file header for the full contract.
 * @param props - {@link QuotaBarProps}
 */
const QuotaBar = ({
    label,
    used,
    limit,
    unit,
    showUnit = false,
    resetLabel,
    isSkeleton = false,
    classNames,
}: QuotaBarProps) => {
    const ratio = limit > 0
        ? Math.min(1, Math.max(0, used / limit))
        : (used > 0 ? 1 : 0)
    const fillTone = resolveQuotaBarFillTone(ratio)
    const value = ratio * 100

    // Whether the caption row has a box to occupy: a resting bar always reserves
    // it (§8, see file header); a live bar only reserves it when there IS a
    // reset time to show.
    const showCaption = isSkeleton || resetLabel != null

    // LabelRow — the window label on the left, the "used / limit" count on the
    // right. Peers on one baseline row (§13b), same shape as `RatingBar`'s own
    // label+key row: `StackH` with `justify="between"`, not `Cluster` — there
    // are exactly two fixed slots here, not a repeating same-kind list.
    const labelRow = (
        <StackH
            gap={3}
            principle="value-row"
            explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
            align="center"
            justify="between"
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <Typography
                        size="sm"
                        color="muted"
                        isSkeleton={isSkeleton}


                        text={label}
                    />
                ),
                () => (
                    <Typography
                        size="sm"
                        weight="medium"
                        tabularNums
                        isSkeleton={isSkeleton}


                        text={(
                            <>
                                {used}
                                {" / "}
                                {limit}
                                {showUnit && unit ? (
                                    <>
                                        {" "}
                                        <Typography size="sm" color="muted" isInline text={unit} />
                                    </>
                                ) : null}
                            </>
                        )}
                    />
                ),
            ]}
        />
    )

    const bar = (
        <div>
            <ProgressBar
                value={value}
                max={100}
                color={fillTone}
                size="sm"
                ariaLabel={label}
                isSkeleton={isSkeleton}

            />
        </div>
    )

    return (
        <StackV identity={{ tier: "block", component: "QuotaBar" }}
            gap={4}
            classNames={classNames}
            isSkeleton={isSkeleton}
            items={[
                () => labelRow,
                () => bar,
                ...(showCaption ? [() => (
                    <Typography
                        size="xs"
                        color="muted"
                        isSkeleton={isSkeleton}


                        text={resetLabel ?? undefined}
                    />
                )] : []),
            ]}
        />
    )
}

export { QuotaBar }

import React from "react"
import { Skeleton as HeroSkeleton } from "@heroui/react"
import { WarningCircleIcon } from "@phosphor-icons/react"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { Cluster } from "@sb-components/frames/Cluster/Cluster"

/**
 * `PhaseScarcityNote` — the scarcity line for a pricing phase. Every number
 * comes from the backend's `coursePricePreview`; it never fabricates a
 * countdown or seat count, and a phase with no seat cap renders nothing.
 */

/** The course's pricing phases (inlined from `@/modules/types/enums/pricing-phase`). */
export enum PricingPhase {
    /** Opening phase with the fewest seats and the lowest price. */
    Pioneer = "pioneer",
    /** Mid phase after pioneer, still discounted before standard pricing. */
    EarlyBird = "early_bird",
    /** Full-price phase after early-bird seats are gone. */
    Regular = "regular",
}

/** Localised phase display name (inlined from `courseLanding.phase.*`, vi). */
const PHASE_LABEL: Record<PricingPhase, string> = {
    [PricingPhase.Pioneer]: "Pioneer",
    [PricingPhase.EarlyBird]: "Early Bird",
    [PricingPhase.Regular]: "Standard",
}

/**
 * Props for {@link PhaseScarcityNote}. `currentPhase`/`seatsRemaining`/
 * `nextPhasePriceVnd` are REQUIRED unless `isSkeleton` (§12b) — the price
 * preview hasn't arrived yet, so there is no honest phase/seat fact to state.
 */
export type PhaseScarcityNoteBaseProps =
    (
        | { isSkeleton: true; currentPhase?: PricingPhase; seatsRemaining?: number | null; nextPhasePriceVnd?: number | null }
        | {
            isSkeleton?: false
            /** The course's current pricing phase (shows its label). */
            currentPhase: PricingPhase
            /** Seats left at this phase's price; `null` = unlimited → renders NOTHING. */
            seatsRemaining: number | null
            /** VND price after this phase sells out; `null` = no rise to mention. */
            nextPhasePriceVnd: number | null
        }
    )

/**
 * Honest scarcity line for a paywall. Sits as a DIRECT SIBLING below `PriceTag`
 * (PriceTag handles discounting; scarcity is a different, orthogonal push axis).
 *
 * Only renders when the current phase has a **real seat cap**
 * (`seatsRemaining != null`) — an unlimited phase has no honest "rises when"
 * milestone to state, so it stays silent. EVERY number comes from the
 * backend's `coursePricePreview` — this file NEVER makes up a countdown or
 * seat count (fake scarcity is a banned dark pattern).
 *
 * @param props - {@link PhaseScarcityNoteBaseProps}
 */
const PhaseScarcityNoteBase = ({
    currentPhase,
    seatsRemaining,
    nextPhasePriceVnd,
    isSkeleton = false,
}: PhaseScarcityNoteBaseProps) => {
    if (isSkeleton) {
        return <HeroSkeleton className="h-4 w-64 max-w-full rounded" />
    }
    // no seat cap at this phase → no honest scarcity reason → stay silent
    if (seatsRemaining == null) {
        return null
    }

    return (
        // Color is set ON THE FRAME; text inside does NOT declare `color`, so it
        // inherits `currentColor` — the exact `warning-soft-foreground` tone.
        //
        // This row is ONE TRACK of N elements that wrap ⇒ exactly the definition
        // of `Cluster`, and repeated lists go through `items` DATA (children are
        // forbidden).
        //
        // What's gained isn't "fewer classes" but that `gap` is now PINNED to
        // the scale BY TYPE: hand-written it's `gap-2` today, `gap-1.5`
        // tomorrow, nothing stops that.
        <div className="text-warning-soft-foreground">
            <Cluster
                gap={3}
                principle="separator-dot"
                explain="Places a middle-dot separator between short meta peers so the items read as one inline list."
                align="center"
                // The `·` between the two clauses is drawn by the FRAME, not written as a text item.
                // A mark that separates a track's items belongs to the track, the same way a rule
                // does; written as content it also produced a `Separator` node in the structure tree
                // whose link went to the generic Typography story.
                separator
                items={[
                    () => (
                        // §5a: icon matches the FONT-SIZE of the text beside it — `sm`
                        // (14px) ⇒ `size-3.5`. §5.0a: below `size-5` ⇒ force
                        // `weight="bold"` to compensate for the thin strokes.
                        <WarningCircleIcon
                            aria-hidden
                            focusable="false"
                            weight="bold"
                            className="size-3.5 shrink-0"
                        />
                    ),
                    () => (
                        <Typography
                            size="sm"
                            weight="medium"
                            text={`${seatsRemaining} seats left at the ${currentPhase != null ? PHASE_LABEL[currentPhase] : ""} price`}

                        />
                    ),
                    // The next two pieces go TOGETHER (no rise means nothing to separate
                    // it from) — but they're still TWO SEPARATE cluster items, since the
                    // `·` mark must be allowed to wrap onto the line with the piece after
                    // it when the row runs tight.
                    ...(nextPhasePriceVnd != null
                        ? [
                            () => (
                                <Typography
                                    size="sm"
                                    text={`price rises to ${nextPhasePriceVnd.toLocaleString("vi-VN")}₫ after that`}

                                />
                            ),
                        ]
                        : []),
                ]}
            />
        </div>
    )
}

/** `PhaseScarcityNote.*` — single-component namespace ⇒ only `.Base`. */
export { PhaseScarcityNoteBase as PhaseScarcityNote }

import React from "react"
import { type SkeletonProps } from "@sb-components/frames/_slot"
import { Popover } from "@heroui/react"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { Cluster } from "@sb-components/frames/Cluster/Cluster"
import { StackV } from "@sb-components/frames/Stack/Stack"
import { KeyValueList } from "@sb-components/composites/data/KeyValue/KeyValue"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"

/**
 * DESIGN — a single course/product price: the amount to pay (bold), the struck
 * list price, a `−X%` success chip, and a breakdown popover.
 *
 * ANATOMY IS PER-LEAF: each story below is its OWN leaf and wraps its render in
 * its OWN BlockAnatomy (Diagram + Tree) reflecting the parts THAT leaf composes —
 * there is no separate consolidated "Anatomy" story. The composition shifts with
 * the shape: no-discount shows only the amount; on-sale adds the struck price,
 * chip, popover, and saving line; `showSavingLine={false}` drops that last line.
 */

/** Currency a price is shown in. */
export type PriceCurrency = "VND" | "USD"

/**
 * How loud the price is on its surface — decides the amount's font size. INTERNAL,
 * and deliberately NOT named `role`: that word is a DOM/ARIA attribute, so a prop by
 * that name reads as an accessibility role to both a reader and to eslint-jsx-a11y
 * (which flagged `role="prominent"` as an invalid ARIA role three times).
 * not exposed as a prop (§14d.1): the caller picks a MEMBER (`PriceTagInline` /
 * `PriceTagProminent`), not a size.
 */
export type PriceEmphasis = "inline" | "prominent"

/** Breakdown rows for the breakdown popover (amounts in the SAME currency as the price). */
export interface PriceBreakdown {
    /** Active-phase price BEFORE loyalty (the middle step list -> phase -> charge). */
    phase: number
    /** Localised phase name (e.g. "Early-bird") shown on the phase row. */
    phaseLabel?: string
    /** Loyalty discount percent (0 = no loyalty row). */
    loyaltyPercent: number
    /** Localised loyalty note (e.g. "already owns 2 courses") appended to the loyalty row. */
    loyaltyNote?: string
}

/** Props for the {@link PriceTag} block. */
export interface PriceTagProps {
    /** The price the user actually pays. */
    discounted: number
    /** The pre-discount (list/MSRP) price; struck through when greater than discounted. */
    original?: number | null
    /** Currency to format in. Defaults to "VND". */
    currency?: PriceCurrency
    /**
 * `true` -> the price is in its RESTING state: the amount, the struck-through
 * original price, the `−X%` chip, and the saving line all turn to shimmer,
 * KEEPING the same line boxes so nothing jumps in layout (§8).
 *
 * The flag FLOWS DOWN into the atoms that render each part (`Typography`,
 * `Chip`), instead of building a second shimmer tree (§12c). The popover
 * is TURNED OFF while resting — there is no data to open yet, and a pressable
 * control while loading is a false promise.
 */
    isSkeleton?: boolean
    /**
 * Optional phase-tier + loyalty rows for the breakdown {@link Popover}. Whenever
 * there IS a saving the `−X%` chip is ALWAYS a button that opens the popover (at
 * minimum list price -> "you pay"); `breakdown` just adds the middle steps that
 * explain WHERE the drop came from. Click/tap (not hover) so it works on touch too.
 */
    breakdown?: PriceBreakdown
    /**
 * Show the concrete "save N₫" line under the price (the real VND saved, not just
 * the percent). Defaults to `true`; set `false` where space is tight (dense cards).
 */
    showSavingLine?: boolean
    /** Where the root sits inside its parent. */
    classNames?: Array<AllowedClassName>
}

/**
 * Role -> amount font size.
 */
const AMOUNT_TYPE: Record<PriceEmphasis, "base" | "h4"> = {
    inline: "base",
    prominent: "h4",
}

/** Role -> struck-through original-price line size, placed next to {@link AMOUNT_TYPE} so the two scales don't drift apart. */
const ORIGINAL_TYPE: Record<PriceEmphasis, "xs" | "sm"> = {
    inline: "xs",
    prominent: "sm",
}

/** Format an amount in the given currency. */
const formatPrice = (amount: number, currency: PriceCurrency): string =>
    currency === "USD"
        ? amount.toLocaleString("en-US", { style: "currency", currency: "USD" })
        : `${amount.toLocaleString("vi-VN")}₫`

/** Whole-percent saving between a "before" and an "after" amount (0 when none). */
const savingPercent = (before: number, after: number): number =>
    before > after ? Math.round((1 - after / before) * 100) : 0

/**
 * The single source of truth for rendering a course/product price: the discounted
 * amount (bold), the list price struck through (only when there IS a saving), and a
 * `−X%` success chip whose percent is the REAL list -> charge gap (phase tier +
 * loyalty). Whenever there is a saving the chip is a clickable button opening a
 * {@link Popover} (at minimum list price -> you pay; `breakdown` adds the phase +
 * loyalty steps). Works in VND or USD.
 *
 * @param props - {@link PriceTagProps}
 */
export const PriceTagBase = ({
    discounted,
    original,
    currency = "VND",
    emphasis,
    isSkeleton = false,
    breakdown,
    showSavingLine = true,
    classNames,
}: PriceTagProps & { emphasis: PriceEmphasis }) => {
    const hasSaving = original != null && original > discounted
    const savePercent = hasSaving ? savingPercent(original, discounted) : 0

    // the −X% saving chip — composed from the `Chip` atom (tone success ->
    // soft-success chip, matching src's raw `<Chip variant="soft" color="success">`).
    // The pressable/focusable button role lives on the canonical `Popover.Trigger`
    // wrapper (react-aria: role=button, aria-expanded/controls, tabindex), so there is
    // exactly ONE interactive element. No caret; the whole chip is the affordance.
    const chip =
        savePercent > 0 ? (
            <Chip
                tone="success"
                text={`−${savePercent}%`}
            />
        ) : null

    // phase saving = list -> phase ; loyalty saving = phase -> charge
    const phaseSave = original != null ? savingPercent(original, breakdown?.phase ?? discounted) : 0
    // Popover content — shown for EVERY saving (so the chip is always clickable), at
    // minimum list price -> you pay. The phase-tier & loyalty rows only appear when a
    // full `breakdown` is supplied.
    const breakdownContent = hasSaving ? (
        // Those four rows are all ONE shape: label left <-> value right, repeated =>
        // exactly `KeyValueList` (a repeated list => `items` is DATA). The "you
        // pay" row is the TOTAL row => `emphasis`, not a hand-drawn rule: the frame
        // already knows how to emphasise a total row, and that emphasis looks the same
        // across every price table in the system.
        //
        // NOTE: The frame does NOT format for you: every money string coming in here
        // has already gone through `formatPrice`.
        // NOTE: This column is NOT badged: the panel groups nodes BY NAME (`firstEl` keeps
        // only the first element of each name), so two `StackV`s with the same name
        // would MERGE into one node and the tree would read wrong. The node that
        // matters inside the popover is `KeyValueList` — that one is badged; the
        // wrapping column is just `p-3` padding.
        // Two vertical rows inside a design (the eyebrow and the breakdown list) =
        // `grouped`, not `tight`. `tight` (1) is reserved for what sits INSIDE a
        // composite, e.g. the icon+label pair of `InlineIconLabel`.
        <StackV gap={1} principle="cell-pad"
            explain="Tight cell inset — not card-padding, because this sits inside a dense table or list cell rather than a card body."
            padding={4} isSkeleton={isSkeleton} items={[() => (
                <StackV gap={4} principle="label-field"
                    explain="Form label above its field — not title-subtitle, because the upper line labels an input rather than a heading pair."
                    isSkeleton={isSkeleton} items={[
                        ({ isSkeleton }: SkeletonProps) => <Typography size="xs" color="muted" text="Price breakdown" isSkeleton={isSkeleton} />,
                        // No `gap` passed: `KeyValueList` already owns its row rhythm (its own default
                        // is the §10b `grouped` step). Passing one from here overrides the composite's
                        // spacing from OUTSIDE, which §10 forbids — a composite owns its internal
                        // spacing and must not receive it.
                        ({ isSkeleton }: SkeletonProps) => (
                            <KeyValueList
                                isSkeleton={isSkeleton}
                                items={[
                                    {
                                        key: "list",
                                        label: "List price",
                                        value: formatPrice(original ?? discounted, currency),
                                    },
                                    ...(breakdown && original != null && original > breakdown.phase
                                        ? [{
                                            key: "phase",
                                            label: breakdown.phaseLabel ? `${breakdown.phaseLabel} phase` : "Phase discount",
                                            // NOTE: `KeyValueListItem.value` is now a plain `string` — this row
                                            // loses the `color="success-soft"` (green) tint it used to carry via
                                            // its own `Typography`. `KeyValueRow` only renders `value` through the
                                            // emphasis/plain split, no per-row tone prop. Preserving the green
                                            // accent needs either accepting the loss (done here) or a future
                                            // `tone`/`accent` field on `KeyValueListItem` — left for whoever owns
                                            // PriceTag/KeyValue next, not decided in this pass.
                                            value: `−${formatPrice(original - breakdown.phase, currency)} (−${phaseSave}%)`,
                                        }]
                                        : []),
                                    ...(breakdown && breakdown.loyaltyPercent > 0 && breakdown.phase > discounted
                                        ? [{
                                            key: "loyalty",
                                            label: breakdown.loyaltyNote ? `Loyalty discount · ${breakdown.loyaltyNote}` : "Loyalty discount",
                                            // See the "phase" row's note above — same loss of the green tint,
                                            // same reason.
                                            value: `−${formatPrice(breakdown.phase - discounted, currency)} (−${breakdown.loyaltyPercent}%)`,
                                        }]
                                        : []),
                                    {
                                        key: "total",
                                        label: "You pay",
                                        value: formatPrice(discounted, currency),
                                        // the TOTAL row: the frame handles the emphasis, replacing a hand-typed `border-t … pt-1`
                                        emphasis: true,
                                    },
                                ]}
                            />
                        ),
                    ]} />
            )]} />
    ) : null

    // The price row aligns on BASELINE (big number, struck number, chip share the
    // same text baseline) and wraps on its own when tight => exactly `Cluster`.
    // The three elements are THREE separate items, not merged into one
    // fragment — merging them leaves the frame's `gap` with nowhere to apply.
    const priceRow = (
        <Cluster
            gap={3}
            principle="value-row"
            align="baseline"

            items={[
                // The amount goes through the ATOM `Typography` (§9c), NOT raw
                // HeroUI — thanks to that, `isSkeleton` flows straight into it instead
                // of branching off to build a separate shimmer bar.
                () => (
                    <Typography
                        size={AMOUNT_TYPE[emphasis]}
                        weight="bold"
                        isSkeleton={isSkeleton}


                        text={formatPrice(discounted, currency)}
                    />
                ),
                ...(hasSaving
                    ? [() => (
                        <Typography
                            size={ORIGINAL_TYPE[emphasis]}
                            color="muted"
                            isSkeleton={isSkeleton}
                            isStruck


                            text={formatPrice(original, currency)}
                        />
                    )]
                    : []),
                // While resting: the chip still holds its place but is NOT wrapped in a
                // Popover — there's no data yet to open, and a pressable control while
                // loading is a false promise.
                ...(isSkeleton
                    ? [() => <Chip isSkeleton />]
                    : savePercent > 0
                        ? [() => (
                            <Popover>
                                <Popover.Trigger
                                    aria-label="Price breakdown"
                                    className="cursor-pointer focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent"

                                >
                                    {chip}
                                </Popover.Trigger>
                                <Popover.Content
                                    className="max-w-xs"

                                >
                                    {breakdownContent}
                                </Popover.Content>
                            </Popover>
                        )]
                        : []),
            ]}
        />
    )

    const savingLine = showSavingLine && (isSkeleton || hasSaving) ? (
        <Typography
            size="xs"
            color="muted"
            isSkeleton={isSkeleton}


            text={hasSaving ? `Save ${formatPrice(original - discounted, currency)}` : undefined}
        />
    ) : null

    return (
        // The outer column = two DIFFERENT lines (the price row · the "saving" line) =>
        // `StackV`, NOT `Cluster`: a cluster is ONE track of N PEER elements (§13b).
        <StackV
            // `grouped` (§10b): the price row and the saving line are two DIFFERENT vertical
            // rows of one design. It was `tight` (1), which §10b reserves for pairs sitting
            // inside a lower-tier component — the saving line read as if it were glued under the number.
            gap={4}
            classNames={classNames}
            isSkeleton={isSkeleton}
            items={[
                () => priceRow,
                () => savingLine,
            ]}
        />
    )
}

import React from "react"
import { type SkeletonProps } from "@sb-components/frames/_slot"
import { ArrowRightIcon, LockIcon } from "@phosphor-icons/react"
import { IconTile } from "@sb-components/atoms/display/IconTile/IconTile"
import { PriceBreakdown, PriceTagProminent } from "@sb-components/starci/blocks/commerce/PriceTag/PriceTag"
// The NON-legacy version (`designs/commerce/…`) — the `_legacy` version of the same
// name still exists but is a dead end; screens are forbidden from touching `_legacy`
// so every link in the chain has to move off it.
import { PhaseScarcityNote, PricingPhase } from "@sb-components/starci/blocks/commerce/PhaseScarcityNote/PhaseScarcityNote"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { TitledText } from "@sb-components/composites/text/TitledText/TitledText"
import { SurfaceCard } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"

/**
 * BLOCK — the trial -> enroll conversion strip on the content-home. Bundles a
 * loss-aversion line (free lessons remaining), the real price (+ phase-scarcity
 * note), and an enroll CTA. `src` is STORE-COUPLED (SWR price fetch + zustand
 * payment overlay) — this port takes the SAME data as PLAIN PROPS (`price`,
 * `isSkeleton`, `onEnroll`) so it renders standalone. Leaves differ by
 * SHAPE: price loading (skeleton mirror) vs price landed (PriceTag +
 * PhaseScarcityNote), and by content (free lessons remaining vs none left).
 *
 * ANATOMY IS PER-LEAF: each story below is its OWN leaf and carries its OWN
 * BlockAnatomy axis (Diagram + Tree) reflecting the parts THAT leaf composes —
 * there is no separate consolidated "Anatomy" story.
 */

/** Minimal price-preview shape this block needs (mirrors `coursePricePreview` fields actually read). */
export interface TrialConversionStripPrice {
    discountedPriceVnd: number
    originalPriceVnd?: number | null
    phasePriceVnd: number
    discountPercent: number
    currentPhase: PricingPhase
    seatsRemainingInCurrentPhase: number | null
    nextPhasePriceVnd: number | null
}

/** Props for the {@link TrialConversionStrip} block. */
export interface TrialConversionStripProps {
    /** FREE lessons the trial viewer hasn't read yet — powers the goal-gradient line. */
    freeLessonsRemaining: number
    /** Price preview for the course; `undefined`/`null` while absent (see `isSkeleton`). */
    price?: TrialConversionStripPrice | null
    /**
 * `true` -> this block is at REST. Only the PRICE region rests: the header (icon,
 * title, description) and the CTA do not depend on the price, so they render
 * immediately and the shimmer stands exactly where PriceTag + PhaseScarcityNote will
 * land, which is what stops the layout jumping when the price arrives.
 *
 * Named `isSkeleton`, not `isPriceLoading` (§12g.0a: ONE vocabulary across all five
 * tiers). The old name was a second word for the same idea at this tier only, so a
 * reader crossing the block boundary had to translate it every time — and the screen
 * had to write `isPriceLoading={isSkeleton}` to bridge the two.
 */
    isSkeleton?: boolean
    /** Fired when the enroll CTA is pressed (caller owns opening the payment flow). */
    onEnroll?: () => void
    /** Layout utilities on the root, from the closed positioning union (SurfaceCard's `className` door was deleted, COMPOSITE-4). */
    classNames?: Array<AllowedClassName>
}

/**
 * Trial -> enroll conversion strip on the content-home. Bundles three honest
 * levers on the surface they actually land on: (1) LOSS-AVERSION — "you've
 * read N/M free lessons, keep going"; (2) SCARCITY — the real pricing-phase
 * seats + next-tier price via {@link PhaseScarcityNote}; (3) the enroll CTA.
 * Every number is a prop from the caller — this block never fabricates one.
 *
 * @param props - {@link TrialConversionStripProps}
 */
const TrialConversionStripBase = ({
    freeLessonsRemaining,
    price,
    isSkeleton = false,
    onEnroll,
    classNames,
}: TrialConversionStripProps) => {
    const hasFreeLeft = freeLessonsRemaining > 0

    const breakdown: PriceBreakdown | undefined = price
        ? {
            phase: price.phasePriceVnd,
            loyaltyPercent: price.discountPercent,
        }
        : undefined

    const headerRow = (
        <StackH gap={4} principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            align="center" isSkeleton={isSkeleton} items={[
                ({ isSkeleton }: SkeletonProps) => (
                    <IconTile
                        isSkeleton={isSkeleton}
                        icon={LockIcon}
                        tone="accent"
                        size="sm"

                    />
                ),
                // The "title + description" cluster is ONE SEMANTIC UNIT => goes through
                // ONE frame, not two separate `Typography`.
                // `TitledText size="row"` (default) already OWNS exactly this scale:
                // title `sm` medium · subtitle `xs` muted. Hand-building two atoms means
                // the block decides its own font sizes — one style per spot, with
                // nothing keeping them in sync.
                () => (
                    <TitledText
                        classNames={["flex-1"]}

                        isSkeleton={isSkeleton && !price}
                        title="Free trial — unlock the full course"
                        subtitle={
                            hasFreeLeft
                                ? `${freeLessonsRemaining} free lessons left unread — keep reading or unlock the full course now.`
                                : "You've read every free lesson — unlock the full course to keep going."
                        }
                    />
                ),
            ]} />
    )

    // `grouped`. Read the seam by RELATIONSHIP, not by tier: the
    // scarcity line is a CAPTION OF THE PRICE, so price + scarcity are one
    // cluster and this is an INTRA-cluster seam. `section` (6) belongs to the
    // seams AROUND this cluster — to the lead cluster above and to the CTA
    // beside it. Applying "design <-> design = 6"
    // mechanically here would produce the rhythm 24/12/24/24, i.e. the caption
    // as far from its own price as the CTA is from everything — a uniform
    // rhythm stops reading as groups. With 3 the
    // card reads 24/12/12/24 — two groups, which is what it is.
    const priceColumn = (
        <StackV gap={4} isSkeleton={isSkeleton} items={
            isSkeleton && !price ? [
                // The CTA card renders instantly once the outline
                // resolves, but the price is a second fetch — mirror the price
                // line instead of showing an empty gap until it lands.
                () => <Typography size="h4" isSkeleton />,
                () => <Typography size="xs" isSkeleton />,
            ] : price?.discountedPriceVnd != null ? [
                ({ isSkeleton }: SkeletonProps) => (
                    <PriceTagProminent
                        isSkeleton={isSkeleton}
                        discounted={price.discountedPriceVnd}
                        original={price.originalPriceVnd}
                        breakdown={breakdown}

                    />
                ),
                ({ isSkeleton }: SkeletonProps) => (
                    <PhaseScarcityNote
                        isSkeleton={isSkeleton}
                        currentPhase={price.currentPhase}
                        seatsRemaining={price.seatsRemainingInCurrentPhase}
                        nextPhasePriceVnd={price.nextPhasePriceVnd}
                    />
                ),
            ] : []
        } />
    )

    // Price is a NUMBER — shrinking it means nothing, unlike a long title that
    // can truncate. The correct behaviour for this row is to WRAP when tight:
    // the button drops to the next line instead of the price getting squeezed.
    // That's `StackH` with `wrap` — children are ARBITRARY.
    // The seam between the lead cluster and the price block is a SEAM, not a
    // BOUNDARY: `gap-6` on the parent stack already separates the two regions;
    // adding a `border-t` on top says the same thing twice in two languages.
    const footerRow = (
        <StackH
            gap={6}
            principle="block-boundary"
            align="end"
            justify="between"
            at="sm"
            isSkeleton={isSkeleton}
            items={[
                () => priceColumn,
                // ATOM `Button`, NOT the `_legacy` version: going around the port is drift —
                // fixing the atom in one place won't propagate here.
                // `suffixIcon` takes a COMPONENT REF, the atom forces scale + weight.
                ({ isSkeleton }: SkeletonProps) => (
                    <Button
                        isSkeleton={isSkeleton}
                        variant="primary"
                        size="lg"

                        label="Unlock the full course"
                        suffixIcon={ArrowRightIcon}
                        iconSlide
                        onPress={onEnroll}

                    />
                ),
            ]}
        />
    )

    return (
        // The frame owns radius/shadow/padding from ONE source: `SurfaceCard`.
        // `padding` defaults to `3` — the system's actual `p-3` card rule.
        <SurfaceCard
            classNames={classNames}
            body={({ isSkeleton }: SkeletonProps) => (
                <StackV gap={6} isSkeleton={isSkeleton} items={[
                    () => headerRow,
                    () => footerRow,
                ]} />
            )}
        />
    )
}

/**
 * `TrialConversionStrip.*` — namespace.
 *
 * The root stays CALLABLE so bare call-sites work; `.Base` is the standard path.
 */
export { TrialConversionStripBase as TrialConversionStrip }

import React from "react"
import { BuildingsIcon } from "@phosphor-icons/react"
import { Image } from "@sb-components/atoms/media/Image/Image"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { SurfaceCard } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `ConsultantCard` — one recruiting consultant as a self-contained pressable
 * tile (photo, name, role, company, blurb) that opens their profile on press.
 * Built on `SurfaceCard.Pressable`. `Minimal` drops `jobTitle`/`companyTitle`/
 * `description` together; `isSkeleton` keeps the same tree as shimmer.
 */

/** One recruiting consultant — plain data, the block builds the tile from it. */
export interface ConsultantCardConsultant {
    /** Stable id, passed back to {@link ConsultantCardProps.onOpen}. */
    id: string
    /** Full name — the card's accessible name. */
    fullName: string
    /** Role/title at their company. Row disappears when absent. */
    jobTitle?: string
    /** Company name. Row disappears when absent. */
    companyTitle?: string
    /** Short bio/blurb. Row disappears when absent. */
    description?: string
    /** Photo URL. Empty/missing → `Image`'s own fallback glyph, never a blank frame. */
    avatarUrl?: string
}

/** Props for {@link ConsultantCard}. */
export interface ConsultantCardProps {
    /** The consultant this tile represents. */
    consultant: ConsultantCardConsultant
    /** Fired with {@link ConsultantCardConsultant.id} when the visitor opens this consultant's profile. */
    onOpen: (id: string) => void
    /**
     * `true` → `Image` and every `Typography` line switch to their own shimmer,
     * and the tile stops accepting presses (there is no id to open yet). See
     * the file header for why this does NOT flow into `.Pressable`'s own flag.
     */
    isSkeleton?: boolean
}

/**
 * ONE consultant tile. See the file header for the full contract.
 *
 * @param props - {@link ConsultantCardProps}
 */
const ConsultantCard = ({
    consultant,
    onOpen,
    isSkeleton = false,
}: ConsultantCardProps) => {
    const { id, fullName, jobTitle, companyTitle, description, avatarUrl } = consultant

    const nameRow = (
        <StackV gap={1} isSkeleton={isSkeleton} items={[
            () => (
                <Typography
                    size="sm"
                    weight="medium"
                    truncate
                    isSkeleton={isSkeleton}
                    text={fullName}

                />
            ),
            ...(isSkeleton || jobTitle ? [() => (
                <Typography
                    size="xs"
                    color="muted"
                    truncate
                    isSkeleton={isSkeleton}
                    text={jobTitle}

                />
            )] : []),
        ]} />
    )

    return (
        <div>
            <div>
                <SurfaceCard
                    onPress={() => onOpen(id)}
                    isDisabled={isSkeleton}

                    body={() => (
                        <StackV
                            gap={4}
                            isSkeleton={isSkeleton}
                            items={[
                                () => (
                                    <div>
                                        <Image
                                            src={avatarUrl}
                                            alt={fullName}
                                            ratio="square"
                                            radius="lg"
                                            isSkeleton={isSkeleton}

                                        />
                                    </div>
                                ),
                                () => nameRow,
                                ...(isSkeleton || companyTitle
                                    ? [
                                        () => (
                                            <Typography
                                                size="xs"
                                                color="muted"
                                                truncate
                                                prefixIcon={BuildingsIcon}
                                                isSkeleton={isSkeleton}
                                                text={companyTitle}

                                            />
                                        ),
                                    ]
                                    : []),
                                ...(isSkeleton || description
                                    ? [
                                        () => (
                                            <Typography
                                                size="sm"
                                                color="muted"
                                                lineClamp={2}
                                                isSkeleton={isSkeleton}
                                                text={description}

                                            />
                                        ),
                                    ]
                                    : []),
                            ]}
                        />
                    )}
                />
            </div>
        </div>
    )
}

export { ConsultantCard }

import React from "react"
import {
    SearchAutocomplete,
    type SearchAutocompleteItem,
} from "@sb-components/atoms/forms/SearchAutocomplete/SearchAutocomplete"

/**
 * `ConsultantDirectoryCompanySearch` — a typed, debounced deep-link to one
 * recruiting company's page, sitting above the consultant grid on the directory
 * screen. It is not a grid filter: there is no server-side search over
 * consultants, only a company suggester, so it jumps straight to a known
 * company page. `isLoadingSuggestions` swaps the popover's content.
 */

/** One company the ES suggester matched against the typed query. */
export interface ConsultantCompanySuggestion {
    /** Stable company id — the payload handed back through `onSelectCompany`. */
    id: string
    /** Company display name, already localized/formatted by the caller. */
    label: string
}

/** Props for {@link ConsultantDirectoryCompanySearch}. */
export interface ConsultantDirectoryCompanySearchProps {
    /** Current text in the search field (controlled). */
    query: string
    /** Fired with the new query on every keystroke; the screen owns debouncing. */
    onQueryChange: (value: string) => void
    /** Company matches for the current query, already fetched by the screen. */
    suggestions: Array<ConsultantCompanySuggestion>
    /** `true` while the screen is waiting on the ES company-suggester. */
    isLoadingSuggestions?: boolean
    /** Fired with the picked company's id; the screen owns the route push. */
    onSelectCompany: (companyId: string) => void
}

/**
 * The company deep-link search row atop the consultant directory. See the file
 * header for why this is a jump-to-company control and not a grid filter.
 *
 * @param props - {@link ConsultantDirectoryCompanySearchProps}
 */
const ConsultantDirectoryCompanySearch = ({
    query,
    onQueryChange,
    suggestions,
    isLoadingSuggestions = false,
    onSelectCompany,
}: ConsultantDirectoryCompanySearchProps) => {
    const items: Array<SearchAutocompleteItem> = suggestions.map((company) => ({
        id: company.id,
        label: company.label,
    }))

    return (
        <div>
            <div>
                <SearchAutocomplete
                    items={items}
                    inputValue={query}
                    onInputChange={onQueryChange}
                    onSelect={onSelectCompany}
                    isLoading={isLoadingSuggestions}
                    // Owned wording: this field jumps to ONE company, it does not filter
                    // the grid below it — the placeholder has to say so or a visitor will
                    // type a role/skill and get nothing back.
                    placeholder="Search for a hiring company by name…"
                    emptyLabel="No companies found"

                />
            </div>
        </div>
    )
}

export { ConsultantDirectoryCompanySearch }

import React from "react"
import { AsyncContent, type AsyncContentEmptyProps } from "@sb-components/composites/async/AsyncContent/AsyncContent"
import { Grid, type GridItem } from "@sb-components/frames/Grid/Grid"
import { StackV } from "@sb-components/frames/Stack/Stack"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { ConsultantCard, type ConsultantCardConsultant } from "@sb-components/starci/blocks/consultant/ConsultantCard/ConsultantCard"

/**
 * `ConsultantDirectoryGrid` — the consultant directory's browse surface: a
 * match count above the cards, across the loading → empty → content lifecycle.
 * `AsyncContent` owns the branch switch, `Grid` the responsive track,
 * `ConsultantCard` one tile. The count line renders inside the `content` branch
 * only, beside real cards.
 */

/** Props for {@link ConsultantDirectoryGrid}. */
export interface ConsultantDirectoryGridProps {
    /**
     * The current page's consultants, already sorted by the caller. `undefined`
     * ⇒ the list has not resolved yet (see {@link ConsultantDirectoryGridProps.isLoading}).
     */
    consultants?: Array<ConsultantCardConsultant>
    /**
     * How many consultants the directory lists in total. `undefined` ⇒ the
     * count line does not render yet (see file header's judgement call).
     */
    count?: number
    /**
     * `true` while the consultant list's own fetch has not resolved. Passed
     * straight to `AsyncContent` — this block never infers it from
     * `consultants` itself (see file header).
     */
    isLoading: boolean
    /** Fired with a consultant's id when their card is pressed. */
    onOpenConsultant: (id: string) => void
    /** The empty-state message, already localized by the caller (see file header for why this stays a caller prop). */
    emptyTitle: string
    /** Accessible name for the directory region — the block has no visible heading of its own. */
    ariaLabel: string
}

/** How many placeholder tiles mirror the grid while the list hasn't resolved — ported from the real `ConsultantGrid`'s `SKELETON_COUNT`. */
const SKELETON_TILE_COUNT = 6

/** Skeleton tiles pass this as `onOpen` — `ConsultantCard.isSkeleton` disables its own press, so it never fires. */
const NOOP = () => {}

/** The block's own wording for the count line (§14d.1) — the caller only ever hands over a bare number. */
const countLabel = (count: number): string => `${count} consultants`

/**
 * The consultant directory's browse surface. See the file header for the full
 * contract and why the count line only shows beside real cards.
 *
 * @param props - {@link ConsultantDirectoryGridProps}
 */
const ConsultantDirectoryGrid = ({
    consultants,
    count,
    isLoading,
    onOpenConsultant,
    emptyTitle,
    ariaLabel,
}: ConsultantDirectoryGridProps) => {
    // Resolved-but-zero, matching the real `ConsultantGrid`'s Redux-driven gating
    // (`!consultants` = loading, `sortedConsultants.length === 0` = empty).
    const isEmpty = !isLoading && (consultants?.length ?? 0) === 0

    const skeletonTiles: Array<GridItem> = Array.from({ length: SKELETON_TILE_COUNT }, (_unused, index) => ({
        key: `skeleton-${index}`,
        content: () => (
            <ConsultantCard
                consultant={{ id: `skeleton-${index}`, fullName: "" }}
                onOpen={NOOP}
                isSkeleton


            />
        ),
    }))

    const tiles: Array<GridItem> = (consultants ?? []).map((consultant) => ({
        key: consultant.id,
        content: () => (
            <ConsultantCard
                consultant={consultant}
                onOpen={onOpenConsultant}


            />
        ),
    }))

    const emptyContent: AsyncContentEmptyProps = {
        title: emptyTitle,

    }

    return (
        <div role="region" aria-label={ariaLabel}>
            <AsyncContent
                isLoading={isLoading}
                skeleton={() => (
                    <div>
                        <Grid columns={{ base: 1, sm: 2, lg: 3 }} principle="content-row"
                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                            items={skeletonTiles}  />
                    </div>
                )}
                isEmpty={isEmpty}
                emptyContent={emptyContent}

                content={() => (
                    <StackV gap={4} principle="group-boundary"
                        explain="Section group spacing — not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
                        items={[
                            ...(count !== undefined ? [() => (
                                <Typography size="sm" color="muted" text={countLabel(count)} />
                            )] : []),
                            () => (
                                <div>
                                    <Grid columns={{ base: 1, sm: 2, lg: 3 }} principle="content-row"
                                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                        items={tiles}  />
                                </div>
                            ),
                        ]} />
                )}
            />
        </div>
    )
}

export { ConsultantDirectoryGrid }

import React from "react"
import { Breadcrumbs } from "@sb-components/atoms/navigation/Breadcrumbs/Breadcrumbs"
import { PageHeader } from "@sb-components/composites/layout/Page/Page"

/**
 * `ConsultantDirectoryHeader` — the directory-identity cluster atop the
 * consultant directory screen: a course-scoped breadcrumb trail, a title, and an
 * optional one-line description. A thin `PageHeader` cluster with no read-state
 * chip or meta row. `description` is optional; `isSkeleton` swaps every atom for
 * its mirror. The breadcrumb trail always exists.
 */

/** One breadcrumb link — plain data, the block builds the atom from it. */
export interface ConsultantDirectoryHeaderCrumb {
    /** Stable React key. */
    key: string
    /** Display label. */
    label: string
    /** Has a handler → the crumb is pressable; the current page leaves it out. */
    onPress?: () => void
}

/** Props for {@link ConsultantDirectoryHeader}. */
export interface ConsultantDirectoryHeaderProps {
    /** Breadcrumb trail as DATA — the block builds `Breadcrumbs` itself (course → consultant directory). */
    breadcrumbItems?: Array<ConsultantDirectoryHeaderCrumb>
    /** Directory title. */
    title: string
    /** One-sentence summary of what the directory lists. */
    description?: string
    /**
     * `true` → every composed atom switches to its own shimmer. The flag FLOWS
     * DOWN into the real atoms rather than building a parallel skeleton tree
     * (§12c).
     */
    isSkeleton?: boolean
}

/**
 * The directory identity cluster at the top of the consultant directory
 * screen. See the file header for the full contract and why this is a thin
 * sibling of `ContentHeader`/`FoundationsHeader` rather than an edit of
 * either.
 *
 * @param props - {@link ConsultantDirectoryHeaderProps}
 */
const ConsultantDirectoryHeader = ({
    breadcrumbItems,
    title,
    description,
    isSkeleton = false,
}: ConsultantDirectoryHeaderProps) => {
    return (
        <div>
            <PageHeader

                isSkeleton={isSkeleton}
                breadcrumb={() =>
                    isSkeleton || breadcrumbItems?.length ? (
                        <div className="w-fit">
                            <Breadcrumbs
                                collapseOnMobile
                                collapseFrom={4}
                                items={breadcrumbItems ?? []}
                                isSkeleton={isSkeleton}
                            />
                        </div>
                    ) : undefined
                }
                title={title}
                description={description}
            />
        </div>
    )
}

