import React from "react"
import { BuildingsIcon, LockIcon } from "@phosphor-icons/react"
import { Image } from "@sb-components/atoms/media/Image/Image"
import { Typography, type TypographyIcon } from "@sb-components/atoms/text/Typography/Typography"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { Callout } from "@sb-components/composites/feedback/Callout/Callout"
import { StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `ConsultantProfileBody` — the full detail content of one consultant's profile:
 * photo, name+role, a pressable company row, the full bio, and either real
 * contact links once unlocked or a locked callout with a way to unlock them.
 * The detail sibling of `ConsultantCard`. `contactUnlocked` only changes which
 * content fills the last slot, not the outer frame.
 */

/** One way to reach this consultant once contact is unlocked — plain navigable data. */
export interface ConsultantProfileBodyContactLink {
    /** Stable React key. */
    key: string
    /** Display label, e.g. "hoa.nguyen@techcorp.vn" or "090 123 4567". */
    label: string
    /** Where the link goes — `mailto:`/`tel:`/`https:` etc. The atom renders it, never fetches it. */
    href: string
    /** Optional leading glyph (mail/phone/chat) as a COMPONENT, not JSX. */
    icon?: TypographyIcon
}

/** One consultant's full profile — plain data, the block builds the detail view from it. */
export interface ConsultantProfileBodyConsultant {
    /** Full name — the profile's accessible heading. */
    fullName: string
    /** Role/title at their company. Row disappears when absent. */
    jobTitle?: string
    /** Company name. The company row disappears when absent. */
    companyTitle?: string
    /** Full bio — rendered in full here, unlike `ConsultantCard`'s clamped teaser. */
    description?: string
    /** Photo URL. Empty/missing → `Image`'s own fallback glyph, never a blank frame. */
    avatarUrl?: string
    /** `true` → real `contactLinks` are shown. `false` → the locked callout is shown instead. */
    contactUnlocked: boolean
    /** Ways to reach this consultant. Only read when `contactUnlocked` is `true`. */
    contactLinks?: Array<ConsultantProfileBodyContactLink>
}

/** Props for {@link ConsultantProfileBody}. */
export interface ConsultantProfileBodyProps {
    /** The consultant whose profile this fills. */
    consultant: ConsultantProfileBodyConsultant
    /** Fired when the visitor presses the company row. Row is disabled without it. */
    onOpenCompany?: () => void
    /** Fired from the locked callout's CTA. No CTA renders without it. */
    onImproveCv?: () => void
    /**
     * `true` → `Image` and every `Typography` line switch to their own shimmer, the
     * company button is disabled, and the contact fork shows a neutral shimmer
     * instead of picking a branch (see file header). There is no id to open yet.
     */
    isSkeleton?: boolean
}

/** Fixed copy for the locked-contact callout — block-owned wording (§14d.1), see file header. */
const LOCKED_TITLE = "Contact is locked"
const LOCKED_DESCRIPTION = "Improve your CV to unlock this consultant's contact information."
const LOCKED_CTA_LABEL = "Improve CV"

/**
 * The full profile-detail content for one consultant. See the file header for
 * the full contract, the fork between `ConsultantCard`'s tile shape and this
 * one, and the judgment calls behind the contact fork.
 *
 * @param props - {@link ConsultantProfileBodyProps}
 */
const ConsultantProfileBody = ({
    consultant,
    onOpenCompany,
    onImproveCv,
    isSkeleton = false,
}: ConsultantProfileBodyProps) => {
    const { fullName, jobTitle, companyTitle, description, avatarUrl, contactUnlocked, contactLinks } = consultant

    const nameRow = (
        <StackV gap={1} align="center" principle="name-handle"
            explain="Display name with handle — not title-subtitle, because the second line is an identity handle rather than a subtitle."
            isSkeleton={isSkeleton} items={[
                () => (
                    <Typography
                        size="h4"
                        weight="bold"
                        align="center"
                        isSkeleton={isSkeleton}
                        text={fullName}

                    />
                ),
                ...(isSkeleton || jobTitle ? [() => (
                    <Typography
                        size="sm"
                        color="muted"
                        align="center"
                        isSkeleton={isSkeleton}
                        text={jobTitle}

                    />
                )] : []),
            ]} />
    )

    // identity: centered photo, name+role, pressable company row
    const identity = (
        <StackV gap={4} align="center" principle="card-caption"
            explain="Holds caption text under card media so the caption stays attached to the image above it."
            isSkeleton={isSkeleton} items={[
                () => (
                    <div className="w-28">
                        <Image
                            src={avatarUrl}
                            alt={fullName}
                            ratio="square"
                            radius="full"
                            isSkeleton={isSkeleton}

                        />
                    </div>
                ),
                () => nameRow,
                ...(isSkeleton || companyTitle ? [() => (
                    <Button
                        isSkeleton={isSkeleton}
                        variant="secondary"
                        size="sm"
                        label={companyTitle ?? ""}
                        prefixIcon={BuildingsIcon}
                        onPress={onOpenCompany}
                        isDisabled={isSkeleton || !onOpenCompany}

                    />
                )] : []),
            ]} />
    )

    // contact fork — see file header for why loading shimmers neutrally
    const contactFork = isSkeleton ? (
        <StackV gap={2} isSkeleton={isSkeleton} items={[
            () => <Typography size="sm" isSkeleton />,
            () => <Typography size="sm" isSkeleton />,
        ]} />
    ) : contactUnlocked ? (
        <StackV gap={2} isSkeleton={isSkeleton} items={(contactLinks ?? []).map((link) => () => (
            <Typography
                size="sm"
                isLink
                href={link.href}
                prefixIcon={link.icon}
                text={link.label}

            />
        ))} />
    ) : (
        <Callout
            status="warning"
            icon={LockIcon}
            title={LOCKED_TITLE}
            description={LOCKED_DESCRIPTION}
            actionLabel={onImproveCv ? LOCKED_CTA_LABEL : undefined}
            onAction={onImproveCv}


        />
    )

    return (
        <StackV
            gap={6}
            isSkeleton={isSkeleton}
            identity={{ tier: "block", component: "ConsultantProfileBody" }}
            items={[
                () => identity,
                // full bio — no clamp, unlike ConsultantCard's directory teaser
                ...(isSkeleton || description ? [() => (
                    <Typography
                        size="sm"
                        color="muted"
                        isSkeleton={isSkeleton}
                        text={description}

                    />
                )] : []),
                () => contactFork,
            ]}
        />
    )
}

export { ConsultantProfileBody }

import React from "react"
import { SurfaceCardNested, type SurfaceCardNestedSection } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { AsyncContent, type AsyncContentErrorProps } from "@sb-components/composites/async/AsyncContent/AsyncContent"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"

/**
 * `ChangelogList` — the dashboard right-rail "What's new" list: dated rows with
 * an optional category, a title that links to the entry when it has a
 * destination, and an optional one-line body. `SurfaceCardNested` owns the
 * card-in-card frame; `AsyncContent` owns the error/loading/empty/content
 * switch. `isLoading` and `error` each swap the whole region; an empty
 * `entries` array renders nothing.
 */

/** Category of a changelog entry — mirrors `ChangelogCategory` (backend-sourced enum). */
export type ChangelogCategory = "feature" | "fix" | "announcement"

/** One changelog row — plain DATA; the block builds the meta line, link target and body styling. */
export interface ChangelogListEntry {
    /** Stable id — the React key. */
    id: string
    /** Headline. */
    title: string
    /** Short body under the title. Row has no third line when absent. */
    body?: string | null
    /** Drives the meta line's trailing label via {@link CATEGORY_LABEL}. Row has no category text when absent. */
    category?: ChangelogCategory | null
    /** ISO publish date — the block formats it (`vi-VN`). */
    publishedAt: string
    /** "Read more" destination. Present → the whole row becomes a link (see file header). */
    linkUrl?: string | null
}

/** Props for {@link ChangelogList}. */
export interface ChangelogListProps {
    /** The recent changelog entries, newest first. REQUIRED — see file header §R0. */
    entries: Array<ChangelogListEntry>
    /** `true` → the list's own fetch is in flight; own LEAF (see file header). */
    isLoading: boolean
    /** Truthy → the list falls to its error message; own LEAF (beats loading/empty). */
    error?: unknown
    /** Fired when the reader presses "Retry" on the error branch. Omit to render the error with no action. */
    onRetry?: () => void
    /** Extra classes on the root. */
    className?: string
}

/** The block's own section label — matches `dashboard.changelog` in `vi.json`. */
const TITLE = "What's new"

/** category → meta-line label — the block's own vocabulary (§14d.1), never handed in by a caller. */
const CATEGORY_LABEL: Record<ChangelogCategory, string> = {
    feature: "Feature",
    fix: "Fix",
    announcement: "Announcement",
}

const ERROR_TITLE = "Couldn't load the changelog. Please try again."
const RETRY_LABEL = "Retry"

/** How many placeholder rows mirror the list while `entries` hasn't landed yet. */
const SKELETON_ROW_COUNT = 4

/** Formats an ISO date the same way across every row — the block's one date rule. */
const formatDate = (iso: string) => new Date(iso).toLocaleDateString("vi-VN")

/** One row's meta line: the formatted date, plus the category label when present. */
const metaLine = (entry: ChangelogListEntry): string => {
    const category = entry.category ? CATEGORY_LABEL[entry.category] : null
    return category ? `${formatDate(entry.publishedAt)} · ${category}` : formatDate(entry.publishedAt)
}

/** Placeholder rows for the loading mirror — no data, no press target (§12c). */
const skeletonItems = (): Array<SurfaceCardNestedSection> =>
    Array.from({ length: SKELETON_ROW_COUNT }, (_unused, index) => ({
        key: `skeleton-${index}`,
        eyebrow: "x",
        title: "x",
        content: () => <Typography size="sm" color="muted" isSkeleton text="x" />,
    }))

/** One real row: meta line, title (linked when `linkUrl` is set), optional body. */
const entryItem = (entry: ChangelogListEntry): SurfaceCardNestedSection => ({
    key: entry.id,
    eyebrow: metaLine(entry),
    title: entry.title,
    content: entry.body ? () => <Typography size="sm" color="muted" text={entry.body} /> : undefined,
    href: entry.linkUrl ?? undefined,
})

/**
 * The dashboard "What's new" rail. See the file header for the full contract,
 * the leaf boundary reasoning and the judgement calls (meta-line text instead
 * of a chip, whole-row link, no outer label wrapper, plain-text body).
 *
 * @param props - {@link ChangelogListProps}
 */
const ChangelogList = ({
    entries,
    isLoading,
    error,
    onRetry,
    className,
}: ChangelogListProps) => {
    const errorContent: AsyncContentErrorProps = {
        title: ERROR_TITLE,
        onRetry,
        retryLabel: onRetry ? RETRY_LABEL : undefined,

    }

    return (
        <div className={className}>
            <AsyncContent
                isLoading={isLoading}
                skeleton={() => (
                    <SurfaceCardNested
                        title={TITLE}
                        items={skeletonItems()}
                        isSkeleton
                    />
                )}
                isEmpty={entries.length === 0}
                error={error}
                errorContent={errorContent}
                content={() => (
                    <SurfaceCardNested
                        title={TITLE}
                        items={entries.map(entryItem)}
                    />
                )}
            />
        </div>
    )
}

export { ChangelogList }

import React from "react"
import { ContinueCardItem } from "@sb-components/starci/blocks/learn/ContinueCard/ContinueCard"
import { AsyncContent } from "@sb-components/composites/async/AsyncContent/AsyncContent"
import { Grid, type GridItem } from "@sb-components/frames/Grid/Grid"
import { Button } from "@sb-components/atoms/buttons/Button/Button"

/**
 * `ContinueLearning` (dashboard) — the "Continue learning" slot: up to 3 resume
 * targets (lessons lead, at most one in-progress challenge as a nudge), or an
 * onboarding CTA when there is nothing to resume. Three leaves: `Content`
 * (1–3 tiles in a `Grid`), `Empty` (`AsyncContentEmpty`, wording forks on
 * `hasCourses`), and `Loading` (a 3-tile skeleton grid).
 */

/** Resume target kind — the ONLY thing that changes the card's subtitle wording. */
export type ContinueLearningItemKind = "lesson" | "challenge"

/** One "pick up where you left off" resume target. */
export interface ContinueLearningItem {
    /** Opaque id — the block never resolves it itself, that's the caller's job on press. */
    id: string
    /** Title to show — already the display string, no further formatting here. */
    title: string
    /** Lesson vs. challenge — drives the subtitle word only. */
    kind: ContinueLearningItemKind
}

/** Props for {@link ContinueLearning}. */
export interface ContinueLearningProps {
    /** Resume targets, already capped + de-duplicated by the caller (§14d.1 — this block does not slice). */
    items: ReadonlyArray<ContinueLearningItem>
    /** `true` → the viewer has joined at least one course (decides the empty leaf's wording). */
    hasCourses: boolean
    /** `true` while the underlying leaf queries are loading (feeds the Loading leaf). */
    isLoading: boolean
    /** Fired with an item's `id` when its card is pressed. */
    onSelectItem: (id: string) => void
    /** Fired when the onboarding CTA is pressed (both empty wordings share one action). */
    onBrowseCourses: () => void
}

/** Subtitle word per kind — the block's own wording (§14d.1: design never sees "lesson"/"challenge"). */
const KIND_LABEL: Record<ContinueLearningItemKind, string> = {
    lesson: "Currently reading",
    challenge: "Challenge in progress",
}

/** Placeholder tiles for the guessed 3-card skeleton grid (§12c) — never carry a press handler. */
const SKELETON_ITEMS: Array<ContinueLearningItem> = [
    { id: "skeleton-0", title: "", kind: "lesson" },
    { id: "skeleton-1", title: "", kind: "lesson" },
    { id: "skeleton-2", title: "", kind: "lesson" },
]

/**
 * The dashboard's "Continue learning" content. See the file header for the full
 * leaf/state contract.
 *
 * @param props - {@link ContinueLearningProps}
 */
const ContinueLearning = ({
    items,
    hasCourses,
    isLoading,
    onSelectItem,
    onBrowseCourses,
}: ContinueLearningProps) => {
    const usingPlaceholders = isLoading && items.length === 0
    const source = usingPlaceholders ? SKELETON_ITEMS : items

    const tiles: Array<GridItem> = source.map((item) => ({
        key: item.id,
        content: () => (
            <ContinueCardItem
                isSkeleton={usingPlaceholders}
                title={item.title}
                subtitle={KIND_LABEL[item.kind]}
                onPress={usingPlaceholders ? undefined : () => onSelectItem(item.id)}
            />
        ),
    }))

    return (
        <div>
            <AsyncContent
                isLoading={isLoading && items.length === 0}
                skeleton={() => <Grid items={tiles} columns={{ base: 1, sm: 2, lg: 3 }} principle="content-row"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                />}
                isEmpty={!isLoading && items.length === 0}
                emptyContent={{
                    title: hasCourses
                        ? "You haven't read any lessons or attempted any challenges yet."
                        : "You haven't joined any courses yet.",
                    description: hasCourses
                        ? "Start a lesson so it shows up here under \"Continue learning\"."
                        : undefined,
                    action: () => (
                        <Button
                            variant="primary"
                            size="sm"
                            label="Browse courses"
                            onPress={onBrowseCourses}

                        />
                    ),

                }}
                content={() => <Grid items={tiles} columns={{ base: 1, sm: 2, lg: 3 }} principle="content-row"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                />}
            />
        </div>
    )
}

export { ContinueLearning }

import React from "react"
import {
    SurfaceCardCrossList,
    type SurfaceCardCrossListItem,
} from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { AsyncContent } from "@sb-components/composites/async/AsyncContent/AsyncContent"
import { StackV } from "@sb-components/frames/Stack/Stack"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { Button } from "@sb-components/atoms/buttons/Button/Button"

/**
 * `DailyQuest` (dashboard) — "Today's quests": a fixed 3-task checklist plus a
 * claim action once every task clears its target. Four async leaves — `Loading`,
 * `Error`, `Empty`, and `Content`, the last forking on claim state: incomplete
 * (prompt), all-done unclaimed (claim button, `isPending` while claiming), or
 * already claimed (chip, no action left).
 */

/** The three fixed daily tasks — closed set, real BE vocabulary (see file header). */
export type DailyQuestTaskKey = "readContent" | "passChallenge" | "reviewFlashcards"

/** One checklist row. */
export interface DailyQuestTask {
    key: DailyQuestTaskKey
    /** Progress made today. */
    current: number
    /** Target to clear the row. */
    target: number
}

/** The full daily-quest entity for one day. */
export interface DailyQuestData {
    /** `true` -> the reward was already claimed today; no further action. */
    claimed: boolean
    /** `true` -> every task has cleared its target (`current >= target`); unlocks the claim button. */
    allDone: boolean
    /** Reward amount, printed inside the claim/prompt wording. */
    reward: number
    /** The checklist rows, in display order. */
    tasks: ReadonlyArray<DailyQuestTask>
}

/** Props for {@link DailyQuest}. */
export interface DailyQuestProps {
    /** The day's quest entity. `null` while genuinely nothing has loaded/resolved yet. */
    quest: DailyQuestData | null
    /** `true` while the quest fetch is in flight (feeds the Loading leaf). */
    isLoading: boolean
    /** Truthy -> the fetch failed (feeds the Error leaf, outranks loading/empty). */
    error?: unknown
    /** Fired when the error leaf's retry button is pressed. */
    onRetry: () => void
    /** Fired when the claim button is pressed (leaf 4b only). */
    onClaim: () => void
    /** `true` -> the claim mutation is in flight (the block's one `pending` state). */
    isClaiming?: boolean
}

/** Row title per task key — the block's own wording (§14d.1). */
const TASK_LABEL: Record<DailyQuestTaskKey, string> = {
    readContent: "Read a lesson",
    passChallenge: "Pass a challenge",
    reviewFlashcards: "Review flashcards",
}

/** One row's text: title (leading) <-> current/target (trailing) — plain text, the composite wraps it in `Typography` itself. */
const rowBody = (task: DailyQuestTask): string => `${TASK_LABEL[task.key]} — ${task.current}/${task.target}`

/**
 * The dashboard's "Today's Quests" content. See the file header for the
 * full leaf/state contract.
 *
 * @param props - {@link DailyQuestProps}
 */
const DailyQuest = ({
    quest,
    isLoading,
    error,
    onRetry,
    onClaim,
    isClaiming = false,
}: DailyQuestProps) => {
    const items: Array<SurfaceCardCrossListItem> = (quest?.tasks ?? []).map((task) => ({
        key: task.key,
        mark: task.current >= task.target ? "check" : "pending",
        text: rowBody(task),

    }))

    // Leaf 4a/4b/4c — the claim state, only meaningful once `quest` exists.
    const claimSlot = quest ? (
        quest.claimed ? (
            <Chip
                tone="success"
                text="Reward claimed"

            />
        ) : quest.allDone ? (
            <Button
                variant="primary"
                size="sm"
                label={`Claim ${quest.reward} coins`}
                isPending={isClaiming}
                onPress={onClaim}


            />
        ) : (
            <Typography
                size="xs"
                color="muted"
                text={`Complete all 3 quests to claim ${quest.reward} coins.`}

            />
        )
    ) : null

    return (
        <div>
            <AsyncContent
                isLoading={quest === null && isLoading}
                skeleton={() => <SurfaceCardCrossList items={[]} isSkeleton skeletonRows={3} />}
                isEmpty={quest === null && !isLoading && !error}
                emptyContent={{
                    title: "No quests for today yet.",
                    onRetry,
                    retryLabel: "Retry",

                }}
                error={quest === null ? error : undefined}
                errorContent={{
                    title: "Couldn't load today's quests.",
                    onRetry,
                    retryLabel: "Retry",

                }}
                content={() => <StackV gap={4} items={[
                    () => <SurfaceCardCrossList items={items} />,
                    () => claimSlot,
                ]} />}
            />
        </div>
    )
}

export { DailyQuest }

import React from "react"
import { type SkeletonProps } from "@sb-components/frames/_slot"
import { AsyncContent } from "@sb-components/composites/async/AsyncContent/AsyncContent"
import { SurfaceCard, SurfaceCardList, type SurfaceCardListItem } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { UserCell } from "@sb-components/composites/lists/UserCell/UserCell"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * BLOCK — `WeeklyChallengeCard`: "Weekly Challenge" — the featured challenge of
 * the week. See the component's own file header for the full contract; this
 * file only adds the states.
 *
 *  LEAF by STRUCTURE (§14d.2): whether the viewer already passed, already
 * claimed, or the leaderboard is short, are all DATA conditions of the same
 * status row/list — never a different shape this block draws — so this block
 * has exactly ONE leaf ("Content"), the same shape `LeaderboardBoard`'s single
 * `Board` leaf uses.
 */

/** One leaderboard row: a finisher who already passed this week's challenge. */
export interface WeeklyChallengeLeaderboardEntry {
    /** Stable React key — the finisher's username. */
    key: string
    /** Account username; drives the avatar fallback (same contract as {@link UserCell}). */
    username: string
    /** Uploaded avatar URL, or `null`/omitted — a generated default is shown instead. */
    avatar?: string | null
    /** Already-worded "x ago" label (e.g. "5 minutes ago"). */
    passedAtLabel: string
}

/** The currently featured weekly-challenge event. */
export interface WeeklyChallengeData {
    /** Title of the featured challenge. */
    title: string
    /** Fired from the title AND the "Try it now" prompt — the caller already resolved the route. Omit when not routable. */
    onOpenChallenge?: () => void
    /** Already-worded countdown to the event's close (e.g. "2 days 6 hours left"). Omit while unknown. */
    endsInLabel?: string
    /** Whether the viewer has already passed the challenge this week. */
    viewerPassed: boolean
    /** Whether the viewer already claimed the reward this week. Ignored unless `viewerPassed`. */
    claimed: boolean
    /** Coin reward for claiming; `null` when the viewer hasn't passed yet. */
    coinReward: number | null
    /** `true` → the claim mutation is in flight — disables + spins the claim button. */
    isClaiming?: boolean
    /** Fired when the viewer presses the claim button. Required whenever `viewerPassed && !claimed`. */
    onClaim?: () => void
    /** Total number of users who have passed so far. */
    passedCount: number
    /** Top finishers (already capped by the caller), newest first. */
    leaderboard: Array<WeeklyChallengeLeaderboardEntry>
}

/** Props for {@link WeeklyChallengeCard}. */
export interface WeeklyChallengeCardProps {
    /** True while the first load is running — {@link AsyncContent}'s loading branch. */
    isLoading: boolean
    /** True (once loaded) → no challenge event is currently active. */
    isEmpty: boolean
    /** Truthy → the snapshot failed to load. Pass SWR's `error`. */
    error?: unknown
    /** Retry handler for the error branch. */
    onRetry: () => void
    /** The featured challenge. Required once loaded and non-empty. */
    data?: WeeklyChallengeData
    /** `true` → every atom this block owns switches to its own shimmer (data already loaded). */
    isSkeleton?: boolean
}

/** The title: a routable link when `onOpenChallenge` is set, plain bold text otherwise. */
const titleText = (data: WeeklyChallengeData, isSkeleton: boolean) =>
    data.onOpenChallenge ? (
        <Typography
            size="sm"
            isLink
            isSkeleton={isSkeleton}
            onPress={data.onOpenChallenge}
            text={data.title}

        />
    ) : (
        <Typography
            size="sm"
            weight="bold"
            isSkeleton={isSkeleton}
            text={data.title}

        />
    )

/** Right side of the status row: claimed chip, a pending claim button, or a "try now" prompt. */
const statusSlot = (data: WeeklyChallengeData, isSkeleton: boolean) => {
    if (isSkeleton) {
        return <Chip isSkeleton />
    }
    if (!data.viewerPassed) {
        return data.onOpenChallenge ? (
            <Typography
                size="xs"
                isLink
                onPress={data.onOpenChallenge}
                text="Try it now"

            />
        ) : null
    }
    if (data.claimed) {
        return (
            <Chip tone="success" text="Completed" />
        )
    }
    return (
        <Button
            variant="primary"
            size="sm"
            isPending={data.isClaiming}
            onPress={data.onClaim}
            label={`Claim ${data.coinReward ?? 0} coins`}
        />
    )
}

/** Builds one finisher's free-form `SurfaceCardList` content: the unchanged `UserCell`. */
const finisherItem = (entry: WeeklyChallengeLeaderboardEntry, isSkeleton: boolean): SurfaceCardListItem => ({
    key: entry.key,
    content: () => (
        <div>
            <UserCell
                username={entry.username}
                avatar={entry.avatar}
                trailing={({ isSkeleton: slotSkeleton }: SkeletonProps) => (
                    <Typography
                        size="xs"
                        color="muted"
                        isSkeleton={slotSkeleton}
                        text={slotSkeleton ? undefined : entry.passedAtLabel}

                    />
                )}
                isSkeleton={isSkeleton}

            />
        </div>
    ),
})

/** Fixed-shape placeholder rendered while {@link WeeklyChallengeCardProps.isLoading} — no real event exists yet. */
const LOADING_DATA: WeeklyChallengeData = {
    title: "",
    viewerPassed: false,
    claimed: false,
    coinReward: null,
    passedCount: 0,
    leaderboard: Array.from({ length: 3 }, (_, index) => ({ key: `loading-${index}`, username: "", passedAtLabel: "" })),
}

/** Props for the internal {@link Content} tree — reused for both the real render and the loading skeleton. */
interface ContentProps {
    data: WeeklyChallengeData
    isSkeleton: boolean
}

const Content = ({ data, isSkeleton }: ContentProps) => {
    const statusRow = (
        <StackH gap={4} principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            justify="between" align="center" items={[
                () => (data.endsInLabel != null || isSkeleton ? (
                    <Typography
                        size="xs"
                        color="muted"
                        isSkeleton={isSkeleton}
                        text={isSkeleton ? undefined : data.endsInLabel}

                    />
                ) : <span />),
                () => statusSlot(data, isSkeleton),
            ]} />
    )

    return (
        <StackV gap={4} items={[
            () => titleText(data, isSkeleton),
            () => statusRow,
            () => (
                <Typography
                    size="xs"
                    color="muted"
                    isSkeleton={isSkeleton}
                    text={isSkeleton ? undefined : `${data.passedCount} people have passed`}

                />
            ),
            ...(data.leaderboard.length > 0 ? [() => (
                <div>
                    <SurfaceCardList
                        variant="nested"
                        items={data.leaderboard.map((entry) => finisherItem(entry, isSkeleton))}

                    />
                </div>
            )] : []),
        ]} />
    )
}

/**
 * "Weekly Challenge" — the featured weekly-challenge card. See the file header
 * for the full contract.
 *
 * @param props - {@link WeeklyChallengeCardProps}
 */
const WeeklyChallengeCard = ({
    isLoading,
    isEmpty,
    error,
    onRetry,
    data,
    isSkeleton = false,
}: WeeklyChallengeCardProps) => (
    <SurfaceCard
        identity={{ tier: "block", component: "WeeklyChallengeCard" }}
        label="Weekly Challenge"


        body={() => (
            <AsyncContent
                isLoading={isLoading}
                skeleton={() => <Content data={LOADING_DATA} isSkeleton />}
                isEmpty={isEmpty}
                emptyContent={{
                    title: "No challenge is currently active",
                    description: "Check back next week for a new challenge.",
                }}
                error={error}
                errorContent={{
                    title: "Couldn't load the weekly challenge",
                    description: "Try again for the latest info.",
                    onRetry,
                    retryLabel: "Retry",
                }}
                content={() => (data ? (
                    <Content data={data} isSkeleton={isSkeleton} />
                ) : null)}
            />
        )}
    />
)

