import React from "react"
import { Skeleton as HeroSkeleton } from "@heroui/react"
import {
    BookOpenIcon,
    CardsIcon,
    CodeIcon,
    FlagIcon,
    FlameIcon,
    PuzzlePieceIcon,
    type Icon as PhosphorIcon,
} from "@phosphor-icons/react"
import { AsyncContent } from "@sb-components/composites/async/AsyncContent/AsyncContent"
import { SurfaceCard } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { StatGridCard, type StatGridCardItem } from "@sb-components/composites/stats/StatGridCard/StatGridCard"
import { ProgressMeter } from "@sb-components/composites/stats/ProgressMeter/ProgressMeter"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * BLOCK — `WeeklyGoals`: "Weekly Goals" — the composite summary + six-metric
 * breakdown. See the component's own file header for the full contract; this
 * file only adds the states.
 *
 *  LEAF by STRUCTURE (§14d.2): the six metrics never change the SHAPE of the
 * tree, only the numbers inside it, so this block has exactly ONE leaf
 * ("Content") — loading / error / content are states of that one leaf, the
 * same shape `ChallengeScoreCard`'s single leaf uses. No `isEmpty` state:
 * `items` is always the fixed six-metric set (see the component file header).
 */

/** The six weekly metrics this block always renders, in display order (mirrors backend `KpiKey`). */
export type WeeklyGoalKey = "lessons" | "studyDays" | "challenges" | "coding" | "flashcards" | "milestones"

/** One weekly-goal metric: current-week value vs the effective target, plus its coin reward. */
export interface WeeklyGoalItem {
    /** Which metric this row is. */
    key: WeeklyGoalKey
    /** Already-localized metric name (e.g. "Lessons") — screen copy, not owned by this block. */
    label: string
    /** The current-week value. */
    current: number
    /** The learner's custom weekly target; `null` when none set (the block falls back to a sensible default). */
    target: number | null
    /** Coin reward for claiming this metric this week; `null` when no target is set server-side. */
    coinReward: number | null
    /** `true` → this metric's reward can be claimed right now (met + not yet claimed). */
    canClaim: boolean
}

/** Server-computed composite score across every metric — read straight, never recomputed. */
export interface WeeklyGoalsComposite {
    /** Average completion across the six metrics, 0–100. */
    percent: number
    /** Number of metrics already met (current >= effective target). */
    completed: number
    /** Always 6 — the fixed metric count. */
    total: number
}

/** The viewer's weekly-goals snapshot (real shape of `myKpis`). */
export interface WeeklyGoalsData {
    /** All six metrics, in display order. */
    items: Array<WeeklyGoalItem>
    /** Server-computed composite score across every metric — read straight, never recomputed. */
    composite: WeeklyGoalsComposite
    /** Already-worded countdown to the weekly reset (e.g. "3 days 12 hours left"). Omit while unknown. */
    resetInLabel?: string
}

/** Props for {@link WeeklyGoals}. */
export interface WeeklyGoalsProps {
    /** True while the first load is running — {@link AsyncContent}'s loading branch. */
    isLoading: boolean
    /** Truthy → the snapshot failed to load. Pass SWR's `error`. */
    error?: unknown
    /** Retry handler for the error branch. */
    onRetry: () => void
    /** The viewer's weekly-goals snapshot. Required once loaded (no error). */
    data?: WeeklyGoalsData
    /** Sensible default target per metric, used when a metric has no custom `target` set yet. */
    defaultTargets: Record<WeeklyGoalKey, number>
    /** `true` → every atom this block owns switches to its own shimmer (data already loaded). */
    isSkeleton?: boolean
}

/** Phosphor icon per metric key — a pure display constant, decoupled from any editor's own map. */
const KPI_ICON: Record<WeeklyGoalKey, PhosphorIcon> = {
    lessons: BookOpenIcon,
    studyDays: FlameIcon,
    challenges: PuzzlePieceIcon,
    coding: CodeIcon,
    flashcards: CardsIcon,
    milestones: FlagIcon,
}

/** One metric cell's content: icon + label + ratio row, then the meter, then an optional coin hint. */
const goalCellContent = (
    item: WeeklyGoalItem,
    defaultTargets: Record<WeeklyGoalKey, number>,
    isSkeleton: boolean,
) => {
    const Icon = KPI_ICON[item.key]
    const effectiveTarget = item.target ?? defaultTargets[item.key]

    const iconLabel = (
        <StackH gap={2} isSkeleton={isSkeleton} items={[
            () => (isSkeleton ? (
                <HeroSkeleton
                    className="size-5 shrink-0 rounded-full"

                />
            ) : (
                <Icon aria-hidden focusable="false" className="size-5 shrink-0 text-muted" />
            )),
            () => (
                <Typography
                    size="sm"
                    isSkeleton={isSkeleton}
                    text={item.label}

                />
            ),
        ]} />
    )

    const labelRow = (
        <StackH gap={3} principle="sibling-stack"
            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
            justify="between" isSkeleton={isSkeleton} items={[
                () => iconLabel,
                () => (
                    <Typography
                        size="xs"
                        color="muted"
                        tabularNums
                        isSkeleton={isSkeleton}
                        text={isSkeleton ? undefined : `${item.current}/${effectiveTarget}`}

                    />
                ),
            ]} />
    )

    return (
        <StackV gap={3} isSkeleton={isSkeleton} items={[
            () => labelRow,
            () => (
                <ProgressMeter
                    value={item.current}
                    max={effectiveTarget > 0 ? effectiveTarget : 1}
                    isSkeleton={isSkeleton}
                />
            ),
            ...(!isSkeleton && item.coinReward != null ? [() => (
                <Typography
                    size="xs"
                    color={item.canClaim ? "accent" : "muted"}
                    isSkeleton={isSkeleton}
                    text={`+${item.coinReward} coins when met`}

                />
            )] : []),
        ]} />
    )
}

/** Fixed-shape placeholder rendered while {@link WeeklyGoalsProps.isLoading} — six empty cells, no real data yet. */
const loadingItems = (defaultTargets: Record<WeeklyGoalKey, number>): Array<WeeklyGoalItem> =>
    (Object.keys(defaultTargets) as Array<WeeklyGoalKey>).map((key) => ({
        key,
        label: "",
        current: 0,
        target: null,
        coinReward: null,
        canClaim: false,
    }))

/** Props for the internal {@link Content} tree — reused for both the real render and the loading skeleton. */
interface ContentProps {
    items: Array<WeeklyGoalItem>
    composite: WeeklyGoalsComposite
    resetInLabel?: string
    defaultTargets: Record<WeeklyGoalKey, number>
    isSkeleton: boolean
}

const Content = ({ items, composite, resetInLabel, defaultTargets, isSkeleton }: ContentProps) => {
    const summary = isSkeleton
        ? undefined
        : `${composite.percent}% complete (${composite.completed}/${composite.total} goals)${resetInLabel != null ? ` · ${resetInLabel}` : ""}`
    const gridItems: Array<StatGridCardItem> = items.map((item) => ({
        key: item.key,
        content: () => goalCellContent(item, defaultTargets, isSkeleton),
    }))
    return (
        <StackV gap={4} isSkeleton={isSkeleton} items={[
            () => (
                <Typography
                    size="sm"
                    weight="medium"
                    isSkeleton={isSkeleton}
                    text={summary}

                />
            ),
            () => (
                <div>
                    <StatGridCard items={gridItems} />
                </div>
            ),
        ]} />
    )
}

/**
 * "Weekly Goals" — the weekly-goal summary + six-metric breakdown. See the
 * file header for the full contract.
 *
 * @param props - {@link WeeklyGoalsProps}
 */
const WeeklyGoals = ({
    isLoading,
    error,
    onRetry,
    data,
    defaultTargets,
    isSkeleton = false,
}: WeeklyGoalsProps) => (
    <SurfaceCard
        identity={{ tier: "block", component: "WeeklyGoals" }}
        label="Weekly Goals"


        body={() => (
            <AsyncContent
                isLoading={isLoading}
                skeleton={() => (
                    <Content
                        items={loadingItems(defaultTargets)}
                        composite={{ percent: 0, completed: 0, total: 6 }}
                        defaultTargets={defaultTargets}
                        isSkeleton

                    />
                )}
                error={error}
                errorContent={{
                    title: "Couldn't load weekly goals",
                    description: "Retry to see the latest progress.",
                    onRetry,
                    retryLabel: "Retry",
                }}
                content={() => (data ? (
                    <Content
                        items={data.items}
                        composite={data.composite}
                        resetInLabel={data.resetInLabel}
                        defaultTargets={defaultTargets}
                        isSkeleton={isSkeleton}

                    />
                ) : null)}
            />
        )}
    />
)

export { WeeklyGoals }

import React from "react"
import { type SkeletonProps } from "@sb-components/frames/_slot"
import { EnumChip, type EnumChipEntry } from "@sb-components/composites/chips/EnumChip/EnumChip"
import { LinkBack } from "@sb-components/atoms/navigation/Link/Link"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { PageHeader } from "@sb-components/composites/layout/Page/Page"
import { StackH } from "@sb-components/frames/Stack/Stack"

/**
 * `ChallengeHeader` — the challenge-identity cluster atop the solve page: back
 * link, title, optional description, and a meta row carrying score, difficulty,
 * and the learner's pass-fail status. A `PageHeader` cluster. Two chips on
 * purpose — `difficulty` (a property of the challenge) and `status` (a property
 * of the attempt) are separate axes. Whether the status chip draws, and loading,
 * are data.
 */

/** How hard the challenge is — a property of the CHALLENGE, always known. */
export type ChallengeDifficulty = "easy" | "medium" | "hard"

/** Where the learner's own attempt stands — a property of the ATTEMPT, may not exist yet. */
export type ChallengeStatus = "completed" | "failed" | "inProgress"

/** Difficulty → chip presentation. The block owns this table (§14d.1: no caller-supplied color). */
const DIFFICULTY_MAP: Record<ChallengeDifficulty, EnumChipEntry> = {
    easy: { color: "success", label: "Easy" },
    medium: { color: "warning", label: "Medium" },
    hard: { color: "danger", label: "Hard" },
}

/**
 * Attempt status → chip presentation.
 *
 * `failed` gets a leading icon — a failed/not-passed verdict is a "universal"
 * symbol (cross), not decoration. `completed`/`inProgress` stay text-only; extend
 * the day a screen actually asks for their icon too, not preemptively.
 */
const STATUS_MAP: Record<ChallengeStatus, EnumChipEntry> = {
    completed: { color: "success", label: "Passed" },
    failed: { color: "danger", label: "Failed", icon: "cross" },
    inProgress: { color: "warning", label: "In progress" },
}

/** Props for {@link ChallengeHeader}. */
export interface ChallengeHeaderProps {
    /** Fired when the back link is pressed — the block never owns routing, only the affordance. */
    onBackPress: () => void
    /** Full back-link label override; omit to fall back to `LinkBack`'s generic "Back". */
    backLabel?: string
    /** Challenge title. */
    title: string
    /** One-sentence summary of the challenge. */
    description?: string
    /**
     * Points this challenge is worth, in RAW NUMBER — the block adds the unit
     * itself ("{n} points", §14d.1). Omit when no score is defined yet.
     */
    scoreValue?: number
    /**
     * How hard the challenge is. Always required — every challenge has a fixed
     * difficulty tier independent of whether the learner has attempted it yet.
     */
    difficulty: ChallengeDifficulty
    /**
     * The learner's own attempt outcome. Omit when the learner has not
     * attempted this challenge — the status chip is not drawn at all rather
     * than showing a "not started" chip nobody asked for.
     */
    status?: ChallengeStatus
    /**
     * `true` → every composed atom switches to its own shimmer. The flag FLOWS
     * DOWN into the real atoms rather than building a parallel skeleton tree
     * (§12c).
     */
    isSkeleton?: boolean
}

/**
 * The challenge identity cluster at the top of the solve page. See the file
 * header for why it is a sibling of `ContentHeader` rather than an edit of it.
 *
 * @param props - {@link ChallengeHeaderProps}
 */
const ChallengeHeader = ({
    onBackPress,
    backLabel,
    title,
    description,
    scoreValue,
    difficulty,
    status,
    isSkeleton = false,
}: ChallengeHeaderProps) => {
    // ONE row, all with the same `gap={3}`, sitting close together on the left:
    // CHIPS FIRST (status, difficulty) then the score as plain text. No
    // `prefixIcon={TrophyIcon}`, and status comes before difficulty.
    return (
        <div>
            <PageHeader

                isSkeleton={isSkeleton}
                breadcrumb={() =>
                    isSkeleton ? (
                        <Typography size="sm" isSkeleton />
                    ) : (
                        <LinkBack
                            label={backLabel}
                            onPress={onBackPress}

                        />
                    )
                }
                title={title}
                // `PageHeader.description` is now a plain `string` (COMPOSITE-4), so this
                // block no longer wraps it in `RichText` at the call site — the field is
                // already typed/documented as a plain one-sentence summary, never markdown,
                // and `PageHeader` now owns the muted styling + skeleton swap itself.
                description={description}
                meta={({ isSkeleton }: SkeletonProps) =>
                    <StackH
                        gap={3}
                        align="center"
                        principle="chip-row"
                        explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                        isSkeleton={isSkeleton}
                        items={[
                            ...(isSkeleton ? [() => (
                                <EnumChip
                                    value="inProgress"
                                    map={STATUS_MAP}
                                    isSkeleton

                                />
                            )] : status != null ? [() => (
                                <EnumChip
                                    value={status}
                                    map={STATUS_MAP}

                                />
                            )] : []),
                            () => (
                                isSkeleton ? (
                                    <EnumChip
                                        value="easy"
                                        map={DIFFICULTY_MAP}
                                        isSkeleton

                                    />
                                ) : (
                                    <EnumChip
                                        value={difficulty}
                                        map={DIFFICULTY_MAP}

                                    />
                                )
                            ),
                            ...(isSkeleton ? [() => (
                                <Typography size="xs" color="muted" isSkeleton />
                            )] : scoreValue != null ? [() => (
                                <Typography
                                    size="xs"
                                    color="muted"
                                    text={`${scoreValue} points`}

                                />
                            )] : []),
                        ]}
                    />
                }
            />
        </div>
    )
}

export { ChallengeHeader }

"use client"

import { SparkleIcon } from "@phosphor-icons/react"
import { FloatingActionButton } from "@sb-components/composites/buttons/FloatingActionButton/FloatingActionButton"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"

/**
 * `ContentAiFab` — the floating "ask StarCi AI" trigger mounted once by
 * `learn/layout.tsx`, bottom-right over every `/learn/**` route. Composes the
 * `FloatingActionButton` composite, fixing the icon + accessible name. `isOpen`
 * decides whether it renders at all, not its shape. No `isSkeleton` — it is
 * static chrome.
 */

/** Fixed accessible name — see the file header on why this is not a prop. */
const ARIA_LABEL = "Ask StarCi AI"

/** Props for {@link ContentAiFab}. */
export interface ContentAiFabProps {
    /**
     * Fired on press. The layout opens the AI chat rail/drawer in response —
     * this block never touches that state itself (§7: a block never decides
     * what an action means, only that it happened).
     */
    onOpen: () => void
    /**
     * `true` → the AI chat rail-mode panel this FAB opens is already open, so
     * the trigger hides instead of floating redundantly on top of it. Defaults
     * to `false` (visible).
     */
    isOpen?: boolean
    /** Where this sits inside its parent. Appearance is not passable — it is already a prop. */
    classNames?: Array<AllowedClassName>
}

/**
 * The floating "ask StarCi AI" trigger. See the file header for why `isOpen`
 * hides the button rather than disabling it.
 *
 * @param props - {@link ContentAiFabProps}
 */
const ContentAiFab = ({
    onOpen,
    isOpen = false,
    classNames,
}: ContentAiFabProps) => {
    // The panel this button opens is already up — a second trigger floating on
    // top of it would be redundant chrome (and could overlap the panel's own
    // controls), so this leaf has nothing true left to show.
    if (isOpen) {
        return null
    }

    return (
        <div>
            <div>
                <FloatingActionButton
                    onPress={onOpen}
                    ariaLabel={ARIA_LABEL}
                    icon={SparkleIcon}
                    classNames={classNames}
                />
            </div>
        </div>
    )
}

export { ContentAiFab }

import { SparkleIcon } from "@phosphor-icons/react"
import { cn } from "@heroui/react"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { StackH } from "@sb-components/frames/Stack/Stack"

/**
 * `ContentAiSelectionAsk` — the "Ask AI" pill that pops up next to a text
 * selection inside lesson content. Selection tracking and portal positioning are
 * DOM behaviour handled outside the block; it takes an `anchor` point. `isNew`
 * toggles a "New" chip beside the pill.
 */

/** A viewport point (already resolved by the caller — e.g. a selection rect). */
export interface ContentAiSelectionAskAnchor {
    /** Distance from the left edge of the viewport, in pixels. */
    x: number
    /** Distance from the top edge of the viewport, in pixels. */
    y: number
}

/** Props for {@link ContentAiSelectionAsk}. */
export interface ContentAiSelectionAskProps {
    /** Fired when the reader taps the pill — the caller opens the AI side-thread. */
    onOpen: () => void
    /** Where to plant the pill, in viewport coordinates. */
    anchor: ContentAiSelectionAskAnchor
    /** `true` -> carries a "New" chip, for the first releases while readers learn the feature exists. */
    isNew?: boolean
    className?: string
}

/**
 * The "ask AI about this passage" pill, planted at a caller-supplied viewport
 * point. See the file header for the scope cut around selection tracking.
 *
 * @param props - {@link ContentAiSelectionAskProps}
 */
const ContentAiSelectionAsk = ({
    onOpen,
    anchor,
    isNew = false,
    className,
}: ContentAiSelectionAskProps) => (
    // Positioning ONLY on this outer box (§13z exempts the anchor point itself, not a row
    // rhythm) — the `Button`<->`Chip` seam is owned by `StackH` below, never hand-written here.
    <div
        style={{ position: "fixed", left: anchor.x, top: anchor.y }}
        className={cn("z-50 -translate-x-1/2 -translate-y-full", className)}

    >
        <StackH
            gap={2}
            principle="icon-text"
            explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
            align="center"
            items={[
                () => (
                    <Button
                        label="Ask AI"
                        variant="primary"
                        size="sm"
                        prefixIcon={SparkleIcon}
                        onPress={onOpen}
                        isElevated

                    />
                ),
                ...(isNew ? [() => (
                    <Chip
                        text="New"
                        tone="accent"

                    />
                )] : []),
            ]}
        />
    </div>
)

export { ContentAiSelectionAsk }

import React from "react"
import { SurfaceCard } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { Callout } from "@sb-components/composites/feedback/Callout/Callout"
import { LockedContentMask } from "@sb-components/composites/layout/LockedContentMask/LockedContentMask"
import { MarkdownContent } from "@sb-components/composites/viewers/MarkdownContent/MarkdownContent"
import { ContentPaywall } from "@sb-components/starci/blocks/learn/ContentPaywall/ContentPaywall"
import type { PricingPhase } from "@sb-components/starci/blocks/commerce/PhaseScarcityNote/PhaseScarcityNote"
import { StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `ContentArticle` — the lesson body on the page it is read from. Over the bare
 * `MarkdownContent` viewer, it knows the document is a lesson: it can be locked,
 * and it offers a first-time reader the hint that they can ask AI about a
 * passage, placed under the text. When locked, the body stays mounted and its
 * tail fades into the surface (selection disabled) with `ContentPaywall` flat
 * beneath it in the same card. Locking and `isSkeleton` are each their own leaf;
 * the open-lesson hint is a state.
 */

/** Everything the offer under a locked lesson needs, as typed data. */
export interface ContentArticleOffer {
    /** Headline, localized by the caller. */
    title: string
    /** One sentence on what buying unlocks. */
    description?: string
    /** Price after discount, in VND. */
    discountedPriceVnd: number
    /** Price before discount, for the struck-through original. */
    originalPriceVnd?: number | null
    /** Pricing phase — drives the scarcity line. Omitted → no scarcity. */
    currentPhase?: PricingPhase
    /** Seats left in the current phase. */
    seatsRemaining?: number | null
    /** What the next phase will cost. */
    nextPhasePriceVnd?: number | null
    /** Label of the single call to action. */
    ctaLabel: string
    /** Fired when the reader takes the offer. */
    onPurchase: () => void
}

/** Props for {@link ContentArticle}. */
export interface ContentArticleProps {
    /** The lesson, as authored markdown. The viewer decides the shape from it. */
    body: string
    /**
     * `true` → the reader has not bought the course: the tail fades, selection is
     * off, and the offer renders under the text inside the same card.
     */
    isLocked?: boolean
    /** The offer. Required in practice whenever `isLocked` is set. */
    offer?: ContentArticleOffer
    /**
     * One-time tip about selecting a passage to ask AI. Omitted → not shown.
     * Never shown on a locked lesson, where selecting is off anyway.
     */
    hintText?: string
    /** `true` → the card draws a body mirror instead of the document. */
    isSkeleton?: boolean
}

/**
 * The lesson body and, when it is locked, the offer under it. See the file
 * header for the full contract.
 *
 * @param props - {@link ContentArticleProps}
 */
const ContentArticle = ({
    body,
    isLocked = false,
    offer,
    hintText,
    isSkeleton = false,
}: ContentArticleProps) => {
    return (
        <div>
            <SurfaceCard
                isSkeleton={isSkeleton}

                body={() => (
                    <StackV
                        gap={6}
                        isSkeleton={isSkeleton}
                        items={[
                            ...(hintText != null && !isLocked ? [() => (
                                <Callout
                                    title={hintText}

                                />
                            )] : []),
                            // Lock fade + select-none owned by LockedContentMask (same owner as ContentPage).
                            () => (
                                <LockedContentMask
                                    isLocked={isLocked}
                                    isSkeleton={isSkeleton}
                                    body={() => (
                                        <MarkdownContent
                                            source={body}
                                            measure="reading"
                                            isSkeleton={isSkeleton}
                                        />
                                    )}
                                />
                            ),
                            ...(isLocked && offer != null ? [() => (
                                <ContentPaywall
                                    title={offer.title}
                                    description={offer.description}
                                    discountedPriceVnd={offer.discountedPriceVnd}
                                    originalPriceVnd={offer.originalPriceVnd}
                                    currentPhase={offer.currentPhase}
                                    seatsRemaining={offer.seatsRemaining}
                                    nextPhasePriceVnd={offer.nextPhasePriceVnd}
                                    ctaLabel={offer.ctaLabel}
                                    onPurchase={offer.onPurchase}


                                />
                            )] : []),
                        ]}
                    />
                )}
            />
        </div>
    )
}

export { ContentArticle }

import React from "react"
import { ChatsCircleIcon, WarningCircleIcon } from "@phosphor-icons/react"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { EmptyState } from "@sb-components/composites/feedback/EmptyState/EmptyState"
import { StackV } from "@sb-components/frames/Stack/Stack"
import { ContentCommentComposer, type ContentCommentComposerViewer } from "@sb-components/starci/blocks/learn/ContentCommentComposer/ContentCommentComposer"
import { ContentCommentThread, type ContentCommentNode, type ContentCommentThreadCallbacks } from "@sb-components/starci/blocks/learn/ContentCommentThread/ContentCommentThread"

/**
 * `ContentDiscussion` — talk about this lesson: a label + archive line, an
 * avatar-led collapsible composer, and the threaded comment list, frameless on
 * the page canvas. The empty state is drawn on purpose — no comments yet is an
 * invitation. The composer never hides, and an error replaces the list only.
 * Comment count, archive line, and `hasMore` are states of `Full`; empty, error,
 * and the loading mirror are each their own leaf.
 */

/** Props for {@link ContentDiscussion}. */
export interface ContentDiscussionProps extends ContentCommentThreadCallbacks {
    /** Section label, localized by the caller — e.g. "Discussion" (the block appends "· {total}"). */
    label: string
    /** Current viewer id — drives owner-only edit/delete down the whole tree; null when signed out. */
    currentUserId: string | null
    /** Current viewer identity for the composer's avatar; null when signed out. */
    currentUser?: ContentCommentComposerViewer | null
    /** Top-level comments, newest first. EMPTY -> the invitation is drawn instead. */
    comments: Array<ContentCommentNode>
    /** Total top-level comment count (drives the label + the archive line). */
    total: number
    /** Replies keyed by parent comment id (lazily populated by the caller). */
    repliesByParent: Record<string, ReadonlyArray<ContentCommentNode>>
    /** Post a new top-level comment. */
    onSubmitComment: (body: string) => void
    /** `true` -> more top-level comment pages remain to load. */
    hasMore?: boolean
    /** `true` -> the next page is currently loading. */
    isLoadingMore?: boolean
    /** Load the next page of top-level comments. */
    onLoadMore?: () => void
    /**
 * Set -> the comment list could not be loaded. The message replaces the
 * LIST only: the composer stays, because a failed read did not remove
 * the ability to write.
 */
    errorMessage?: string
    /** `true` -> two placeholder threads mirror the real row shape while the first page loads. */
    isSkeleton?: boolean
}

/** Two placeholder rows so the mirror has the same shape as a short thread. */
const SKELETON_ROWS: Array<ContentCommentNode> = [
    { id: "s1", author: { id: "s1", username: "" }, createdTimeAgo: "", body: "", replyCount: 0, myReaction: null },
    { id: "s2", author: { id: "s2", username: "" }, createdTimeAgo: "", body: "", replyCount: 0, myReaction: null },
]

/**
 * Lesson discussion. See the file header for the full contract.
 *
 * @param props - {@link ContentDiscussionProps}
 */
const ContentDiscussion = ({
    label,
    currentUserId,
    currentUser,
    comments,
    total,
    repliesByParent,
    onSubmitComment,
    onReply,
    onEdit,
    onDelete,
    onReactComment,
    onLoadReplies,
    hasMore = false,
    isLoadingMore = false,
    onLoadMore,
    errorMessage,
    isSkeleton = false,
}: ContentDiscussionProps) => {
    // real (not fabricated) count of currently-loaded top-level comments that already
    // have at least one reply — under-counts before "load more" is exhausted, same
    // tradeoff real `Discussion` documents for its own archive line
    const answeredCount = comments.filter((comment) => comment.replyCount > 0).length

    // no icon here: a chat-bubble icon needs an ASSOCIATION step to read as
    // "discussion" (not a universal symbol like check/locklock), and the label text already
    // carries the full fact on its own.
    return (
        <div>
            <StackV
                gap={4}
                isSkeleton={isSkeleton}
                items={[
                    // These 3 seams match the real-src `Discussion/index.tsx:98-114` exactly:
                    // [label+archive]<->composer = grouped (gap-3) · [icon+label]<->archive-line
                    // = tight (gap-1) · icon<->label = related (gap-2).
                    () => (
                        <StackV
                            gap={4}
                            isSkeleton={isSkeleton}
                            items={[
                                () => (
                                    <StackV
                                        gap={2}
                                        isSkeleton={isSkeleton}
                                        items={[
                                            () => (
                                                isSkeleton ? (
                                                    <Typography weight="medium" isSkeleton />
                                                ) : (
                                                    <Typography weight="medium" text={`${label} · ${total}`} />
                                                )
                                            ),
                                            ...(isSkeleton || total > 0 ? [() => (
                                                <Typography
                                                    size="xs"
                                                    color="muted"
                                                    isSkeleton={isSkeleton}

                                                    text={`${answeredCount}/${total} questions answered, accumulated over time`}

                                                />
                                            )] : []),
                                        ]}
                                    />
                                ),
                                () => (
                                    <ContentCommentComposer
                                        onSubmit={onSubmitComment}
                                        currentUser={currentUser}
                                        collapsible
                                        ariaLabel="Write a comment"


                                    />
                                ),
                            ]}
                        />
                    ),
                    ...(errorMessage != null ? [() => (
                        <EmptyState
                            icon={WarningCircleIcon}
                            title={errorMessage}

                        />
                    )] : !isSkeleton && comments.length === 0 ? [() => (
                        // Nobody has written yet. This is an INVITATION, so it is drawn —
                        // hiding the section would hide the invitation with it.
                        <EmptyState
                            icon={ChatsCircleIcon}
                            title="No discussion yet"
                            description="Ask the first question about this lesson"

                        />
                    )] : [() => (
                        <StackV
                            gap={4}
                            isSkeleton={isSkeleton}
                            items={[
                                ...(isSkeleton ? SKELETON_ROWS : comments).map((comment) => () => (
                                    <ContentCommentThread
                                        key={comment.id}
                                        comment={comment}
                                        currentUserId={currentUserId}
                                        currentUser={currentUser}
                                        depth={0}
                                        repliesByParent={repliesByParent}
                                        onReply={onReply}
                                        onEdit={onEdit}
                                        onDelete={onDelete}
                                        onReactComment={onReactComment}
                                        onLoadReplies={onLoadReplies}

                                    />
                                )),
                                ...(!isSkeleton && hasMore ? [() => (
                                    <Button
                                        variant="ghost"
                                        size="sm"

                                        label={isLoadingMore ? "Loading…" : "Show more comments"}
                                        isDisabled={isLoadingMore}
                                        onPress={onLoadMore}
                                    />
                                )] : []),
                            ]}
                        />
                    )]),
                ]}
            />
        </div>
    )
}

export { ContentDiscussion }

import React from "react"
import { CheckCircleIcon } from "@phosphor-icons/react"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { Breadcrumbs } from "@sb-components/atoms/navigation/Breadcrumbs/Breadcrumbs"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { SurfaceCardList } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { PageHeader } from "@sb-components/composites/layout/Page/Page"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `ContentHeader` — the lesson-identity cluster atop the reading screen: a
 * `PageHeader` cluster carrying read state, reading time, challenge count, and
 * learning outcomes. One chip per cluster (`starci-fe/no-adjacent-chip`): read
 * state takes the chip, reading time and challenge count ride as muted text with
 * an inline icon. `isRead` is a state; losing the outcomes card and `isSkeleton`
 * are each their own leaf. The breadcrumb trail always exists.
 */

/** One breadcrumb link — plain data, the block builds the atom from it. */
export interface ContentHeaderCrumb {
    /** Stable React key. */
    key: string
    /** Display label. */
    label: string
    /** Has a handler → the crumb is pressable; the current page leaves it out. */
    onPress?: () => void
}

/** One line of "what you'll learn" — plain data, the block builds the row. */
export interface ContentHeaderOutcome {
    /** Stable React key. */
    key: string
    /** The outcome sentence, already localized by the caller (blocks carry no i18n). */
    text: string
}

/** Props for {@link ContentHeader}. */
export interface ContentHeaderProps {
    /** Breadcrumb trail as DATA — the block builds `Breadcrumbs` itself. */
    breadcrumbItems?: Array<ContentHeaderCrumb>
    /** Lesson title. */
    title: string
    /** One-sentence summary of the lesson. */
    description?: string
    /**
     * `true` → the learner has finished this lesson. This is the ONE classifying
     * fact in the meta cluster, so it is the one that gets a chip.
     */
    isRead?: boolean
    /** Estimated reading time in MINUTES — the block adds the word itself. */
    minutesRead?: number
    /** How many challenges hang off this lesson — the block adds the word itself. */
    challengeCount?: number
    /**
     * The "what you'll learn" lines. Empty or omitted → the whole section is not
     * drawn at all: a lesson with no stated outcomes should say nothing, not show
     * an empty card.
     */
    outcomes?: Array<ContentHeaderOutcome>
    /**
     * `true` → every composed atom switches to its own shimmer. The flag FLOWS
     * DOWN into the real atoms rather than building a parallel skeleton tree
     * (§12c), so the shimmer keeps the exact box of the thing it replaces.
     */
    isSkeleton?: boolean
}

/**
 * Lesson identity cluster at the top of the reading screen. See the file header
 * for the full contract.
 *
 * @param props - {@link ContentHeaderProps}
 */
const ContentHeader = ({
    breadcrumbItems,
    title,
    description,
    isRead = false,
    minutesRead,
    challengeCount,
    outcomes,
    isSkeleton = false,
}: ContentHeaderProps) => {
    const hasOutcomes = isSkeleton || (outcomes?.length ?? 0) > 0

    return (
        <div>
            <StackV
                gap={6}
                isSkeleton={isSkeleton}
                items={[
                    () => (
                        <PageHeader

                            isSkeleton={isSkeleton}
                            breadcrumb={() =>
                                isSkeleton || breadcrumbItems?.length ? (
                                    <div className="w-fit">
                                        <Breadcrumbs
                                            collapseOnMobile
                                            collapseFrom={4}
                                            items={breadcrumbItems ?? []}
                                            isSkeleton={isSkeleton}
                                        />
                                    </div>
                                ) : undefined
                            }
                            title={title}
                            description={description}
                            meta={() =>
                                <StackH
                                    gap={3}
                                    align="center"
                                    principle="sibling-stack"
                                    explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                                    isSkeleton={isSkeleton}
                                    items={[
                                        ...(isSkeleton ? [() => (
                                            <Chip isSkeleton />
                                        )] : isRead ? [() => (
                                            <Chip
                                                tone="success"
                                                icon={CheckCircleIcon}
                                                text="Read"

                                            />
                                        )] : []),
                                        ...(isSkeleton ? [() => (
                                            <Typography size="xs" color="muted" isSkeleton />
                                        )] : [
                                            ...(minutesRead != null ? [() => (
                                                <Typography
                                                    size="xs"
                                                    color="muted"
                                                    text={`${minutesRead} min read`}

                                                />
                                            )] : []),
                                            ...(challengeCount != null ? [() => (
                                                <Typography
                                                    size="xs"
                                                    color="muted"
                                                    text={`${challengeCount} challenges`}

                                                />
                                            )] : []),
                                        ]),
                                    ]}
                                />
                            }
                        />
                    ),
                    ...(hasOutcomes ? [() => (
                        <SurfaceCardList
                            label="What you will learn"
                            isSkeleton={isSkeleton}

                            items={(outcomes ?? []).map((outcome) => ({
                                key: outcome.key,
                                leadingIcon: CheckCircleIcon,
                                leadingIconColor: "success",
                                title: outcome.text,
                            }))}
                        />
                    )] : []),
                ]}
            />
        </div>
    )
}

export { ContentHeader }

import React from "react"
import { BookOpenIcon, CodeIcon, FlaskIcon, PlayIcon, PuzzlePieceIcon } from "@phosphor-icons/react"
import { Toolbar, type ToolbarTabItem } from "@sb-components/composites/navigation/Toolbar/Toolbar"

/**
 * `ContentModeNav` — how to view this lesson: modes on the left, code language
 * on the right. Switching mode changes the route, so this is navigation, not a
 * tab/panel pair. A locked mode renders muted but still fires `onModeChange` —
 * the screen decides a locked tap opens the paywall. The mode group carries the
 * one accent; the language group is neutral. No `isSkeleton` — it is static
 * chrome. The right group appearing is its own leaf; selected mode and lock
 * state are data.
 */

/** The ways a lesson can be looked at. */
export type ContentMode = "content" | "sandbox" | "challenges" | "aiLab"

/**
 * Label + icon per mode. The BLOCK owns this table: it is the vocabulary of the
 * reading experience, and a caller that could pass it would own the wording.
 */
const MODE_LABEL: Record<ContentMode, string> = {
    content: "Content",
    sandbox: "Sandbox",
    challenges: "Challenges",
    aiLab: "AI Lab",
}

// `size-5` — the tab's own text is `text-sm` (HeroUI `Tabs.Tab` default, `tabs.css`
// `.apply ... text-sm`), and this icon sits INSIDE that control, so it matches the
// control's own box height (line-height 20px), not the bare glyph size (§5a icon=DIV
// case) — `size-3.5` would be the icon=TEXT pairing, wrong for an icon inside a tab.
const MODE_ICON: Record<ContentMode, React.ReactNode> = {
    content: <BookOpenIcon aria-hidden focusable="false" className="size-5" />,
    sandbox: <PlayIcon aria-hidden focusable="false" className="size-5" />,
    challenges: <PuzzlePieceIcon aria-hidden focusable="false" className="size-5" />,
    aiLab: <FlaskIcon aria-hidden focusable="false" className="size-5" />,
}

// Same icon on every language tab (doesn't distinguish TS from Go) — the trigger
// affordance for "this collapses to a language switcher" below `@app-sm`, not a
// per-language mark. Matches `Toolbar`'s own collapsed-group story convention
// (`RightNeutralCollapsed`, every item sharing one `GlobeIcon`) — the collapsed
// `Select` trigger is ICON-ONLY (§13c), so a language row with no icon of its own
// would render a blank trigger once `collapseRightOnMobile` is on.
const LANGUAGE_ICON = <CodeIcon aria-hidden focusable="false" className="size-4" weight="bold" />

/** One offered mode — whether it is locked. */
export interface ContentModeOption {
    /** Which mode this entry is. */
    mode: ContentMode
    /** `true` → premium and not yet bought: rendered muted, still clickable. */
    isLocked?: boolean
}

/** One entry in the fixed code-language catalog. */
export interface ContentLanguage {
    /** Stable id used as the selection key, e.g. `"typescript"`. */
    key: string
    /** Display label, already localized by the caller. */
    label: string
    /** `true` → this lesson has no body in this language: rendered disabled, not omitted. */
    isDisabled?: boolean
}

/** Props for {@link ContentModeNav}. */
export interface ContentModeNavProps {
    /** Modes this lesson offers, in display order. */
    modes: Array<ContentModeOption>
    /** Which mode is being looked at now. */
    mode: ContentMode
    /**
     * Fired with the mode the reader picked — INCLUDING a locked one. The screen
     * decides what a locked pick means (typically: open the paywall instead of
     * navigating). The block never swallows the event.
     */
    onModeChange: (mode: ContentMode) => void
    /**
     * The FULL fixed language catalog (TypeScript/Java/C#/Go, in that order),
     * each carrying its own `isDisabled` — a lesson missing a language still
     * lists it, dimmed, rather than shrinking the row (real `src` never hides
     * a language, only greys it out). Fewer than two AVAILABLE (non-disabled)
     * entries → the right group is not drawn at all: a switcher with one live
     * option is a control that cannot do anything.
     */
    languages?: Array<ContentLanguage>
    /** Which language is being read. */
    language?: string
    /** Fired with the language the reader picked. */
    onLanguageChange?: (language: string) => void
    /**
     * Accessible name for the mode row, localized by the caller (blocks carry no
     * i18n). Without it a screen reader hears loose tabs.
     */
    ariaLabel: string
    /** Accessible name for the language group. Required whenever `languages` is set. */
    languageAriaLabel?: string
}

/**
 * The lesson's mode row. See the file header for why locked modes stay clickable
 * and why this is navigation rather than a tab/panel pair.
 *
 * @param props - {@link ContentModeNavProps}
 */
const ContentModeNav = ({
    modes,
    mode,
    onModeChange,
    languages,
    language,
    onLanguageChange,
    ariaLabel,
    languageAriaLabel,
}: ContentModeNavProps) => {
    const items: Array<ToolbarTabItem> = modes.map((entry) => ({
        key: entry.mode,
        label: MODE_LABEL[entry.mode],
        icon: MODE_ICON[entry.mode],
        // MUTED, not disabled: a locked mode must still receive the click so the
        // screen can open the offer. Disabling it kills the very thing this row is for.
        muted: entry.isLocked,
    }))

    // A switcher with one AVAILABLE option is a control that cannot do anything — count
    // only the non-disabled entries, since the catalog itself always lists all four.
    const availableLanguageCount = (languages ?? []).filter((entry) => !entry.isDisabled).length
    const hasLanguages = availableLanguageCount > 1 && language != null && onLanguageChange != null

    return (
        <div>
            <div>
                <Toolbar
                    leftTabs={{
                        items,
                        selectedKey: mode,
                        ariaLabel,
                        onSelectionChange: (key) => onModeChange(String(key) as ContentMode),
                    }}
                    rightTabs={
                        hasLanguages
                            ? {
                                items: (languages ?? []).map((entry) => ({
                                    key: entry.key,
                                    label: entry.label,
                                    icon: LANGUAGE_ICON,
                                    isDisabled: entry.isDisabled,
                                })),
                                selectedKey: language as string,
                                ariaLabel: languageAriaLabel ?? "",
                                onSelectionChange: (key) => onLanguageChange?.(String(key)),
                            }
                            : undefined
                    }
                    // The language group is a "same lesson, different presentation" toggle, so
                    // it stays NEUTRAL: only the mode group carries accent, and the row keeps
                    // ONE accent signal rather than two competing for the eye.
                    rightTabsNeutral
                    // A set-once preference, not a second navigation choice — folds behind a
                    // compact icon-only dropdown below `@app-sm` instead of crowding the reading
                    // column with 4 inline tabs.
                    collapseRightOnMobile

                />
            </div>
        </div>
    )
}

export { ContentModeNav }

import React from "react"
import { type SkeletonProps } from "@sb-components/frames/_slot"
import { CaretLeftIcon, CaretRightIcon } from "@phosphor-icons/react"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { SurfaceCardPressableGroup, type SurfaceCardPressableGroupItem } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `ContentPager` — step to the neighbouring lesson at the foot of the reading
 * screen. It owns the "previous lesson" / "next lesson" labels and the lesson
 * title + link on each card. The right card mirrors the left so the pair reads
 * as a direction, pinning to a second column only where the grid has two (a
 * container query). Losing either card, and `isSkeleton`, are each their own
 * leaf; having no neighbour renders nothing.
 */

/** One neighbouring lesson — plain data, the block builds the card from it. */
export interface ContentPagerNeighbour {
    /** Lesson title, shown under the direction label and clamped to two lines. */
    title: string
    /** Where the card navigates. */
    href: string
}

/** Props for {@link ContentPager}. */
export interface ContentPagerProps {
    /** The lesson before this one. Omitted → the left card is not drawn. */
    previous?: ContentPagerNeighbour
    /** The lesson after this one. Omitted → the right card is not drawn. */
    next?: ContentPagerNeighbour
    /**
     * Accessible name for the pair, localized by the caller (blocks carry no
     * i18n). Without it a screen reader hears two loose links with nothing tying
     * them together.
     */
    ariaLabel: string
    /**
     * `true` → the group draws its own mirror. The flag FLOWS DOWN into
     * `SurfaceCardPressableGroup`, which owns the card box and the grid, so the
     * shimmer keeps the exact shape the real cards will take (§12c).
     */
    isSkeleton?: boolean
}

/**
 * Previous/next lesson pager. See the file header for the full contract.
 *
 * @param props - {@link ContentPagerProps}
 */
const ContentPager = ({
    previous,
    next,
    ariaLabel,
    isSkeleton = false,
}: ContentPagerProps) => {
    // Nothing to step to in either direction ⇒ draw nothing at all. Reached on the
    // first and last lesson of a course, which are ordinary, not exceptional.
    if (!isSkeleton && !previous && !next) {
        return null
    }

    const items: Array<SurfaceCardPressableGroupItem> = []
    if (previous) {
        const previousCard = (
            <StackH
                gap={4}
                principle="content-row"
                align="center"
                isSkeleton={isSkeleton}
                items={[
                    // DIV position: this card is a control with its own FIXED padding
                    // (`SurfaceCardPressableGroup` tile, `cozy` inset) — not hug-content —
                    // so size tracks line-height, not font-size. Title is `text-sm` ⇒ `size-5`,
                    // matching the sibling `ITEM_ICON_CLS` convention this same file's parent
                    // (`SurfaceCard.tsx`) already forces for icons in this exact tile shape.
                    // Weight omitted → Phosphor default `regular`, correct at `size-5`.
                    () => <CaretLeftIcon aria-hidden focusable="false" className="size-5 shrink-0 text-muted" />,
                    ({ isSkeleton }: SkeletonProps) => (
                        <StackV
                            gap={1}
                            isSkeleton={isSkeleton}
                            items={[
                                () => <Typography size="xs" color="muted" text="Previous content" />,
                                () => (
                                    <Typography
                                        size="sm"
                                        weight="medium"
                                        lineClamp={2}
                                        underlineOnGroupHover
                                        text={previous.title}
                                    />
                                ),
                            ]}
                        />
                    ),
                ]}
            />
        )
        items.push({
            key: "previous",
            href: previous.href,
            content: () => previousCard,
        })
    }
    if (next) {
        const nextCard = (
            <StackH
                gap={4}
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                align="center"
                justify="end"
                isSkeleton={isSkeleton}
                items={[
                    ({ isSkeleton }: SkeletonProps) => (
                        <StackV
                            gap={1}
                            principle="name-handle"
                            explain="Display name with handle — not title-subtitle, because the second line is an identity handle rather than a subtitle."
                            align="end"
                            isSkeleton={isSkeleton}
                            items={[
                                () => (
                                    <Typography size="xs" color="muted" align="end" text="Next content" />
                                ),
                                () => (
                                    <Typography
                                        size="sm"
                                        weight="medium"
                                        align="end"
                                        lineClamp={2}
                                        underlineOnGroupHover
                                        text={next.title}
                                    />
                                ),
                            ]}
                        />
                    ),
                    // Same DIV position/size reasoning as the mirrored left caret above.
                    () => <CaretRightIcon aria-hidden focusable="false" className="size-5 shrink-0 text-muted" />,
                ]}
            />
        )
        items.push({
            key: "next",
            href: next.href,
            // Full-width lone pager card: Grid's only placement lever is `span`
            // (`GridItem.span`, capped at 2). Column-start escapes are intentionally
            // unavailable — same contract as `PagerFullWidth` in SurfaceCardPressableGroup stories.
            span: 2,
            content: () => nextCard,
        })
    }

    return (
        <div>
            <div>
                <SurfaceCardPressableGroup ariaLabel={ariaLabel} columns={{ base: 1, sm: 2 }} items={items} isSkeleton={isSkeleton} principle="content-row"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title." />
            </div>
        </div>
    )
}

export { ContentPager }

import React from "react"
import { ArrowRightIcon, LockIcon } from "@phosphor-icons/react"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { IconTile } from "@sb-components/atoms/display/IconTile/IconTile"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { PhaseScarcityNote } from "@sb-components/starci/blocks/commerce/PhaseScarcityNote/PhaseScarcityNote"
import { PriceTagProminent } from "@sb-components/starci/blocks/commerce/PriceTag/PriceTag"
import type { PricingPhase } from "@sb-components/starci/blocks/commerce/PhaseScarcityNote/PhaseScarcityNote"
import { StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `ContentPaywall` — the offer at the point the lesson stops. Flat, with no card
 * of its own, so it sits inside the reading card under the faded body tail as
 * one surface that runs out. It reuses the course page's price and scarcity
 * blocks and owns only the frame the offer arrives in: the lock, the sentence,
 * the order, and one call to action. Losing the scarcity line and `isSkeleton`
 * are each their own leaf; whether an original price strikes through is data.
 */

/** Props for {@link ContentPaywall}. */
export interface ContentPaywallProps {
    /** Headline, localized by the caller — e.g. "The rest is for enrolled learners". */
    title: string
    /** One sentence on what buying unlocks. */
    description?: string
    /** Price after discount, in VND. */
    discountedPriceVnd: number
    /** Price before discount, for the struck-through original. */
    originalPriceVnd?: number | null
    /** Which pricing phase the course is in — drives the scarcity line. */
    currentPhase?: PricingPhase
    /** Seats left in the current phase. `null` → the phase is not capped. */
    seatsRemaining?: number | null
    /** What the next phase will cost, so the reader can see waiting is not free. */
    nextPhasePriceVnd?: number | null
    /** Label of the single call to action, localized by the caller. */
    ctaLabel: string
    /** Fired when the reader takes the offer. */
    onPurchase: () => void
    /**
     * `true` → the price and the scarcity line mirror themselves. The lock, the
     * headline and the button stay REAL: they are known before any price request,
     * and shimmering them would hide an offer that was already legible.
     */
    isSkeleton?: boolean
}

/**
 * The offer where the lesson stops. See the file header for the full contract.
 *
 * @param props - {@link ContentPaywallProps}
 */
const ContentPaywall = ({
    title,
    description,
    discountedPriceVnd,
    originalPriceVnd,
    currentPhase,
    seatsRemaining = null,
    nextPhasePriceVnd = null,
    ctaLabel,
    onPurchase,
    isSkeleton = false,
}: ContentPaywallProps) => {
    return (
        <div>
            <StackV
                gap={4}
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                align="center"
                items={[
                    () => <IconTile icon={LockIcon} tone="accent" size="sm" />,
                    // real source (`PremiumPaywall/index.tsx:54`): `text-xl font-semibold` (a bare div,
                    // not routed through Typography) — matches `size="h4"` (heading, 20px), not body `lg`.
                    () => <Typography size="h4" weight="semibold" align="center" text={title} />,
                    ...(description != null ? [() => (
                        <Typography size="sm" color="muted" align="center" text={description} />
                    )] : []),
                    () => (
                        <PriceTagProminent
                            discounted={discountedPriceVnd}
                            original={originalPriceVnd}
                            isSkeleton={isSkeleton}

                        />
                    ),
                    ...(currentPhase != null ? [() => (
                        <PhaseScarcityNote
                            currentPhase={currentPhase}
                            seatsRemaining={seatsRemaining}
                            nextPhasePriceVnd={nextPhasePriceVnd}


                        />
                    )] : []),
                    () => (
                        <Button
                            label={ctaLabel}
                            variant="primary"
                            suffixIcon={ArrowRightIcon}
                            iconSlide
                            onPress={onPurchase}

                        />
                    ),
                ]}
            />
        </div>
    )
}

export { ContentPaywall }

import React from "react"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { ReactionButton, type ReactionType, type ReactionCount } from "@sb-components/starci/blocks/learn/ReactionButton/ReactionButton"
import { StackH } from "@sb-components/frames/Stack/Stack"

/**
 * `ContentReaction` — say how the lesson landed: a six-emotion picker on the
 * left, the quiet view count on the right. Reacting is a button; the view count
 * is muted text. The caller hands over `counts` (one entry per emotion reacted);
 * the block owns the six fixed labels/emoji and does the sort/cap/total. Which
 * emotion is picked, empty summary, and the server wait are states; `isSkeleton`
 * is its own leaf.
 */

export type { ReactionType, ReactionCount as ContentReactionCount }

/** Props for {@link ContentReaction}. */
export interface ContentReactionProps {
    /** The viewer's own reaction, or `null`/omitted if they haven't reacted. */
    myReaction?: ReactionType | null
    /** Per-emotion counts. Empty/omitted → the summary is not drawn at all. */
    counts?: ReadonlyArray<ReactionCount>
    /** How many people opened this lesson. Omitted → the fact is not claimed. */
    viewCount?: number
    /** Fired with the picked emotion, or `null` to remove the current one. */
    onReact: (type: ReactionType | null) => void
    /**
     * `true` → the reaction is in flight. The trigger owns the busy affordance,
     * so the row keeps its shape while the server answers.
     */
    isPending?: boolean
    /**
     * `true` → both slots switch to their own shimmer. Without it the row would
     * render a truthful-looking "no reactions" for the length of the fetch and
     * then jump when the real summary lands.
     */
    isSkeleton?: boolean
}

/**
 * Reaction footer for a lesson. See the file header for the full contract.
 *
 * @param props - {@link ContentReactionProps}
 */
const ContentReaction = ({
    myReaction = null,
    counts = [],
    viewCount,
    onReact,
    isPending = false,
    isSkeleton = false,
}: ContentReactionProps) => {
    return (
        <div>
            <StackH
                gap={3}
                principle="sibling-stack"
                explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
                align="center"
                justify="between"
                isSkeleton={isSkeleton}
                items={[
                    () => (
                        <ReactionButton
                            myReaction={myReaction}
                            counts={counts}
                            onReact={onReact}
                            isPending={isPending}
                            isSkeleton={isSkeleton}


                        />
                    ),
                    ...(isSkeleton ? [() => (
                        <Typography size="xs" color="muted" isSkeleton />
                    )] : viewCount != null ? [() => (
                        <Typography
                            size="xs"
                            color="muted"
                            text={`${viewCount.toLocaleString("en-US")} views`}

                        />
                    )] : []),
                ]}
            />
        </div>
    )
}

export { ContentReaction }

import React from "react"
import { LockSimpleIcon } from "@phosphor-icons/react"
import { SurfaceCardList, type SurfaceCardListItem } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `ContentRelatedList` — what else in this course is worth reading after this
 * lesson: a quiet list, never a call to action. Self-hides with nothing related
 * — no card, no label, no empty state (the opposite of `ContentDiscussion`).
 * `breadcrumb` shows a course trail above the title; `isLocked` adds a quiet
 * lock line below. Row count is a state of `Full`; hidden, `isSkeleton`, and a
 * locked row are each their own leaf.
 */

/** One related lesson — plain data, the block builds the row. */
export interface ContentRelatedItem {
    /** Stable React key. */
    key: string
    /** Lesson title. */
    title: string
    /** Course trail this result belongs to, e.g. "Containerization · Docker". Omitted → no line above the title. */
    breadcrumb?: string
    /** `true` → the viewer must enrol to open this result; a quiet lock line replaces any snippet. */
    isLocked?: boolean
    /** Where the row navigates. */
    href: string
}

/** Props for {@link ContentRelatedList}. */
export interface ContentRelatedListProps {
    /**
     * The related lessons. EMPTY → the block renders nothing at all, which is the
     * ordinary case for a course with one lesson on a subject.
     */
    items: Array<ContentRelatedItem>
    /**
     * Section label, localized by the caller (blocks carry no i18n) — e.g.
     * "You might also want to read".
     */
    label: string
    /** Accessible text for the lock line, e.g. "Enroll to unlock". */
    enrollToOpenLabel?: string
    /**
     * `true` → the list draws its own row mirror. Kept even though the block
     * self-hides when empty: during the fetch we do not yet KNOW it is empty, and
     * hiding first then appearing would push the page down under the reader.
     */
    isSkeleton?: boolean
}

/**
 * One related-lesson row's content — extracted because it depends on the loop
 * variable (`item`) and so cannot be hoisted to a module-level const.
 */
const relatedItemBody = (item: ContentRelatedItem, enrollToOpenLabel: string) => (
    <>
        {item.breadcrumb ? (
            <Typography size="xs" color="muted" truncate text={item.breadcrumb} />
        ) : null}
        <Typography
            size="sm"
            weight="medium"
            truncate
            text={item.title}
            underlineOnGroupHover

        />
        {item.isLocked ? (
            <Typography size="xs" color="warning" prefixIcon={LockSimpleIcon} text={enrollToOpenLabel} />
        ) : null}
    </>
)

/**
 * Related-reading list under a lesson. See the file header for the full contract.
 *
 * @param props - {@link ContentRelatedListProps}
 */
const ContentRelatedList = ({
    items,
    label,
    enrollToOpenLabel = "Enroll to unlock",
    isSkeleton = false,
}: ContentRelatedListProps) => {
    // Nothing related ⇒ draw nothing. Deliberately BEFORE the skeleton check is
    // false: while loading we do not know yet, so the mirror still shows.
    if (!isSkeleton && items.length === 0) {
        return null
    }

    const rows: Array<SurfaceCardListItem> = items.map((item) => ({
        key: item.key,
        href: item.href,
        // Row-as-link: hover underlines the title itself, never a full-row fill —
        // matches the real row's own affordance (no accent, no arrow).
        hover: "underline",
        content: () => (
            <StackV gap={2} isSkeleton={isSkeleton} items={[() => relatedItemBody(item, enrollToOpenLabel)]} />
        ),
    }))

    return (
        <div>
            <SurfaceCardList
                label={label}
                items={rows}
                isSkeleton={isSkeleton}

            />
        </div>
    )
}

export { ContentRelatedList }

import React from "react"
import { type SkeletonProps } from "@sb-components/frames/_slot"
import { Skeleton as HeroSkeleton } from "@heroui/react"
import { ProgressMeter } from "@sb-components/composites/stats/ProgressMeter/ProgressMeter"
import { ListMeta } from "@sb-components/composites/lists/List/List"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { type ContinueCardDataProps } from "./types"

/** Shared internals: eyebrow-less, title → meta/subtitle → progress → CTA. */
export const CardBody = ({
    title,
    subtitle,
    value,
    max = 100,
    meta,
    timeLeft,
    urgent = false,
    isSkeleton = false,
    cta,
}: ContinueCardDataProps & { cta: React.ReactNode }) => {
    return (
        <>
            {/* The outer row = ONE horizontal track ⇒ `StackH` (children are ARBITRARY, not a
                repeating list so NOT `Cluster`). The inner column = a vertical track ⇒ `StackV`.
                `min-w-0 flex-1` stays in `className`: that's its PLACEMENT within the parent row
                (`className` is allowed for placement), not the scaffold's own shape. */}
            <div className="relative">
                <StackH
                    gap={4}
                    principle="content-row"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                    align="center"
                    isSkeleton={isSkeleton}
                    items={[
                        ({ isSkeleton }: SkeletonProps) => (
                            <StackV
                                gap={3}
                                classNames={["min-w-0", "flex-1"]}
                                isSkeleton={isSkeleton}
                                items={[
                                    () => (
                                        <Typography weight="medium" truncate isSkeleton={isSkeleton} text={title} />
                                    ),
                                    ...(isSkeleton ? [() => (
                                        // `ListMeta` (the scaffold the live branch uses here) has no `isSkeleton`
                                        // yet and sits outside this round's boundary — CardBody calls that scaffold
                                        // DIRECTLY so it builds ONE shimmer bar in place of the meta/subtitle row
                                        // (the real shape always has EXACTLY ONE of the two) using atom `Typography`.
                                        <Typography size="xs" color="muted" isSkeleton />
                                    )] : meta?.length || timeLeft ? [() => (
                                        <ListMeta
                                            items={meta ?? []}

                                            chip={
                                                timeLeft ? (
                                                    // Same kind of information (time left) ⇒ the same element in
                                                    // EVERY case; only the TONE escalates: `default` while time
                                                    // remains, `warning` when it's about to run out.
                                                    () => (
                                                        <Chip
                                                            tone={urgent ? "warning" : "default"}

                                                            text={timeLeft}
                                                        />
                                                    )
                                                ) : undefined
                                            }
                                        />
                                    )] : subtitle ? [() => (
                                        <Typography size="xs" color="muted" truncate text={subtitle} />
                                    )] : []),
                                ]}
                            />
                        ),
                    ]}
                />
            </div>
            {/* Progress SITS right under the text cluster, BEFORE the button:
            where am I → how much progress → what's next. Put it
            after the CTA and it reads as detached from the card, misread as belonging to the block below. */}
            {value === undefined ? null : isSkeleton ? (
                // `ProgressMeter` (scaffold) has no `isSkeleton` yet and sits outside this
                // round's boundary — CardBody calls that scaffold directly so it builds a
                // track shimmer bar matching the real track height (`h-1`, see `ProgressMeter.tsx`).
                <HeroSkeleton className="h-1 w-full rounded-full" />
            ) : (
                <ProgressMeter value={value} max={max} />
            )}
            <div className="relative">{cta}</div>
        </>
    )
}

import React from "react"
import { PageHeader } from "@sb-components/composites/layout/Page/Page"
import { type SkeletonProps } from "@sb-components/frames/_slot"
import { Breadcrumbs } from "@sb-components/atoms/navigation/Breadcrumbs/Breadcrumbs"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"

/**
 * `CourseBrief` — the course-identity cluster atop a page. It takes crumb DATA
 * (`breadcrumbItems`) and builds the `Breadcrumbs` atom itself, so a screen
 * never holds the `PageHeader` frame or the atom directly. Meta is a muted text
 * strip joined by `·`, not a chip. The two leaves lose a node; a long trail only
 * changes the crumb count, so it is a state.
 */

/** One breadcrumb link — plain data, the block builds the atom from it. */
export interface CourseBriefCrumb {
    /** React key. */
    key: string
    /** Display label. */
    label: string
    /** Has a handler → crumb is pressable; the last crumb (current page) leaves it out. */
    onPress?: () => void
}

/** Props for {@link CourseBrief}. */
export interface CourseBriefBaseProps {
    /** Breadcrumb trail as DATA — the block builds `Breadcrumbs` itself. */
    breadcrumbItems?: Array<CourseBriefCrumb>
    /** Course name. */
    title: string
    /** One-sentence course description. */
    description?: string
    /**
     *  NO pre-formatted `meta` string prop.
     * Passing `meta="8 modules · ~14h · 2,481 learners"` is **breaking the
     * structure**: the caller ends up deciding the join, units, and separator —
     * the block loses ownership of its own shape. Below are separate NUMBER
     * fields; the block joins them itself into a muted strip separated by `·`.
     */
    moduleCount?: number
    /** Total learning hours (rounded) — the block adds `~` and the "hours" word itself. */
    hours?: number
    /** Number of enrolled learners — the block formats the thousands separator itself. */
    learnerCount?: number
    /**
     * `true` → the cluster switches to a mirror shimmer INSTEAD OF waiting for
     * data — the flag FLOWS DOWN to the actual text-rendering atoms/frames
     * (`PageHeader`/`Breadcrumbs`/`Typography`), not a parallel skeleton tree
     * (§12c). `PageHeader` owns `isSkeleton` itself now (it swaps
     * `title`/`description` to shimmer internally), so this block just
     * forwards the flag straight through.
     */
    isSkeleton?: boolean
}

/**
 * Course identity cluster at the top of a page. See the file header for the
 * full contract.
 *
 * @param props - {@link CourseBriefBaseProps}
 */
const CourseBriefBase = ({
    breadcrumbItems,
    title,
    description,
    moduleCount,
    hours,
    learnerCount,
    isSkeleton = false,
}: CourseBriefBaseProps) => {
    // Meta strip joined by the BLOCK from NUMBERS — units, separators, thousands
    // grouping are all presentation; the caller doesn't touch this (§14d.1).
    const metaParts = [
        moduleCount != null ? `${moduleCount} modules` : null,
        hours != null ? `~${hours} hours` : null,
        learnerCount != null ? `${learnerCount.toLocaleString("vi-VN")} learners` : null,
    ].filter(Boolean)

    return (
        <div>
            <PageHeader

                isSkeleton={isSkeleton}
                breadcrumb={
                    breadcrumbItems?.length
                        ? ({ isSkeleton: skeleton }: SkeletonProps) => (
                            <div className="w-fit">
                                {/* collapse: below @app-sm or trail ≥ 4 crumbs → back-link (the old
                        capability of ResponsiveBreadcrumb, now a prop of the Breadcrumbs atom). */}
                                <Breadcrumbs
                                    collapseOnMobile
                                    collapseFrom={4}
                                    items={breadcrumbItems ?? []}
                                    isSkeleton={skeleton}
                                />
                            </div>
                        )
                        : undefined
                }
                title={title}
                description={description}
                meta={
                    metaParts.length > 0
                        ? () => (
                            <span>
                                <Typography size="xs" color="muted" text={metaParts.join(" · ")} />
                            </span>
                        )
                        : undefined
                }
            />
        </div>
    )
}

/** `CourseBrief.*` — single-component namespace ⇒ only `.Base`. */
export { CourseBriefBase as CourseBrief }

import React, { useState } from "react"
import { type SkeletonProps } from "@sb-components/frames/_slot"
import { Avatar } from "@sb-components/atoms/display/Avatar/Avatar"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { InputTextarea } from "@sb-components/atoms/forms"
import { InputButtonLike } from "@sb-components/composites/buttons/InputButtonLike/InputButtonLike"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * BLOCK — `CourseQaComposer`: the ONE writing shape reused three ways on a
 * course Q&A board — the root "ask the whole course" collapsible pill, an
 * answer's inline edit form, and an inline reply form. See the component file
 * header for the full mode/`initialValue`/fold-back contract and why this is
 * genuinely new rather than a duplicate of `_legacy/blocks/feed/Composer`.
 */

/** Which of the block's two writing shapes to render. */
export type CourseQaComposerMode = "collapsible" | "plain"

/** The signed-in viewer writing this — plain data, the block builds the avatar from it. */
export interface CourseQaComposerUser {
    /** Display name; also seeds the avatar's initials fallback. */
    name: string
    /** Avatar image URL. Omitted → the avatar falls back per its own chain. */
    avatarSrc?: string
}

/** Props for {@link CourseQaComposer}. */
export interface CourseQaComposerProps {
    /**
     * `"collapsible"` — boots as a slim avatar + placeholder pill, opens into the
     * full form on press (the root "ask the whole course" composer). `"plain"` —
     * always the full form (an answer's inline edit, an inline reply, or a
     * bottom "write an answer" box).
     */
    mode: CourseQaComposerMode
    /** The signed-in viewer. Omitted → no leading avatar is drawn (either shape). */
    currentUser?: CourseQaComposerUser
    /**
     * Existing content this composer opened WITH (an edit/reply reopened, not a
     * fresh draft). Read once, only to decide a `"collapsible"` composer's BOOT
     * state — see the file header. Never re-consulted after mount; the live
     * draft is entirely `value`/`onValueChange`.
     */
    initialValue?: string
    /** The current draft text — fully controlled by the caller. */
    value: string
    /** Fired with the next draft text on every keystroke. */
    onValueChange: (value: string) => void
    /** Placeholder for both the collapsed pill and the open textarea. */
    placeholder?: string
    /** Label for the submit button. Defaults to `"Send"`. */
    submitLabel?: string
    /**
     * Fired when the viewer submits. The caller already holds the draft via
     * `value`, so this fires with no argument. A `"collapsible"` composer folds
     * itself back to the pill right after — the caller is still responsible for
     * clearing `value`.
     */
    onSubmit: () => void
    /**
     * Fired when the viewer backs out. Shown whenever `mode === "collapsible"`
     * (folding back to the pill always needs a way out) or whenever the caller
     * supplies this (the edit/reply shapes of `mode === "plain"`).
     */
    onCancel?: () => void
    /** `true` → submit is in flight: the Submit button owns the busy affordance and both buttons lock. */
    isPending?: boolean
    /**
     * `true` → every composed atom mirrors itself. The flag FLOWS DOWN into the
     * real atoms (§12c) rather than a parallel skeleton tree, within whichever
     * leaf (`CollapsedPrompt`/`ExpandedForm`) is currently showing.
     */
    isSkeleton?: boolean
}

/**
 * The Q&A board's one writing shape. See the file header for the mode
 * contract, the controlled-text/`initialValue` split, and the fold-back
 * judgement call.
 *
 * @param props - {@link CourseQaComposerProps}
 */
const CourseQaComposer = ({
    mode,
    currentUser,
    initialValue,
    value,
    onValueChange,
    placeholder,
    submitLabel = "Send",
    onSubmit: onSubmitAction,
    onCancel: onCancelAction,
    isPending = false,
    isSkeleton = false,
}: CourseQaComposerProps) => {
    // Transient UI-only chrome (§ not domain data) — owned here, never lifted to
    // the caller. A "plain" composer has no collapsed shape at all, so it always
    // boots open; a "collapsible" one boots open only when reopened WITH content.
    const [expanded, setExpanded] = useState(() => mode === "plain" || Boolean(initialValue))

    const canSubmit = value.trim().length > 0 && !isPending
    const showCancel = mode === "collapsible" || onCancelAction != null

    const onSubmit = () => {
        onSubmitAction()
        // Folding back is presentational chrome the block owns; the caller still
        // clears `value` itself (it owns the draft) — see file header.
        if (mode === "collapsible") {
            setExpanded(false)
        }
    }

    const onCancel = () => {
        if (mode === "collapsible") {
            setExpanded(false)
        }
        onCancelAction?.()
    }

    const avatar = currentUser || isSkeleton ? (
        <Avatar
            name={currentUser?.name}
            src={currentUser?.avatarSrc}
            size="sm"
            isSkeleton={isSkeleton}


        />
    ) : null

    // ── LEAF — CollapsedPrompt: avatar + pill, nothing else composed ──────────
    if (mode === "collapsible" && !expanded) {
        return (
            <div>
                <StackH
                    gap={3}
                    isSkeleton={isSkeleton}
                    items={[
                        () => avatar,
                        () => (
                            <div className="min-w-0 flex-1">
                                <InputButtonLike
                                    placeholder={placeholder ?? "Ask a question about this course…"}
                                    onPress={() => setExpanded(true)}
                                    isSkeleton={isSkeleton}
                                />
                            </div>
                        ),
                    ]}
                />
            </div>
        )
    }

    // ── LEAF — ExpandedForm: avatar + textarea + action row ───────────────────
    return (
        <div>
            <StackH
                gap={3}
                isSkeleton={isSkeleton}
                items={[
                    () => avatar,
                    ({ isSkeleton }: SkeletonProps) => (
                        <StackV
                            gap={3}
                            isSkeleton={isSkeleton}
                            classNames={["min-w-0", "flex-1"]}
                            items={[
                                () => (
                                    <InputTextarea
                                        value={value}
                                        onValueChange={onValueChange}
                                        placeholder={placeholder}
                                        ariaLabel={placeholder ?? "Content"}
                                        rows={3}
                                        isDisabled={isPending}
                                        isSkeleton={isSkeleton}

                                    />
                                ),
                                () => (
                                    <StackH
                                        gap={3}
                                        principle="flex-action"
                                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                        justify="end"
                                        isSkeleton={isSkeleton}
                                        items={[
                                            ...(showCancel ? [() => (
                                                <Button
                                                    label="Cancel"
                                                    variant="tertiary"
                                                    size="sm"
                                                    onPress={onCancel}
                                                    isDisabled={isPending}
                                                    isSkeleton={isSkeleton}

                                                />
                                            )] : []),
                                            () => (
                                                <Button
                                                    label={submitLabel}
                                                    variant="primary"
                                                    size="sm"
                                                    onPress={onSubmit}
                                                    isDisabled={!canSubmit}
                                                    isPending={isPending}
                                                    isSkeleton={isSkeleton}

                                                />
                                            ),
                                        ]}
                                    />
                                ),
                            ]}
                        />
                    ),
                ]}
            />
        </div>
    )
}

export { CourseQaComposer }

import React from "react"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { StackV } from "@sb-components/frames/Stack/Stack"

/**
 * BLOCK — `CourseQaEngagementStrip`: the "you're not learning alone" honest
 * aggregate under `CourseQaHeader` on a course Q&A board — enrolled learners,
 * then answered/total questions. See the component file header for the full
 * real-numbers-only contract and the leaf/state judgement call.
 */

/** Props for {@link CourseQaEngagementStrip}. */
export interface CourseQaEngagementStripProps {
    /**
     * Learners enrolled in the course this Q&A board belongs to. `undefined` →
     * the caller has no honest number to show yet, so the enrollment line is
     * dropped entirely rather than showing a placeholder. `0` still prints —
     * it's a real fact, not "unknown".
     */
    enrollmentCount?: number
    /** Total questions ever asked on this board. */
    totalQuestions: number
    /** Of {@link CourseQaEngagementStripProps.totalQuestions}, how many have at least one answer. */
    answeredQuestions: number
    /**
     * `true` → both lines shimmer. The flag FLOWS DOWN into the real
     * `Typography` atoms (§12c) rather than a parallel skeleton tree.
     */
    isSkeleton?: boolean
}

/**
 * The board's second line — real answered/total, or an honest admission that
 * nothing has been asked yet. Never a computed ratio from zero questions.
 */
const questionLine = (totalQuestions: number, answeredQuestions: number): string => {
    if (totalQuestions <= 0) {
        return "No questions asked yet"
    }
    return `${answeredQuestions}/${totalQuestions} questions answered`
}

/**
 * The board's honest engagement readout. See the file header for the full
 * contract.
 *
 * @param props - {@link CourseQaEngagementStripProps}
 */
const CourseQaEngagementStrip = ({
    enrollmentCount,
    totalQuestions,
    answeredQuestions,
    isSkeleton = false,
}: CourseQaEngagementStripProps) => {
    const hasEnrollment = enrollmentCount != null

    return (
        <div>
            <StackV
                gap={1}
                isSkeleton={isSkeleton}
                items={[
                    ...(isSkeleton || hasEnrollment ? [() => (
                        <Typography
                            size="sm"
                            color="muted"
                            isSkeleton={isSkeleton}
                            text={hasEnrollment ? `${enrollmentCount!.toLocaleString("vi-VN")} learners enrolled in this course` : undefined}

                        />
                    )] : []),
                    () => (
                        <Typography
                            size="sm"
                            color="muted"
                            isSkeleton={isSkeleton}
                            text={isSkeleton ? undefined : questionLine(totalQuestions, answeredQuestions)}

                        />
                    ),
                ]}
            />
        </div>
    )
}

