import React from "react"
import { PushPinIcon, SealCheckIcon } from "@phosphor-icons/react"
import { Avatar } from "@sb-components/atoms/display/Avatar/Avatar"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import type { ComponentTypeWithSkeleton } from "@sb-components/frames/_slot"
import { StackV, StackH } from "@sb-components/frames/Stack/Stack"
import { Cluster } from "@sb-components/frames/Cluster/Cluster"
import { type CourseQaQuestionItem, type CourseQaQuestionScope } from "../types"

/** The block's own scope→label vocabulary (§14d.1) — never handed in pre-formatted. */
const scopeLabel = (scope: CourseQaQuestionScope): string =>
    scope.kind === "lesson" ? `Lesson: ${scope.lessonTitle}` : "General"

/** The block's own status→label vocabulary (§14d.1). */
const statusLabel = (replyCount: number, answeredByFounder?: boolean): string => {
    if (replyCount <= 0) {
        return "Not answered yet"
    }
    return answeredByFounder ? "Instructor answered" : "Answered"
}

/** Props for {@link QuestionPreviewRow}. */
interface QuestionPreviewRowProps {
    question: CourseQaQuestionItem
    currentUserId: string | null
}

/**
 * TEMPORARY GAP STAND-IN for the not-yet-built `QaQuestionThread` block — see
 * the file header's GAP note (*2). Renders the COLLAPSED look only (real data,
 * real atoms), no expand/reply behaviour: pressing does nothing, because
 * inventing a fake "open the thread" affordance here would be worse than
 * honestly having none yet.
 */
export const QuestionPreviewRow = ({ question, currentUserId }: QuestionPreviewRowProps) => {
    const isMine = currentUserId != null && currentUserId === question.author.id
    const isAnswered = question.replyCount > 0
    const askerName = isMine ? "You" : question.author.displayName

    // ONE chip for the row's classification axis (status — the thing worth scanning
    // the list for); the scope rides as plain muted text beside it instead of a
    // second chip (eslint `starci-fe/no-adjacent-chip`, *7).
    const chips: Array<ComponentTypeWithSkeleton> = [
        () => <Typography size="xs" color="muted" text={scopeLabel(question.scope)} />,
        () => (
            <Chip
                tone={isAnswered ? "success" : "default"}
                text={statusLabel(question.replyCount, question.answeredByFounder)}

            />
        ),
    ]
    if (isAnswered) {
        // no icon here — §5a.2: a chat-bubble needs an ASSOCIATION step to read as
        // "replies" (not a universal symbol like check/locklock), and the text already carries
        // the fact on its own (same fix already applied to QaQuestionThread/QaConversationHeader).
        chips.push(() => (
            <Typography size="xs" color="muted" text={`${question.replyCount} replies`} />
        ))
    }

    const textColumnItems = [
        () => (
            <StackH
                gap={2}
                items={[
                    ...(question.isPinned ? [() => (
                        <PushPinIcon weight="fill" aria-hidden focusable="false" className="size-3.5 shrink-0 text-accent-soft-foreground" />
                    )] : []),
                    () => <Typography size="xs" weight="medium" text={askerName} />,
                    ...(question.isFounderAuthor ? [() => (
                        <SealCheckIcon weight="fill" aria-hidden focusable="false" className="size-3.5 shrink-0 text-accent-soft-foreground" />
                    )] : []),
                    () => <Typography size="xs" color="muted" text={`· ${question.createdTimeAgo}`} />,
                ]}
            />
        ),
        () => <Typography size="sm" lineClamp={2} text={question.preview} />,
        () => <Cluster gap={3} items={chips} />,
    ]

    return (
        <StackH
            gap={4}
            principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            align="start"

            items={[
                () => (
                    <div className="shrink-0">
                        <Avatar
                            src={question.author.avatarUrl}
                            name={question.author.displayName}
                            seed={question.author.id}
                            size="sm"

                        />
                    </div>
                ),
                () => <StackV gap={2} classNames={["min-w-0", "flex-1"]} items={textColumnItems} />,
                () => (
                    <span
                        aria-hidden
                        className={`size-2 shrink-0 rounded-full ${isAnswered ? "bg-success" : "bg-warning"}`}
                    />
                ),
            ]}
        />
    )
}

import React from "react"
import { Skeleton as HeroSkeleton } from "@heroui/react"
import { Avatar } from "@sb-components/atoms/display/Avatar/Avatar"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { StackV, StackH } from "@sb-components/frames/Stack/Stack"

/**
 * One placeholder row for the Loading branch — avatar + 2 text bars +
 * chip-pill row + status dot, ported verbatim from the real
 * `CourseQaSkeleton.tsx` shape (*1).
 *
 * `align="start"` on the outer row (instead of the real file's `mt-2` on the
 * dot) top-aligns all three children without a child pushing its own margin
 * (§10a — the padding gate only allows a parent's `gap`/surface `padding` to
 * own a seam).
 */
export const SkeletonQuestionRow = () => {
    return (
        <StackH identity={{ tier: "block", component: "SkeletonQuestionRow" }}
            gap={4}
            principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            align="start"

            items={[
                () => (
                    <div className="shrink-0">
                        <Avatar isSkeleton size="sm" />
                    </div>
                ),
                () => (
                    <StackV
                        gap={2}
                        classNames={["min-w-0", "flex-1"]}
                        items={[
                            // asker + time line
                            () => <Typography size="xs" isSkeleton />,
                            // two-line preview
                            () => (
                                <StackV
                                    gap={2}
                                    items={[
                                        () => <Typography size="sm" isSkeleton />,
                                        () => <Typography size="sm" isSkeleton />,
                                    ]}
                                />
                            ),
                            // chip-pill row — ONE chip (status, the classification axis) + the scope
                            // as a plain shimmer bar, matching the real row's own text-inline treatment
                            // (eslint `starci-fe/no-adjacent-chip`, *7 below).
                            () => (
                                <StackH
                                    gap={3}
                                    items={[
                                        () => <Typography size="xs" isSkeleton />,
                                        () => <Chip isSkeleton />,
                                    ]}
                                />
                            ),
                        ]}
                    />
                ),
                // status dot — no home atom (*3), same escape hatch `Pagination` uses for its own shimmer squares
                () => <HeroSkeleton className="size-2 shrink-0 rounded-full" />,
            ]}
        />
    )
}

import React from "react"
import { Toolbar } from "@sb-components/composites/navigation/Toolbar/Toolbar"
import { InputSearch } from "@sb-components/atoms/forms"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `CourseQaToolbar` — the control strip above a course Q&A question list:
 * status/scope filter tabs, a search field, and a live match count. Two stacked
 * rows — the filter tabs go through `Toolbar` (leftTabs only), while the search
 * field + count are hand-composed in a `StackH` beside them. One leaf: active
 * filter, search text, and count loading are all data on the same two-row shape.
 */

/** Status/scope filter for the course-wide Q&A roll-up. Mirrors `src`'s `CourseQuestionFilter`. */
export type CourseQaFilter = "unanswered" | "answered" | "engagement" | "mine" | "all"

/** Filter tabs in display order — the block's own vocabulary (§14d.1). */
const FILTER_ORDER: ReadonlyArray<CourseQaFilter> = ["unanswered", "answered", "engagement", "mine", "all"]

/** Filter → tab label, ported verbatim from `vi.json`'s `courseQa.filter.*`. */
const FILTER_LABEL: Record<CourseQaFilter, string> = {
    unanswered: "Unanswered",
    answered: "Answered",
    engagement: "Most active",
    mine: "Mine",
    all: "All",
}

/** The board's own count wording — the caller hands over a bare number, never a formatted string. */
const resultCountLabel = (count: number): string => `${count} questions`

/** Props for {@link CourseQaToolbar}. */
export interface CourseQaToolbarProps {
    /** Which status/scope filter is active. */
    filter: CourseQaFilter
    /** Fired with the filter the reader picked. */
    onFilterChange: (filter: CourseQaFilter) => void
    /** Current text in the search field (controlled; the screen owns debouncing). */
    searchValue: string
    /** Fired with the new query on every keystroke. */
    onSearchChange: (value: string) => void
    /** How many questions the active filter + search matched. */
    resultCount: number
    /** Accessible name for the filter tab row, localized by the caller (blocks carry no i18n). */
    filterAriaLabel: string
    /**
     * `true` → the result count shimmers instead of printing a number. Scoped to
     * the count only — see the file header for why the tabs and search field
     * never skeletonise.
     */
    isSkeleton?: boolean
}

/**
 * The Q&A board's control strip. See the file header for why the two rows
 * cannot collapse into one `Toolbar` call and why only the count skeletonises.
 *
 * @param props - {@link CourseQaToolbarProps}
 */
const CourseQaToolbar = ({
    filter,
    onFilterChange,
    searchValue,
    onSearchChange,
    resultCount,
    filterAriaLabel,
    isSkeleton = false,
}: CourseQaToolbarProps) => {
    const items = FILTER_ORDER.map((value) => ({
        key: value,
        label: FILTER_LABEL[value],
    }))

    return (
        <div>
            <StackV
                gap={4}
                isSkeleton={isSkeleton}
                items={[
                    () => (
                        <div>
                            <Toolbar
                                leftTabs={{
                                    items,
                                    selectedKey: filter,
                                    ariaLabel: filterAriaLabel,
                                    onSelectionChange: (key) => onFilterChange(String(key) as CourseQaFilter),
                                }}

                            />
                        </div>
                    ),
                    () => (
                        <StackH
                            gap={3}
                            principle="flex-action"
                            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                            justify="between"
                            at="sm"
                            isSkeleton={isSkeleton}
                            items={[
                                () => (
                                    <div className="min-w-0 flex-1 @app-sm:max-w-sm">
                                        <InputSearch
                                            value={searchValue}
                                            onValueChange={onSearchChange}
                                            placeholder="Search questions..."
                                            ariaLabel="Search questions"

                                        />
                                    </div>
                                ),
                                () => (
                                    isSkeleton ? (
                                        <Typography
                                            size="sm"
                                            color="muted"
                                            isSkeleton


                                        />
                                    ) : (
                                        <Typography
                                            size="sm"
                                            color="muted"
                                            tabularNums
                                            text={resultCountLabel(resultCount)}


                                        />
                                    )
                                ),
                            ]}
                        />
                    ),
                ]}
            />
        </div>
    )
}

export { CourseQaToolbar }

import React from "react"
import type { ReactNode } from "react"
import { Skeleton as HeroSkeleton, cn } from "@heroui/react"
import { ArrowRightIcon, LockIcon } from "@phosphor-icons/react"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { IconTile } from "@sb-components/atoms/display/IconTile/IconTile"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { AsyncContent } from "@sb-components/composites/async/AsyncContent/AsyncContent"
import { SurfaceCard } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { Box } from "@sb-components/frames/Box/Box"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"
import { PhaseScarcityNote, type PricingPhase } from "@sb-components/starci/blocks/commerce/PhaseScarcityNote/PhaseScarcityNote"
import { PriceTagProminent, type PriceBreakdown } from "@sb-components/starci/blocks/commerce/PriceTag/PriceTag"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"

/**
 * `EnrollGate` — the conversion card shown in place of an enrollment-required
 * learn surface (currently personal-project) for a trial viewer. Kept separate
 * from `ContentPaywall` despite composing the same two commerce blocks. Four
 * leaves: `Standalone` (no `preview`, centered), `WithPreview` (floats over a
 * faded teaser), `NoScarcity` (no `price.currentPhase`, drops
 * `PhaseScarcityNote`), and `Loading` (`isSkeleton`, price region shimmers).
 */

/**
 * Named price shape for {@link EnrollGateProps.price} — see the file header's
 * "THE `price` PROP IS A NEW NAME" note for why this isn't just `PriceBreakdown`.
 */
export interface EnrollGatePrice {
    /** Price the learner actually pays, in VND. */
    discountedVnd: number
    /** Pre-discount VND price; `PriceTagProminent` strikes it through when greater. */
    originalVnd?: number | null
    /** Phase-tier + loyalty steps for `PriceTagProminent`'s breakdown popover. */
    breakdown?: PriceBreakdown
    /** Current pricing phase — drives the scarcity line. Omit → no scarcity line. */
    currentPhase?: PricingPhase
    /** Seats left in the current phase. `null`/omitted → unlimited, scarcity line stays silent. */
    seatsRemaining?: number | null
    /** What the next phase will cost — the honest "waiting is not free" fact. */
    nextPhasePriceVnd?: number | null
}

/** Props for {@link EnrollGate}. */
export interface EnrollGateProps {
    /** Headline, localized by the caller — e.g. "Unlock Personal Project". */
    title: string
    /** One-line reason the surface needs enrollment. */
    description: string
    /**
     * Optional MOCK teaser of the gated surface (e.g. `PersonalProjectGatePreview`)
     * — non-interactive, rendered `aria-hidden` behind a bottom fade with the
     * enroll card floating over it. Omit → just the centered enroll card.
     */
    preview?: ReactNode
    /**
     * Resolved price + scarcity data. `undefined` → the price region shows the
     * `AsyncContent` shimmer (not yet resolved); the lock/headline/description/CTA
     * stay real regardless.
     */
    price?: EnrollGatePrice
    /** Fired when the learner takes the enroll CTA. */
    onEnroll: () => void
    /**
     * `true` → force the price region into its shimmer state even if `price` is
     * already known (used by this block's own "Loading" story state). The lock,
     * headline, description and CTA never shimmer — see the file header.
     */
    isSkeleton?: boolean
    /**
     * Where this sits inside its parent. Appearance is not passable — it is already a prop.
     * Prefer this over `className`; the string form is going away.
     */
    classNames?: Array<AllowedClassName>
}

/**
 * The conversion card in front of a gated learn surface. See the file header
 * for the full contract.
 *
 * @param props - {@link EnrollGateProps}
 */
const EnrollGateBase = ({
    title,
    description,
    preview,
    price,
    onEnroll,
    isSkeleton = false,
    classNames,
}: EnrollGateProps) => {
    // no price to show yet (unresolved) OR the caller forces the loading state —
    // either way the price region falls to the AsyncContent shimmer branch.
    const priceLoading = isSkeleton || price == null

    // The price group only exists once `price` has resolved — kept as its own
    // named const because it depends on `price` and is only used inside the
    // `AsyncContent` content branch below.
    const priceGroup = price != null ? (
        <>
            <PriceTagProminent
                discounted={price.discountedVnd}
                original={price.originalVnd}
                breakdown={price.breakdown}
                classNames={["self-center"]}
            />
            {price.currentPhase != null ? (
                <Box className="self-center">
                    <PhaseScarcityNote
                        currentPhase={price.currentPhase}
                        seatsRemaining={price.seatsRemaining ?? null}
                        nextPhasePriceVnd={price.nextPhasePriceVnd ?? null}
                    />
                </Box>
            ) : null}
        </>
    ) : null

    // lock identity + outcome copy + price + scarcity + one CTA — everything
    // the conversion card's own `StackV` arranges.
    const offerBody = (
        <>
            <IconTile
                icon={LockIcon}
                tone="accent"
                size="sm"

            />
            {/* the real src (`EnrollGate/index.tsx:67`): `type="h4" weight="bold"` — a real
                HEADING (20px), not body `lg` (18px). */}
            <Typography
                size="h4"
                weight="bold"
                align="center"
                text={title}

            />
            <Typography
                size="sm"
                color="muted"
                align="center"
                text={description}

            />
            <AsyncContent
                isLoading={priceLoading}
                skeleton={() => <HeroSkeleton className="h-7 w-32 rounded-xl" />}
                content={() => <StackV gap={4} principle="card-caption"
                    explain="Holds caption text under card media so the caption stays attached to the image above it."
                    align="center" isSkeleton={isSkeleton} items={[() => priceGroup]} />}
            />
            <Button
                label="Enroll now"
                variant="primary"
                size="lg"
                suffixIcon={ArrowRightIcon}
                iconSlide
                onPress={onEnroll}


            />
        </>
    )

    // the conversion card itself: lock identity + outcome copy + price + scarcity
    // + one CTA. A real SurfaceCard so it "floats up" whether it sits alone on
    // the canvas or over the faded teaser.
    const card = (
        // `SurfaceCard.className` door was deleted (COMPOSITE-4) and `max-w-[480px]` is an
        // arbitrary value outside the closed `AllowedClassName` union anyway — no frame's
        // typed `classNames` can carry it. `Box` centres via `principle="center-measure"`
        // (the real `mx-auto`) and keeps the raw width class as its escape-hatch `className`.
        // TODO(atom): `max-w-[480px]` still wants its own typed sizing step (or a matching
        // `Container` size) so this card stops needing the escape hatch at all.
        <Box principle="center-measure"
            explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport."
            className="w-full max-w-[480px]">
            <SurfaceCard
                padding={6}

                body={() => <StackV gap={4} principle="content-row"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                    align="center" isSkeleton={isSkeleton} items={[() => offerBody]} />}
            />
        </Box>
    )

    // no teaser → just the centered enroll card. `StackH` with a single child and
    // `gap={1}` (no seam to enforce with one item) is how the §10 scale still
    // governs the wrapper's padding instead of a hand-typed `p-*` value.
    if (preview == null) {
        return (
            <StackH gap={1} principle="page-pad"
                explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface."
                justify="center" padding={6} isSkeleton={isSkeleton} classNames={classNames} items={[() => card]}  />
        )
    }

    // teaser → the FULL preview (no height cap — mirrors `ContentArticle`, which
    // renders the whole real body and only fades its tail, never truncates
    // early), with the enroll card floating over the faded tail.
    return (
        <div className={cn("relative", classNames)}>
            <div aria-hidden className="pointer-events-none relative">
                {preview}
                {/* Same fade band as `ContentArticle`'s locked-body tail — fades into
                    the preview's OWN card token (`bg-surface`), not the page canvas,
                    since the teaser content is itself `bg-surface` cards. */}
                <div className="absolute inset-x-0 bottom-0 h-72 bg-gradient-to-b from-transparent via-surface/70 to-surface" />
            </div>
            {/* `padding={6}` (the frame's own §10c scale) replaces the hand-typed
                `px-4 pb-6` the real component used — the ONE deviation from a byte-for-byte
                port, since the scale is symmetric and has no asymmetric step. `-mt-32` stays
                hand-written: it is the float-over-the-fade OVERLAP effect itself, not a seam
                between siblings, the same idiom as `SurfaceCard.Pressable`'s highlight layer. */}
            <div className="relative z-10 -mt-32">
                <StackH gap={1} principle="page-pad"
                    explain="Page chrome inset — not card-padding, because this pads the whole page rather than a nested card surface."
                    justify="center" padding={6} isSkeleton={isSkeleton} items={[() => card]}  />
            </div>
        </div>
    )
}

/** `EnrollGate.*` — single-component namespace ⇒ only `.Base`. */
export { EnrollGateBase as EnrollGate }

import React from "react"
import { CaretRightIcon, CardsIcon, MagnifyingGlassIcon, RowsIcon, SquaresFourIcon } from "@phosphor-icons/react"
import { InputSearch } from "@sb-components/atoms/forms"
import { Tabs, type TabItem } from "@sb-components/atoms/navigation/Tabs/Tabs"
import { Pagination } from "@sb-components/atoms/navigation/Pagination/Pagination"
import { ProgressGauge } from "@sb-components/atoms/display/Progress/Progress"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import {
    SurfaceCard,
    SurfaceCardList,
    type SurfaceCardListItem,
} from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { AsyncContentEmpty } from "@sb-components/composites/async/AsyncContent/AsyncContent"
import { Grid, type GridItem } from "@sb-components/frames/Grid/Grid"
import { Cluster } from "@sb-components/frames/Cluster/Cluster"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"
import type { ComponentTypeWithSkeleton } from "@sb-components/frames/_slot"
import { VariantChipDifficulty, type Difficulty } from "@sb-components/starci/blocks/learn/VariantChip/VariantChip"

/**
 * `FlashcardDeckList` — the course's deck picker: search, switch between a grid
 * of tiles and a scan-friendly line list, page through results, and open any
 * deck. Four leaves: `GridView` (tiles in a responsive `Grid`), `LineView`
 * (rows in one `SurfaceCardList`), `SearchEmpty` (`AsyncContentEmpty`,
 * view-agnostic), and `Loading` (a guessed tile count through each composite's
 * mirror). Toggling `view` or `isSkeleton` on a populated list repaints the same
 * tree.
 */

/** How the deck track is currently laid out. Persisted by the caller, not a leaf-driving prop by itself (see file header). */
export type FlashcardDeckListView = "grid" | "line"

/** One deck row/tile — plain DATA; the block decides which chips and meters it earns. */
export interface FlashcardDeckListDeck {
    /** Stable id — the React key, and what `onSelectDeck` fires with. */
    id: string
    /** Deck title. */
    title: string
    /** Optional blurb. Grid: clamped to two lines. Line: the row's subtitle (falls back to a card count when absent). */
    description?: string
    /** Difficulty tier — the block builds `VariantChipDifficulty` itself. */
    difficulty: Difficulty
    /** Cards due for review right now. Omit or `0` → no due chip (see file header). */
    dueCount?: number
    /** Cards the viewer has already mastered. Paired with `totalCount` for the mastery meter. */
    masteredCount?: number
    /** Total cards in the deck. */
    totalCount: number
}

/** Props for {@link FlashcardDeckList}. */
export interface FlashcardDeckListProps {
    /** The current page's decks, in display order. */
    decks: Array<FlashcardDeckListDeck>
    /** Current search text (controlled). */
    query: string
    /** Fired on every keystroke in the search field. */
    onQueryChange: (query: string) => void
    /** Which shape the track renders as — a persisted VIEWER SETTING, not a one-off UI toggle. */
    view: FlashcardDeckListView
    /** Fired with the shape the viewer picked. */
    onViewChange: (view: FlashcardDeckListView) => void
    /** 1-based current page. */
    page: number
    /** Total page count — see the file header's "added prop" note. */
    totalPages: number
    /** Fired with the 1-based page the viewer picked. */
    onPageChange: (page: number) => void
    /** Fired with a deck's id when its tile/row is pressed. */
    onSelectDeck: (id: string) => void
    /** Overrides the default grid-tile CTA wording ("Study now"). Localization override, not domain data (mirrors `seeMoreLabel`/`removeLabel`). */
    ctaLabel?: string
    /** `true` → grid tiles and list rows also carry the per-viewer mastery meter. `false` → a plain browse surface with no progress talk. */
    showProgress: boolean
    /** `true` → the track renders its own mirror. `decks` empty while on → guesses a placeholder count in the current `view`'s shape (§12c). */
    isSkeleton?: boolean
}

/** The block's own wording for the grid-tile CTA — overridable via `ctaLabel`. */
const DEFAULT_CTA_LABEL = "Study now"

/** View-toggle tabs — icon only, labels are `sr-only` (the atom takes a `ReactNode` label, so this is within its own contract, not a hack around it). */
const VIEW_ITEMS: Array<TabItem> = [
    { key: "grid", label: <span className="sr-only">Grid view</span>, icon: SquaresFourIcon },
    { key: "line", label: <span className="sr-only">List view</span>, icon: RowsIcon },
]

/** Placeholder rows/tiles for the guessed skeleton count (§12c) — never carry a press handler. */
const skeletonDecks = (count: number): Array<FlashcardDeckListDeck> =>
    Array.from({ length: count }, (_unused, index) => ({
        id: `skeleton-${index}`,
        title: "",
        difficulty: "beginner" as Difficulty,
        totalCount: 0,
    }))

/**
 * The block's decision at a glance:
 * ─────────────────────────────────────────────────────────────────────────────
 * DECIDE → track is empty (search or fetch found nothing) → LEAF 3, everything below skipped
 *        → still no decks AND still loading           → LEAF 4, placeholder count
 *        → view === "grid"                            → LEAF 1
 *        → view === "line"                             → LEAF 2
 * ─────────────────────────────────────────────────────────────────────────────
 *
 * @param props - {@link FlashcardDeckListProps}
 */
const FlashcardDeckList = ({
    decks,
    query,
    onQueryChange,
    view,
    onViewChange,
    page,
    totalPages,
    onPageChange,
    onSelectDeck,
    ctaLabel,
    showProgress,
    isSkeleton = false,
}: FlashcardDeckListProps) => {
    // Empty while loading (no real decks yet) → guess a placeholder count in the
    // CURRENT view's shape, keeping the right footprint for when real data lands
    // (§8). Once real `decks` exist, keep the exact count already there.
    const usingPlaceholders = isSkeleton && decks.length === 0
    const source = usingPlaceholders ? skeletonDecks(view === "grid" ? 6 : 4) : decks

    // LEAF 3 — the whole track is replaced by the message; nothing below runs.
    // Reached whether `view` is grid or line, so it forks on data, not on shape.
    const isEmpty = !isSkeleton && decks.length === 0
    const hasQuery = query.trim().length > 0

    /** One grid tile's content — computed only when it will actually render (skeleton tiles never see it). */
    const deckTileBody = (deck: FlashcardDeckListDeck) => {
        const chips: Array<ComponentTypeWithSkeleton> = [
            () => <VariantChipDifficulty difficulty={deck.difficulty} />,
        ]
        if (deck.dueCount) {
            chips.push(() => <Chip tone="warning" text={`${deck.dueCount} due`} />)
        }

        return (
            <StackV
                gap={3}
                isSkeleton={isSkeleton}
                items={[
                    () => (
                        <StackV
                            gap={1}
                            isSkeleton={isSkeleton}
                            items={[
                                () => <Typography size="sm" weight="medium" truncate text={deck.title} />,
                                ...(deck.description ? [() => (
                                    <Typography size="xs" color="muted" lineClamp={2} text={deck.description} />
                                )] : []),
                            ]}
                        />
                    ),
                    () => <Cluster gap={3} items={chips} />,
                    ...(showProgress && deck.totalCount > 0 ? [() => (
                        <StackH
                            gap={2}
                            isSkeleton={isSkeleton}
                            items={[
                                () => (
                                    <div className="flex-1">
                                        <ProgressGauge
                                            value={((deck.masteredCount ?? 0) / deck.totalCount) * 100}
                                            size="sm"
                                            ariaLabel={`Mastery level for the ${deck.title} deck`}

                                        />
                                    </div>
                                ),
                                () => (
                                    <Typography
                                        size="xs"
                                        color="muted"
                                        text={`${deck.masteredCount ?? 0}/${deck.totalCount}`}

                                    />
                                ),
                            ]}
                        />
                    )] : []),
                    () => (
                        <StackH
                            gap={2}
                            principle="icon-text"
                            explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
                            justify="end"
                            isSkeleton={isSkeleton}
                            items={[
                                () => (
                                    <Typography
                                        size="sm"
                                        weight="medium"
                                        color="accent-soft"
                                        text={ctaLabel ?? DEFAULT_CTA_LABEL}

                                    />
                                ),
                                () => (
                                    <CaretRightIcon aria-hidden focusable="false" weight="bold" className="size-4 shrink-0 text-accent-soft-foreground" />
                                ),
                            ]}
                        />
                    ),
                ]}
            />
        )
    }

    const tiles: Array<GridItem> = source.map((deck) => ({
        key: deck.id,
        content: () => (
            <div>
                <SurfaceCard
                    isSkeleton={isSkeleton}
                    // Always set, even during a placeholder tile: `Base`'s skeleton-mirror
                    // branch intercepts BEFORE this ever reaches a real button (see
                    // SurfaceCard.tsx), so it's inert while `isSkeleton` is true — it only
                    // needs to be present so the merged `.Pressable` shape (not the plain
                    // `SurfaceCard` shape) is the one that renders once loading finishes.
                    onPress={() => onSelectDeck(deck.id)}
                    ariaLabel={deck.title}

                    body={() => (isSkeleton ? null : deckTileBody(deck))}
                />
            </div>
        ),
    }))

    const rows: Array<SurfaceCardListItem> = source.map((deck) => {
        const metaChips: Array<ComponentTypeWithSkeleton> = []
        if (!isSkeleton) {
            metaChips.push(() => <VariantChipDifficulty difficulty={deck.difficulty} />)
            if (deck.dueCount) {
                metaChips.push(() => <Chip tone="warning" text={`${deck.dueCount} due`} />)
            }
        }
        return {
            key: deck.id,
            leadingIcon: CardsIcon,
            title: deck.title,
            // The block owns this fallback (§14d.1): a deck with no blurb still says
            // something useful — its card count — instead of a blank second line.
            subtitle: deck.description ?? `${deck.totalCount} cards`,
            meta: metaChips.length > 0 ? () => <Cluster gap={3} items={metaChips} /> : undefined,
            trailing:
                showProgress && !isSkeleton && deck.totalCount > 0
                    ? () => <Typography size="xs" color="muted" text={`${deck.masteredCount ?? 0}/${deck.totalCount}`} />
                    : undefined,
            onPress: usingPlaceholders ? undefined : () => onSelectDeck(deck.id),
        }
    })

    const track = isEmpty ? (
        <AsyncContentEmpty
            icon={hasQuery ? MagnifyingGlassIcon : undefined}
            title={hasQuery ? `No decks match “${query}”` : "This course has no decks yet"}
            description={hasQuery ? "Try a different search term." : undefined}


        />
    ) : view === "grid" ? (
        <div>
            <Grid columns={{ base: 1, sm: 2, md: 3 }} principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={tiles}  />
        </div>
    ) : (
        <SurfaceCardList isSkeleton={isSkeleton} items={rows} />
    )

    return (
        <StackV
            gap={4}
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <StackH
                        gap={3}
                        principle="flex-action"
                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                        at="sm"
                        isSkeleton={isSkeleton}
                        items={[
                            () => (
                                <div className="min-w-0 flex-1">
                                    <InputSearch
                                        value={query}
                                        onValueChange={onQueryChange}
                                        placeholder="Search decks"
                                        ariaLabel="Search decks"

                                    />
                                </div>
                            ),
                            () => (
                                <div>
                                    <Tabs
                                        items={VIEW_ITEMS}
                                        selectedKey={view}
                                        onSelectionChange={(key) => onViewChange(key as FlashcardDeckListView)}
                                        ariaLabel="Display style"

                                    />
                                </div>
                            ),
                        ]}
                    />
                ),
                () => track,
                ...(!isSkeleton && decks.length > 0 ? [() => (
                    <div>
                        <Pagination currentPage={page} totalPages={totalPages} onPageChange={onPageChange} />
                    </div>
                )] : []),
            ]}
        />
    )
}

export { FlashcardDeckList }

import React from "react"
import { FlameIcon } from "@phosphor-icons/react"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { SurfaceCard } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { SegmentBar, type SegmentBarSegment } from "@sb-components/composites/stats/SegmentBar/SegmentBar"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `FlashcardMasteryStrip` — mastery-first progress readout for a deck ("how much
 * of this do I own", not "how many cards are left today"); maps to
 * `FlashcardStatsStrip`. Reuses `SegmentBar`'s own `caption` slot for the
 * retention/first-review line; loading feeds one flat uncoloured segment with
 * the legend hidden. Four leaves across two axes: the streak chip appearing, and
 * the caption switching between a retention number and a first-review nudge.
 */

/** Props for {@link FlashcardMasteryStrip}. */
export interface FlashcardMasteryStripProps {
    /** Cards the learner has fully mastered. */
    mastered: number
    /** Total cards in the deck. */
    total: number
    /** Cards still being learned (seen, not yet mastered). */
    learning: number
    /** Cards never reviewed. */
    newCount: number
    /** Current daily-study streak, in days. Omit → no streak chip (nothing to show yet). */
    streak?: number
    /** 30-day retention rate, 0–100. Only shown once {@link FlashcardMasteryStripProps.totalReviewed} clears the 5-review floor. */
    retention?: number
    /** Lifetime review count across the deck — the signal that decides which caption (if any) is honest to show. */
    totalReviewed: number
    /** `true` → the numbers shimmer and the bar goes inert while the deck's stats load. */
    isSkeleton?: boolean
}

/**
 * `SegmentBar` has no `isSkeleton`, so the loading state feeds it this one
 * inert, uncoloured segment (paired with `hideLegend`) instead of the real
 * mastered/learning/new split — see the file header's judgment call.
 */
const SKELETON_SEGMENTS: Array<SegmentBarSegment> = [
    { key: "loading", label: "", value: 1, color: "var(--default)" },
]

/**
 * Below the 5-review floor there is no honest retention number to show yet.
 * With zero reviews the caption becomes a nudge instead of a stat; between 1
 * and 4 it says nothing at all rather than print a number computed from too
 * little data.
 */
const masteryCaption = (totalReviewed: number, retention: number | undefined): string | undefined => {
    if (totalReviewed === 0) {
        return "Review your first card to start measuring retention."
    }
    if (totalReviewed >= 5 && retention != null) {
        return `${retention}% recall across ${totalReviewed} reviews.`
    }
    return undefined
}

/**
 * The deck's mastery readout. See the file header for the full contract.
 *
 * @param props - {@link FlashcardMasteryStripProps}
 */
const FlashcardMasteryStrip = ({
    mastered,
    total,
    learning,
    newCount,
    streak,
    retention,
    totalReviewed,
    isSkeleton = false,
}: FlashcardMasteryStripProps) => {
    const pct = total > 0 ? Math.round((mastered / total) * 100) : 0
    const hasStreak = streak != null

    const segments: Array<SegmentBarSegment> = [
        { key: "mastered", label: "Mastered", value: mastered, color: "var(--success)" },
        { key: "learning", label: "Learning", value: learning, color: "var(--warning)" },
        { key: "new", label: "New", value: newCount, color: "var(--muted)" },
    ]

    const ariaLabel = isSkeleton
        ? "Loading retention progress"
        : `Retention progress: ${mastered} mastered, ${learning} learning, ${newCount} new, out of ${total} cards`

    return (
        <div>
            <SurfaceCard
                label="Mastered"
                action={() =>
                    isSkeleton ? (
                        <Chip isSkeleton />
                    ) : hasStreak ? (
                        <Chip
                            tone="warning"
                            icon={FlameIcon}
                            text={`${streak}-day streak`}

                        />
                    ) : undefined
                }
                isSkeleton={isSkeleton}


                body={() => (
                    <StackV
                        gap={4}
                        isSkeleton={isSkeleton}
                        items={[
                            () => (
                                <StackH
                                    gap={2}
                                    principle="value-row"
                                    explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
                                    align="baseline"
                                    isSkeleton={isSkeleton}
                                    items={[
                                        () => (
                                            <Typography
                                                size="h3"
                                                weight="bold"
                                                isSkeleton={isSkeleton}
                                                text={`${mastered}/${total}`}

                                            />
                                        ),
                                        () => (
                                            <Typography
                                                size="sm"
                                                color="muted"
                                                isSkeleton={isSkeleton}
                                                text={`${pct}%`}

                                            />
                                        ),
                                    ]}
                                />
                            ),
                            () => (
                                <SegmentBar
                                    segments={isSkeleton ? SKELETON_SEGMENTS : segments}
                                    max={isSkeleton ? undefined : total}
                                    hideLegend={isSkeleton}
                                    ariaLabel={ariaLabel}
                                    caption={isSkeleton ? undefined : masteryCaption(totalReviewed, retention)}

                                />
                            ),
                        ]}
                    />
                )}
            />
        </div>
    )
}

export { FlashcardMasteryStrip }

import React from "react"
import { type SkeletonProps } from "@sb-components/frames/_slot"
import { LockIcon, CaretLeftIcon, CaretRightIcon } from "@phosphor-icons/react"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { ChipGroup, type ChipGroupItem } from "@sb-components/composites/chips/ChipGroup/ChipGroup"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { SurfaceCard } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { MarkdownContent } from "@sb-components/composites/viewers/MarkdownContent/MarkdownContent"
import { RatingBar, type RatingOption } from "@sb-components/starci/blocks/learn/RatingBar/RatingBar"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `FlashcardStudyCard` — one card of a review run, shared by both due-review and
 * deck-review. Composes `SurfaceCard`, `MarkdownContent`, `Chip`/`ChipGroup`,
 * `Button`, and the shared `RatingBar`; only the locked-premium notice is
 * hand-rolled. One chip per meta row (`starci-fe/no-adjacent-chip`): `levelLabel`
 * takes the lone chip, `tags` ride `ChipGroup`. Three leaves: `revealed` swaps
 * question-only for answer body, and within revealed `isLocked` swaps the answer
 * for a lock notice; `levelLabel`/`tags`/`explanation` stay states. Prev/next
 * never gate on grading.
 */

/** Props for {@link FlashcardStudyCard}. */
export interface FlashcardStudyCardProps {
    /** The question, as authored markdown. */
    question: string
    /** Seniority/difficulty this card targets, e.g. "Middle" — already localized. */
    levelLabel?: string
    /** Free-form tags on the card, e.g. topic labels. Rendered as a truncating row. */
    tags?: Array<string>
    /** `true` → the answer body (or the lock notice) is shown under the question. */
    revealed: boolean
    /** Fired when the learner asks to see the answer. */
    onReveal: () => void
    /** The answer, as authored markdown. Shown only once `revealed` and not `isLocked`. */
    answer?: string
    /** Optional reasoning under the answer, as authored markdown. */
    explanation?: string
    /**
     * `true` → this card's answer is premium content the learner has not bought.
     * Only meaningful once `revealed`: the question always shows, but revealing
     * swaps in a lock notice + unlock CTA instead of the real answer.
     */
    isLocked?: boolean
    /** Fired when the learner takes the way through the lock. Required when `isLocked` can be true. */
    onUnlock?: () => void
    /** Recall grades offered once the real answer is showing. */
    ratingOptions: Array<RatingOption>
    /** Fired with the grade the learner picked. */
    onRate: (grade: number) => void
    /** `true` → a grade is in flight; `RatingBar` owns the busy affordance. */
    isRatingPending?: boolean
    /** `true` → this is the first card of the run; the previous control is disabled. */
    isFirst: boolean
    /** `true` → this is the last card of the run; the next control is disabled. */
    isLast: boolean
    /** Fired to step back a card, regardless of whether this one was graded. */
    onPrev: () => void
    /** Fired to step forward a card, regardless of whether this one was graded. */
    onNext: () => void
    /** `true` → the card draws its own mirror instead of the real content. */
    isSkeleton?: boolean
}

/**
 * One review card. See the file header for the full contract, in particular why
 * this has exactly three leaves and why prev/next never gate on grading.
 *
 * @param props - {@link FlashcardStudyCardProps}
 */
const FlashcardStudyCard = ({
    question,
    levelLabel,
    tags,
    revealed,
    onReveal,
    answer,
    explanation,
    isLocked = false,
    onUnlock,
    ratingOptions,
    onRate,
    isRatingPending = false,
    isFirst,
    isLast,
    onPrev,
    onNext,
    isSkeleton = false,
}: FlashcardStudyCardProps) => {
    const hasMeta = levelLabel != null || (tags != null && tags.length > 0)
    const tagItems: Array<ChipGroupItem> = (tags ?? []).map((tag) => ({ key: tag, text: tag }))

    const metaRow = hasMeta ? (
        <StackH
            gap={3}
            principle="chip-row"
            explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
            at="sm"
            align="center"
            isSkeleton={isSkeleton}
            items={[
                ...(levelLabel != null ? [({ isSkeleton }: SkeletonProps) => <Chip isSkeleton={isSkeleton} tone="default" text={levelLabel} />] : []),
                ...(tagItems.length > 0
                    ? [
                        ({ isSkeleton }: SkeletonProps) => (
                            <ChipGroup
                                items={tagItems}
                                isSkeleton={isSkeleton}

                            />
                        ),
                    ]
                    : []),
            ]}
        />
    ) : null

    // The one hand-rolled part of this block (see file header): no existing
    // composite draws a lock message sized for ONE card face that still has a
    // question and nav controls around it — `EmptyState` fills a whole
    // pane, which is the wrong weight here.
    const lockNotice = (
        <StackV
            gap={3}
            principle="sibling-stack"
            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => (
                    <StackH
                        gap={3}
                        principle="identity"
                        explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                        align="center"
                        isSkeleton={isSkeleton}
                        items={[
                            () => <LockIcon aria-hidden focusable="false" weight="bold" className="size-5 shrink-0 text-muted" />,
                            ({ isSkeleton }: SkeletonProps) => (
                                <StackV
                                    gap={1}
                                    isSkeleton={isSkeleton}
                                    items={[
                                        ({ isSkeleton }: SkeletonProps) => <Typography size="sm" weight="medium" isSkeleton={isSkeleton} text="Answer locked" />,
                                        ({ isSkeleton }: SkeletonProps) => <Typography size="xs" color="muted" isSkeleton={isSkeleton} text="Upgrade to Premium to see this card's answer and explanation" />,
                                    ]}
                                />
                            ),
                        ]}
                    />
                ),
                ({ isSkeleton }: SkeletonProps) => <Button isSkeleton={isSkeleton} label="Unlock this card" variant="primary" onPress={onUnlock} />,
            ]}
        />
    )

    const answerBody = (
        <StackV
            gap={6}
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => (
                    <StackV
                        gap={3}
                        isSkeleton={isSkeleton}
                        items={[
                            ({ isSkeleton }: SkeletonProps) => <Typography size="xs" color="muted" isSkeleton={isSkeleton} text="Answer" />,
                            () => (
                                <MarkdownContent
                                    source={answer ?? ""}
                                    measure="compact"

                                />
                            ),
                        ]}
                    />
                ),
                ...(explanation != null
                    ? [
                        ({ isSkeleton }: SkeletonProps) => (
                            <StackV
                                gap={3}
                                isSkeleton={isSkeleton}
                                items={[
                                    ({ isSkeleton }: SkeletonProps) => <Typography size="xs" color="muted" isSkeleton={isSkeleton} text="Explanation" />,
                                    () => (
                                        <MarkdownContent
                                            source={explanation}
                                            measure="compact"

                                        />
                                    ),
                                ]}
                            />
                        ),
                    ]
                    : []),
                // The recall grade, not the run's right/wrong — same shared block
                // and same reasoning as `QuizRecapList`'s use of it.
                ({ isSkeleton }: SkeletonProps) => (
                    <RatingBar
                        options={ratingOptions}
                        onRate={onRate}
                        ariaLabel="Choose recall level"
                        isPending={isRatingPending}
                        isSkeleton={isSkeleton}

                    />
                ),
            ]}
        />
    )

    // Prev/next live beside reveal but never gate on it — see file header.
    const navRow = (
        <StackH
            gap={3}
            principle="flex-action"
            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
            justify="between"
            align="center"
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => (
                    <Button
                        isSkeleton={isSkeleton}
                        isIconOnly
                        prefixIcon={CaretLeftIcon}
                        ariaLabel="Previous card"
                        variant="tertiary"
                        isDisabled={isFirst}
                        onPress={onPrev}

                    />
                ),
                ...(!revealed ? [({ isSkeleton }: SkeletonProps) => <Button isSkeleton={isSkeleton} label="Show answer" variant="primary" onPress={onReveal} />] : []),
                ({ isSkeleton }: SkeletonProps) => (
                    <Button
                        isSkeleton={isSkeleton}
                        isIconOnly
                        prefixIcon={CaretRightIcon}
                        ariaLabel="Next card"
                        variant="tertiary"
                        isDisabled={isLast}
                        onPress={onNext}

                    />
                ),
            ]}
        />
    )

    return (
        <div>
            <SurfaceCard
                isSkeleton={isSkeleton}

                body={() => (
                    <StackV
                        gap={6}
                        isSkeleton={isSkeleton}
                        items={[
                            () => metaRow,
                            () => (
                                <MarkdownContent
                                    source={question}
                                    measure="compact"

                                />
                            ),
                            ...(revealed ? [() => (isLocked ? lockNotice : answerBody)] : []),
                            () => navRow,
                        ]}
                    />
                )}
            />
        </div>
    )
}

export { FlashcardStudyCard }

import React from "react"
import { Breadcrumbs } from "@sb-components/atoms/navigation/Breadcrumbs/Breadcrumbs"
import { PageHeader } from "@sb-components/composites/layout/Page/Page"

/**
 * `FoundationCategoryHeader` — the Foundations-hub identity cluster: a breadcrumb
 * trail above a title and description, nothing more. Sibling of `ContentHeader`
 * but thinner — a Foundations category carries no read state, reading time, or
 * outcomes, so it stops at the description. The breadcrumb slot is optional and
 * simply drops out when absent.
 */

/** One breadcrumb link — plain data, the block builds the atom from it. */
export interface FoundationCategoryHeaderCrumb {
    /** Stable React key. */
    key: string
    /** Display label. */
    label: string
    /** Has a handler → the crumb is pressable; the current page leaves it out. */
    onPress?: () => void
}

/** Props for {@link FoundationCategoryHeader}. */
export interface FoundationCategoryHeaderProps {
    /**
     * Breadcrumb trail as DATA — the block builds `Breadcrumbs` itself. Empty
     * or omitted (and not loading) → the whole breadcrumb slot is left out: a
     * root category reached directly has nothing above it to trail through.
     */
    breadcrumbItems?: Array<FoundationCategoryHeaderCrumb>
    /** Category title. */
    title: string
    /** One-sentence summary of the category. */
    description?: string
    /**
     * `true` → every composed atom switches to its own shimmer. The flag FLOWS
     * DOWN into the real atoms rather than building a parallel skeleton tree
     * (§12c), so the shimmer keeps the exact box of the thing it replaces.
     */
    isSkeleton?: boolean
}

/**
 * Foundations-hub identity cluster: trail, title, description. See the file
 * header for why this stops short of `ContentHeader`'s meta row and outcomes
 * card, and why it still earns its own layer above `PageHeader`.
 *
 * @param props - {@link FoundationCategoryHeaderProps}
 */
const FoundationCategoryHeader = ({
    breadcrumbItems,
    title,
    description,
    isSkeleton = false,
}: FoundationCategoryHeaderProps) => {
    return (
        <div>
            <PageHeader

                isSkeleton={isSkeleton}
                breadcrumb={() =>
                    isSkeleton || breadcrumbItems?.length ? (
                        <div className="w-fit">
                            <Breadcrumbs
                                collapseOnMobile
                                collapseFrom={4}
                                items={breadcrumbItems ?? []}
                                isSkeleton={isSkeleton}
                            />
                        </div>
                    ) : undefined
                }
                title={title}
                description={description}
            />
        </div>
    )
}

export { FoundationCategoryHeader }

import React from "react"
import { CaretRightIcon, MagnifyingGlassIcon } from "@phosphor-icons/react"
import { SurfaceCardList, type SurfaceCardListItem } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { EmptyState } from "@sb-components/composites/feedback/EmptyState/EmptyState"
import { Image } from "@sb-components/atoms/media/Image/Image"
import { Pagination } from "@sb-components/atoms/navigation/Pagination/Pagination"
import { StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `FoundationCategoryList` — the Foundations content library's browse-and-drill-in
 * list: joined rows with a thumbnail, title, one-line description and a trailing
 * caret, plus a pager once there is more than one page. Loading swaps row content
 * to shimmer; the `Empty` state replaces the rows with an `EmptyState` (worded by
 * whether a search query drove the empty result), both bounded inside the same
 * `SurfaceCardList` surface.
 */

/** One category row — plain data; the block resolves the thumbnail chain and builds the wording. */
export interface FoundationCategoryListItem {
    /** Stable id — also what `onSelectCategory` fires with. */
    id: string
    /** Category title. */
    title: string
    /** One-line summary, shown as the row's subtitle. */
    description?: string
    /** Underlying tech/brand mark — rides as the `Image` atom's `fallbackSrc` (see file header). */
    logoSrc?: string
    /** Dedicated category thumbnail — wins over `logoSrc` when present (see file header). */
    thumbnailUrl?: string
}

/** Page state for the list's own pager — omit entirely when the caller has only one page. */
export interface FoundationCategoryListPagination {
    /** 1-based current page. */
    currentPage: number
    /** Total page count. */
    totalPages: number
    /** Fired with the 1-based page the reader picked. */
    onPageChange: (pageNumber: number) => void
}

/** Props for {@link FoundationCategoryList}. */
export interface FoundationCategoryListProps {
    /** The current page's categories, in display order. */
    categories: Array<FoundationCategoryListItem>
    /**
     * Current search text driving which empty reason applies when `categories`
     * is empty (see file header, judgement 2). Not rendered as a field by this
     * block — the search input itself is `FoundationCategorySearchBar`'s job.
     */
    searchQuery?: string
    /** Fired with a category's id on ANY row press. */
    onSelectCategory: (id: string) => void
    /** Page nav state. Omit → no pager, even with a full page of rows. */
    pagination?: FoundationCategoryListPagination
    /**
     * `true` → the list draws its own row mirror. `categories` empty while
     * loading (§12c) → guesses 3 rows, this composite's siblings' SSOT convention.
     */
    isSkeleton?: boolean
}

/** The library-itself-is-empty title — no search was involved, so no "try another word" hint applies. Ported verbatim from `foundations.emptyCategories`. */
const LIBRARY_EMPTY_TITLE = "No Foundations topics yet."

/** Placeholder rows for the guessed skeleton count (§12c) — never carry a press handler or a thumbnail. */
const SKELETON_CATEGORIES: Array<FoundationCategoryListItem> = Array.from({ length: 3 }, (_unused, index) => ({
    id: `skeleton-${index}`,
    title: "",
}))

/**
 * Resolves the thumbnail-priority chain (see file header, judgement 1) into the
 * `Image` atom's own `src`/`fallbackSrc` pair — a naming decision, not a second
 * rendering path.
 */
const resolveThumbnail = (category: FoundationCategoryListItem): { src?: string; fallbackSrc?: string } =>
    category.logoSrc
        ? { src: category.logoSrc, fallbackSrc: category.thumbnailUrl }
        : { src: category.thumbnailUrl, fallbackSrc: undefined }

interface NoCategoriesEmptyStateProps {
    hasQuery: boolean
    searchQuery?: string
}
const NoCategoriesEmptyState = ({ hasQuery, searchQuery }: NoCategoriesEmptyStateProps) => (
    <EmptyState
        icon={hasQuery ? MagnifyingGlassIcon : undefined}
        title={hasQuery ? `No topics match "${searchQuery?.trim()}".` : LIBRARY_EMPTY_TITLE}
    />
)

/**
 * The Foundations library's browse-and-drill-in list. See the file header for
 * the thumbnail-priority chain, the two empty reasons, and why loading stays a
 * state of the same leaf rather than earning its own.
 *
 * @param props - {@link FoundationCategoryListProps}
 */
const FoundationCategoryList = ({
    categories,
    searchQuery,
    onSelectCategory,
    pagination,
    isSkeleton = false,
}: FoundationCategoryListProps) => {
    // Empty while loading (no real categories yet) → guess 3 rows, keeping the
    // right shape for when real data lands (§8). Once real `categories` exist,
    // keep the EXACT row count already there.
    const usingPlaceholders = isSkeleton && categories.length === 0
    const source = usingPlaceholders ? SKELETON_CATEGORIES : categories

    const rows: Array<SurfaceCardListItem> = source.map((category) => {
        const { src, fallbackSrc } = resolveThumbnail(category)
        return {
            key: category.id,
            leading: () => (
                <div className="size-10 shrink-0">
                    <Image
                        src={src}
                        fallbackSrc={fallbackSrc}
                        alt={category.title}
                        ratio="square"
                        radius="md"
                        isSkeleton={isSkeleton}

                    />
                </div>
            ),
            title: category.title,
            subtitle: category.description,
            // Every real row navigates — a constant of this domain, never conditional
            // (see file header, judgement 3).
            trailingIcon: CaretRightIcon,
            // Placeholder rows never become press targets — nothing underneath can act
            // yet, and a clickable shimmer row would be a false affordance.
            onPress: usingPlaceholders ? undefined : () => onSelectCategory(category.id),
        }
    })

    // Which of the two empty reasons applies (see file header, judgement 2) —
    // never during the skeleton branch, where "empty" just means "not loaded yet".
    const hasQuery = (searchQuery?.trim().length ?? 0) > 0
    const emptyState = !isSkeleton && categories.length === 0
        ? () => <NoCategoriesEmptyState hasQuery={hasQuery} searchQuery={searchQuery} />
        : undefined

    // Nothing to page through during the first fetch or an empty result (see
    // file header, judgement on the pager).
    const showPager = !isSkeleton && categories.length > 0 && pagination != null

    return (
        <StackV identity={{ tier: "block", component: "FoundationCategoryList" }}
            gap={4}
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <SurfaceCardList

                        isSkeleton={isSkeleton}
                        items={rows}
                        emptyState={emptyState}
                    />
                ),
                ...(showPager
                    ? [
                        () => (
                            <div>
                                <Pagination
                                    currentPage={pagination.currentPage}
                                    totalPages={pagination.totalPages}
                                    onPageChange={pagination.onPageChange}

                                />
                            </div>
                        ),
                    ]
                    : []),
            ]}
        />
    )
}

export { FoundationCategoryList }

import React from "react"
import { type SkeletonProps } from "@sb-components/frames/_slot"
import { SearchAutocomplete, type SearchAutocompleteItem } from "@sb-components/atoms/forms/SearchAutocomplete/SearchAutocomplete"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { StackH } from "@sb-components/frames/Stack/Stack"

/**
 * BLOCK — `FoundationCategorySearchBar`: the Foundations hub's search row —
 * a debounced autocomplete field plus a live "N topics" count riding beside
 * it, one `StackH` seam apart. See the component file header for why this
 * earns its own layer over the bare `SearchAutocomplete` atom (domain
 * mapping + count wording, §14d.1).
 *
 *  ONE LEAF (§14d.2). `isSkeleton`, an empty vs. populated suggestion list,
 * and every value `count` can take (unknown / zero / N) are all DATA — no
 * node appears or disappears across them — so they are STATES inside the
 * single `Default` leaf, not leaves of their own.
 */

/** One foundation-category autocomplete suggestion (from `foundationCategorySuggestions`). */
export interface FoundationCategorySuggestion {
    /** Category id — the payload `onSelectSuggestion` fires with. */
    id: string
    /** Clean display label (bare tech name, e.g. "Docker"). */
    label: string
}

/** Props for {@link FoundationCategorySearchBar}. */
export interface FoundationCategorySearchBarProps {
    /** Current text in the search field (controlled, debounced upstream by the screen). */
    query: string
    /** Fired with the new query on every keystroke. */
    onQueryChange: (query: string) => void
    /** Suggestions for the current query, best match first. */
    suggestions: Array<FoundationCategorySuggestion>
    /** Fired with the chosen suggestion's id. */
    onSelectSuggestion: (id: string) => void
    /** Matching category count. `undefined` while the count itself is not known yet. */
    count?: number
    /** Renders the field's + count's skeleton mirrors instead of the real controls. */
    isSkeleton?: boolean
}

/** Vietnamese count wording, ported verbatim from `foundations.categoryCount`. */
const countLabel = (count: number): string => (count === 0 ? "No topics yet" : `${count} topics`)

/**
 * The Foundations hub's search row. See the file header for why the count's
 * zero case renders (unlike a nav badge) and why this stays one leaf.
 *
 * @param props - {@link FoundationCategorySearchBarProps}
 */
const FoundationCategorySearchBar = ({
    query,
    onQueryChange,
    suggestions,
    onSelectSuggestion,
    count,
    isSkeleton = false,
}: FoundationCategorySearchBarProps) => {
    // domain entity → the atom's generic item shape (no `description` line: a
    // category suggestion carries only a bare name).
    const items: Array<SearchAutocompleteItem> = suggestions.map((suggestion) => ({
        id: suggestion.id,
        label: suggestion.label,
    }))

    return (
        <div>
            <StackH
                gap={4}
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                justify="between"
                isSkeleton={isSkeleton}
                items={[
                    () => (
                        <div className="min-w-0 flex-1">
                            <SearchAutocomplete
                                items={items}
                                inputValue={query}
                                onInputChange={onQueryChange}
                                onSelect={onSelectSuggestion}
                                placeholder="Search topics..."
                                isSkeleton={isSkeleton}

                            />
                        </div>
                    ),
                    ...(isSkeleton
                        ? [() => <Typography size="sm" color="muted" isSkeleton />]
                        : count !== undefined
                            ? [
                                ({ isSkeleton }: SkeletonProps) => (
                                    <Typography
                                        isSkeleton={isSkeleton}
                                        size="sm"
                                        color="muted"
                                        text={countLabel(count)}


                                    />
                                ),
                            ]
                            : []),
                ]}
            />
        </div>
    )
}

