import React from "react"
import { ArrowClockwiseIcon } from "@phosphor-icons/react"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { StackH } from "@sb-components/frames/Stack/Stack"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"

/**
 * `LeaderboardToolbar` — the strip above the ranking: "ranked by X" on the left, a
 * quiet last-updated fact beside it, a plain refresh button on the right. It sits
 * outside the board's async region, hence its own block. Hand-composed from atoms —
 * no composite draws this "label · muted timestamp · secondary button" shape. Owns
 * the "Ranked by …" template and the relative-time phrasing built from a plain
 * `updatedAt: Date`. Whether the timestamp has landed and whether a refresh is in
 * flight are states on the same three-slot row.
 */

/** Props for {@link LeaderboardToolbar}. */
export interface LeaderboardToolbarProps {
    /** What the ranking is sorted by, e.g. "this week's XP". The block builds the sentence around it. */
    categoryLabel: string
    /** When the board last refreshed. Omitted → nothing has loaded yet, so no timestamp is claimed. */
    updatedAt?: Date
    /** Fired when the reader asks for a fresh ranking. */
    onRefresh: () => void
    /** `true` → a refresh is in flight; the button carries its own busy skin and locks the press. */
    isRefreshing?: boolean
    /** Localized trigger word for the refresh button, e.g. "Refresh" (blocks carry no i18n). */
    refreshLabel: string
    /** Extra classes on the row, from the closed atom/frame union. */
    classNames?: Array<AllowedClassName>
}

/**
 * Vietnamese relative-time wording — this block's own vocabulary, built from a
 * plain `Date` so the caller never hands over a pre-formatted string.
 */
const formatUpdatedAt = (updatedAt: Date): string => {
    const diffMinutes = Math.floor((Date.now() - updatedAt.getTime()) / 60_000)
    if (diffMinutes < 1) return "Just updated"
    if (diffMinutes < 60) return `Updated ${diffMinutes} minutes ago`
    const diffHours = Math.floor(diffMinutes / 60)
    if (diffHours < 24) return `Updated ${diffHours} hours ago`
    const diffDays = Math.floor(diffHours / 24)
    return `Updated ${diffDays} days ago`
}

/**
 * The leaderboard's chrome strip. See the file header for why it is
 * hand-composed and why it stays one leaf.
 *
 * @param props - {@link LeaderboardToolbarProps}
 */
const LeaderboardToolbar = ({
    categoryLabel,
    updatedAt,
    onRefresh,
    isRefreshing = false,
    refreshLabel,
    classNames,
}: LeaderboardToolbarProps) => (
    <StackH
        gap={3}
        principle="flex-action"
        align="center"
        classNames={classNames}

        items={[
            () => (
                <Typography
                    size="sm"
                    weight="medium"
                    text={`Ranked by ${categoryLabel}`}

                />
            ),
            // no icon here — §5a.2: a clock needs an ASSOCIATION step to read as "time"
            // (not a universal symbol like check/locklock), and the text already carries the fact.
            ...(updatedAt != null ? [() => (
                <Typography
                    size="xs"
                    color="muted"
                    text={formatUpdatedAt(updatedAt)}

                />
            )] : []),
            // Pushes the refresh button to the row's trailing edge without a second
            // nested track — same spacer idiom `WorkSessionHeader` already uses.
            () => <span aria-hidden className="flex-1" />,
            () => (
                <Button
                    label={refreshLabel}
                    variant="secondary"
                    size="sm"
                    prefixIcon={ArrowClockwiseIcon}
                    isPending={isRefreshing}
                    onPress={onRefresh}
                />
            ),
        ]}
    />
)

export { LeaderboardToolbar }

import { FunnelSimpleIcon, MagnifyingGlassIcon } from "@phosphor-icons/react"
import { InputSearch } from "@sb-components/atoms/forms"
import { Popover } from "@sb-components/atoms/overlay/Popover/Popover"
import { ButtonRadioGroup } from "@sb-components/composites/buttons/ButtonRadioGroup/ButtonRadioGroup"
import { Badge } from "@sb-components/atoms/display/Badge/Badge"
import {
    AsyncContent,
    type AsyncContentEmptyProps,
} from "@sb-components/composites/async/AsyncContent/AsyncContent"
import { SurfaceCardList, type SurfaceCardListItem } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import type { VerdictBandVariant } from "@sb-components/composites/cards/verdict-band"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `MindMapRail` — the keyword lookup pane beside a mind-map canvas: search a term,
 * narrow by popularity tier, pick a result. Two shapes: `Default` (funnel popover
 * closed — loading/empty/populated are states of the single region below the header
 * row, swapped by `AsyncContent`) and `FilterOpen` (the popover panel open, so the
 * tier `ButtonRadioGroup` becomes a real node). The open panel renders through a
 * portal, outside the box `BlockAnatomy` scans.
 */

/** The popularity-tier filter this rail's result list is narrowed by. */
export type MindMapRailTier = "all" | "medium" | "high"

/** One keyword result — plain DATA; the block builds the row's tone and check. */
export interface MindMapRailItem {
    /** Stable id — the React key, and what `onPick` fires with. */
    id: string
    /** The keyword's display label. */
    label: string
    /** Relevance/popularity score in the map (0–100, higher = more central). Drives the row's tone via {@link popularityTone}. */
    popularity: number
    /** Where this keyword sits in the map's hierarchy, e.g. "Networking > TCP > Handshake". */
    breadcrumb: string
}

/** Props for {@link MindMapRail}. */
export interface MindMapRailProps {
    /** Current search text (controlled). */
    query: string
    /** Fired on every keystroke in the search field. */
    onQuery: (query: string) => void
    /** Current popularity-tier filter. */
    tier: MindMapRailTier
    /** Fired with the tier the reader picked in the funnel popover. */
    onTier: (tier: MindMapRailTier) => void
    /** The current query+tier's matching keywords, in display order. */
    items: Array<MindMapRailItem>
    /** Which result is currently focused on the canvas, if any. */
    selectedId?: string
    /** Fired with a result's id when its row is pressed. */
    onPick: (id: string) => void
    /** `true` → this rail's own query/tier fetch is in flight. */
    isLoading: boolean
    /** Accessible name for the search field. */
    ariaLabel: string
    /** Accessible name for the tier radio group inside the funnel popover. */
    tierAriaLabel: string
    /** `true` → the result list renders its own mirror (see file header's loading judgement call). */
    isSkeleton?: boolean
    /** Dev/spec only: pins the funnel popover open (see file header's judgement call). */
    defaultFilterOpen?: boolean
}

/** The block's own wording for the tier filter — never handed in by the caller (§14d.1). */
const TIER_LABEL: Record<MindMapRailTier, string> = {
    all: "All",
    medium: "Medium",
    high: "High",
}

const TIER_ORDER: Array<MindMapRailTier> = ["all", "medium", "high"]

/** Popularity score at/above which a row earns the "hub term" accent band. */
const POPULARITY_HIGH_THRESHOLD = 70
/** Popularity score at/above which a row earns the quieter "worth a look" band. */
const POPULARITY_MEDIUM_THRESHOLD = 35

/** Popularity → row tone — see file header's judgement call for why only two bands exist. */
const popularityTone = (popularity: number): VerdictBandVariant | undefined => {
    if (popularity >= POPULARITY_HIGH_THRESHOLD) return "accent"
    if (popularity >= POPULARITY_MEDIUM_THRESHOLD) return "warning"
    return undefined
}

const FILTER_TRIGGER_LABEL = "Filter"
const FILTER_HEADING = "Popularity"
const SEARCH_PLACEHOLDER = "Search keywords..."
const EMPTY_TITLE_NO_QUERY = "No keywords in this map yet"
const EMPTY_DESCRIPTION_WITH_QUERY = "Try a different keyword or loosen the filter."

/** How many placeholder rows mirror the list while `items` hasn't landed yet. */
const SKELETON_ROW_COUNT = 5

/** Placeholder rows for the loading mirror — no data, no press handler (§12c). */
const skeletonRows = (): Array<SurfaceCardListItem> =>
    Array.from({ length: SKELETON_ROW_COUNT }, (_unused, index) => ({
        key: `skeleton-${index}`,
        title: "",
        subtitle: "",
    }))

/** One real row: label + breadcrumb subtitle, popularity tone band, selection check. */
const resultRow = (item: MindMapRailItem, selectedId: string | undefined, onPick: (id: string) => void): SurfaceCardListItem => ({
    key: item.id,
    title: item.label,
    subtitle: item.breadcrumb,
    metaText: String(item.popularity),
    tone: popularityTone(item.popularity),
    selected: item.id === selectedId,
    onPress: () => onPick(item.id),
})

/**
 * The keyword lookup pane. See the file header for the full contract, the
 * two-leaf boundary, and the judgement calls (tone bands, `defaultFilterOpen`,
 * never-skeletonised header row).
 *
 * @param props - {@link MindMapRailProps}
 */
const MindMapRail = ({
    query,
    onQuery,
    tier,
    onTier,
    items,
    selectedId,
    onPick,
    isLoading,
    ariaLabel,
    tierAriaLabel,
    isSkeleton = false,
    defaultFilterOpen = false,
}: MindMapRailProps) => {
    const hasQuery = query.trim().length > 0
    const isFiltered = tier !== "all"

    const emptyContent: AsyncContentEmptyProps = hasQuery
        ? {
            icon: MagnifyingGlassIcon,
            title: `No keywords match "${query}"`,
            description: EMPTY_DESCRIPTION_WITH_QUERY,

        }
        : {
            title: EMPTY_TITLE_NO_QUERY,

        }

    const rows: Array<SurfaceCardListItem> = items.map((item) => resultRow(item, selectedId, onPick))

    const filterTrigger = (
        <Popover
            triggerLabel={FILTER_TRIGGER_LABEL}
            triggerIcon={FunnelSimpleIcon}
            heading={FILTER_HEADING}
            defaultOpen={defaultFilterOpen}

            content={
                <div>
                    <ButtonRadioGroup
                        ariaLabel={tierAriaLabel}
                        value={tier}
                        onChange={onTier}

                        items={TIER_ORDER.map((key) => ({ value: key, content: TIER_LABEL[key] }))}
                    />
                </div>
            }
        />
    )

    return (
        <StackV
            identity={{ tier: "block", component: "MindMapRail" }}
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <StackH
                        gap={3}
                        principle="flex-action"
                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                        at="sm"
                        isSkeleton={isSkeleton}
                        items={[
                            () => (
                                <div className="min-w-0 flex-1">
                                    <InputSearch
                                        value={query}
                                        onValueChange={onQuery}
                                        placeholder={SEARCH_PLACEHOLDER}
                                        ariaLabel={ariaLabel}

                                    />
                                </div>
                            ),
                            () => (
                                <div>
                                    {/* `Badge` only wraps the trigger when a non-default tier is active — `dot` has
                                        no built-in "hide me" reading the way `count` does (§ Badge file header: count
                                        ≤ 0 hides itself, a bare dot has no such signal), so the ON/OFF state is this
                                        block's own condition instead of a prop the atom could resolve alone. */}
                                    {isFiltered ? <Badge dot>{filterTrigger}</Badge> : filterTrigger}
                                </div>
                            ),
                        ]}
                    />
                ),
                () => (
                    <AsyncContent
                        isLoading={isLoading || isSkeleton}
                        skeleton={() => <SurfaceCardList items={skeletonRows()} isSkeleton />}
                        isEmpty={items.length === 0}
                        emptyContent={emptyContent}

                        content={() => <SurfaceCardList items={rows} />}
                    />
                ),
            ]}
        />
    )
}

export { MindMapRail }

import React from "react"
import { type SkeletonProps } from "@sb-components/frames/_slot"
import { Skeleton as HeroSkeleton } from "@heroui/react"
import { ArrowRightIcon, CheckCircleIcon, WarningCircleIcon, XCircleIcon } from "@phosphor-icons/react"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { SurfaceCard, SurfaceCardCrossList, type SurfaceCardCrossListItem } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { Callout, type CalloutIcon } from "@sb-components/composites/feedback/Callout/Callout"
import { MarkdownContent } from "@sb-components/composites/viewers/MarkdownContent/MarkdownContent"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"
import { ScoreRow } from "./ScoreRow"

/**
 * `MockInterviewScorecard` — read-only render of one graded mock-interview run:
 * a verdict banner (`Callout`), hand-laid `ProgressMeter` rows for the score and
 * attribute breakdowns, and strengths/gaps via `SurfaceCard.CrossList`. Every
 * optional section — byline, attribute breakdown, strengths, gaps, follow-up,
 * weak-area tag, retry — is a state of one shape. Per-question model-answer review
 * is out of scope (no primitive for it yet).
 */

/** Pass / borderline / fail — reuses the interview verdict vocabulary verbatim from the BE contract. */
export type MockInterviewVerdict = "pass" | "borderline" | "fail"

/** One row of the score breakdown — a phase (design mode) or a question ordinal (Q&A mode), already display-labeled by the caller. */
export interface MockInterviewScoreRow {
    /** Stable React key. */
    key: string
    /** Display label — a resolved phase name or a question ordinal ("Question 1"), already localized/resolved by the caller. */
    label: string
    /** Points earned for this phase/question. */
    score: number
    /** Points available for this phase/question. */
    max: number
}

/** One row of the attribute breakdown (communication, structured thinking …), 0–100. */
export interface MockInterviewAttributeScoreRow {
    /** Stable React key. */
    key: string
    /** Display label, already localized/resolved by the caller. */
    label: string
    /** 0–100. */
    score: number
}

/** Props for {@link MockInterviewScorecard}. */
export interface MockInterviewScorecardProps {
    /** Pass / borderline / fail — drives the verdict callout's tone, icon and wording. */
    verdict: MockInterviewVerdict
    /** Overall score, 0–100. */
    overallScore: number
    /** Per-phase or per-question score breakdown, in display order. Section self-hides when empty (and `isSkeleton` is off). */
    phaseOrQuestionScores: Array<MockInterviewScoreRow>
    /** Per-attribute score breakdown, in display order. Section self-hides when empty. */
    attributeScores: Array<MockInterviewAttributeScoreRow>
    /** Concrete things done right, as markdown. Section self-hides when empty. */
    strengths: Array<string>
    /** Concrete gaps framed as "what to add", as markdown. Section self-hides when empty. */
    gaps: Array<string>
    /** A follow-up an interviewer would ask next, as markdown. Omit → the section does not render. */
    followUpQuestion?: string | null
    /** The weakest area, already resolved by the caller (which phase/attribute counts as "weak enough to push" is a screen-level call, not this block's). Omit → the primary CTA reads generically. */
    weakAreaLabel?: string
    /** Fired when the learner takes the primary CTA — go study the weak area. */
    onStudyWeakArea: () => void
    /** Fired when the learner picks the capstone hand-off CTA. */
    onCapstone: () => void
    /** Fired when the learner wants to run the interview again. Omit → the retry action does not render (e.g. a read-only history detail). */
    onRetry?: () => void
    /** The system/prompt this run interviewed on, shown as a header line when known. */
    promptTitle?: string
    /** When this attempt was graded, already formatted/localized by the caller (e.g. "Jul 28, 2026 · 14:32"). Omit for a live, just-finished session. */
    createdAt?: string
    /** `true` → every part this block renders itself mirrors as shimmer. */
    isSkeleton?: boolean
}

/** Verdict → callout tone. */
const VERDICT_STATUS: Record<MockInterviewVerdict, "success" | "warning" | "danger"> = {
    pass: "success",
    borderline: "warning",
    fail: "danger",
}

/** Verdict → callout indicator icon. */
const VERDICT_ICON: Record<MockInterviewVerdict, CalloutIcon> = {
    pass: CheckCircleIcon,
    borderline: WarningCircleIcon,
    fail: XCircleIcon,
}

/** Verdict → the block's own wording (§14d.1 — a caller passes the enum, never a formatted string). */
const VERDICT_LABEL: Record<MockInterviewVerdict, string> = {
    pass: "Pass",
    borderline: "Borderline",
    fail: "Fail",
}

/** Placeholder row count while `isSkeleton` and the real breakdown length isn't known yet. */
const SKELETON_SCORE_ROWS = 3
const SKELETON_ATTRIBUTE_ROWS = 3

/**
 * The graded-run scorecard. See the file header for the full contract, the
 * scope cut (no per-question review this pass), and why every optional
 * section stays a STATE of this one leaf.
 *
 * @param props - {@link MockInterviewScorecardProps}
 */
const MockInterviewScorecard = ({
    verdict,
    overallScore,
    phaseOrQuestionScores,
    attributeScores,
    strengths,
    gaps,
    followUpQuestion,
    weakAreaLabel,
    onStudyWeakArea,
    onCapstone,
    onRetry,
    promptTitle,
    createdAt,
    isSkeleton = false,
}: MockInterviewScorecardProps) => {
    const hasByline = isSkeleton || promptTitle != null || createdAt != null
    const hasScoreRows = isSkeleton || phaseOrQuestionScores.length > 0
    const hasAttributeRows = isSkeleton || attributeScores.length > 0
    const hasStrengths = isSkeleton || strengths.length > 0
    const hasGaps = isSkeleton || gaps.length > 0
    const hasFollowUp = isSkeleton || Boolean(followUpQuestion)

    const strengthItems: Array<SurfaceCardCrossListItem> = strengths.map((strength, index) => ({
        key: `strength-${index}`,
        mark: "check",
        tone: "success",
        text: strength,
    }))

    const gapItems: Array<SurfaceCardCrossListItem> = gaps.map((gap, index) => ({
        key: `gap-${index}`,
        mark: "cross",
        tone: "danger",
        text: gap,
    }))

    const primaryCtaLabel = weakAreaLabel ? `Review: ${weakAreaLabel}` : "Review your weak areas"

    const bylineRow = hasByline ? (
        <StackH
            gap={4}
            justify="between"
            at="sm"
            principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            isSkeleton={isSkeleton}
            items={[
                () => (isSkeleton ? (
                    <Typography size="sm" weight="medium" isSkeleton />
                ) : promptTitle != null ? (
                    <Typography size="sm" weight="medium" text={promptTitle} />
                ) : null),
                () => (isSkeleton ? (
                    <Typography size="xs" color="muted" isSkeleton />
                ) : createdAt != null ? (
                    <Typography size="xs" color="muted" text={createdAt} />
                ) : null),
            ]}
        />
    ) : null

    const scoreBreakdownRows = (isSkeleton
        ? Array.from({ length: SKELETON_SCORE_ROWS }, (_, index) => ({
            key: `score-skeleton-${index}`,
            label: "",
            score: 0,
            max: 100,
        }))
        : phaseOrQuestionScores
    ).map((row) => () => (
        <ScoreRow
            key={row.key}
            label={row.label}
            score={row.score}
            max={row.max}
            isSkeleton={isSkeleton}
        />
    ))

    const attributeBreakdownRows = (isSkeleton
        ? Array.from({ length: SKELETON_ATTRIBUTE_ROWS }, (_, index) => ({
            key: `attribute-skeleton-${index}`,
            label: "",
            score: 0,
            max: 100,
        }))
        : attributeScores.map((row) => ({ ...row, max: 100 }))
    ).map((row) => () => (
        <ScoreRow
            key={row.key}
            label={row.label}
            score={row.score}
            max={row.max}
            isSkeleton={isSkeleton}
        />
    ))

    const weakAreaRow = weakAreaLabel != null && !isSkeleton ? (
        <StackH
            gap={2}
            align="center"
            principle="icon-text"
            explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => <Typography size="xs" color="muted" text="Weakest:" isSkeleton={isSkeleton} />,
                ({ isSkeleton }: SkeletonProps) => <Chip tone="warning" text={weakAreaLabel} isSkeleton={isSkeleton} />,
            ]}
        />
    ) : null

    const ctaButtonRow = (
        <StackH
            gap={4}
            at="sm"
            principle="flex-action"
            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <Button
                        isSkeleton={isSkeleton}
                        variant="primary"
                        size="lg"
                        label={primaryCtaLabel}
                        suffixIcon={ArrowRightIcon}
                        iconSlide
                        onPress={onStudyWeakArea}

                    />
                ),
                () => (
                    <Button
                        isSkeleton={isSkeleton}
                        variant="secondary"
                        size="lg"
                        label="Work on personal project"
                        onPress={onCapstone}

                    />
                ),
                ...(onRetry != null || isSkeleton ? [() => (
                    <Button
                        isSkeleton={isSkeleton}
                        variant="ghost"
                        size="lg"
                        label="Retry interview"
                        onPress={onRetry}

                    />
                )] : []),
            ]}
        />
    )

    return (
        <div>
            <StackV
                gap={6}
                isSkeleton={isSkeleton}
                items={[
                    () => bylineRow,
                    // Verdict banner. `Callout` has no `isSkeleton` of its own (a message
                    // frame, not a data-bearing one) — a bare bar stands in, in the same slot.
                    () => (
                        isSkeleton ? (
                            <HeroSkeleton className="h-20 w-full rounded-2xl" />
                        ) : (
                            <Callout
                                status={VERDICT_STATUS[verdict]}
                                icon={VERDICT_ICON[verdict]}
                                title={`${overallScore}/100 · ${VERDICT_LABEL[verdict]}`}

                            />
                        )
                    ),
                    ...(hasScoreRows ? [() => (
                        <SurfaceCard
                            label="Score by section"


                            body={() => (
                                <StackV gap={4} isSkeleton={isSkeleton} items={scoreBreakdownRows} />
                            )}
                        />
                    )] : []),
                    ...(hasAttributeRows ? [() => (
                        <SurfaceCard
                            label="Score by criterion"


                            body={() => (
                                <StackV gap={4} isSkeleton={isSkeleton} items={attributeBreakdownRows} />
                            )}
                        />
                    )] : []),
                    ...(hasStrengths ? [() => (
                        <StackV
                            gap={3}
                            isSkeleton={isSkeleton}
                            items={[
                                () => <Typography size="sm" weight="medium" text="Strengths" />,
                                () => <SurfaceCardCrossList items={strengthItems} isSkeleton={isSkeleton} />,
                            ]}
                        />
                    )] : []),
                    ...(hasGaps ? [() => (
                        <StackV
                            gap={3}
                            isSkeleton={isSkeleton}
                            items={[
                                () => <Typography size="sm" weight="medium" text="Areas to improve" />,
                                () => <SurfaceCardCrossList items={gapItems} isSkeleton={isSkeleton} />,
                            ]}
                        />
                    )] : []),
                    // no icon here — §5a.2: a chat-bubble needs an ASSOCIATION step to read as
                    // "a question" (not a universal symbol like check/locklock), and the card's own
                    // label="Follow-up question" already carries the fact.
                    ...(hasFollowUp ? [() => (
                        <SurfaceCard
                            label="Follow-up question"


                            body={() => (
                                <div className="italic [&_p]:m-0">
                                    <MarkdownContent
                                        source={followUpQuestion ?? ""}
                                        measure="compact"
                                        isSkeleton={isSkeleton}

                                    />
                                </div>
                            )}
                        />
                    )] : []),
                    () => (
                        <StackV
                            gap={3}
                            isSkeleton={isSkeleton}
                            items={[
                                ...(weakAreaRow != null ? [() => weakAreaRow] : []),
                                () => ctaButtonRow,
                            ]}
                        />
                    ),
                ]}
            />
        </div>
    )
}

export { MockInterviewScorecard }

import React from "react"
import { type SkeletonProps } from "@sb-components/frames/_slot"
import { FlowArrowIcon, PlayIcon } from "@phosphor-icons/react"
import { Avatar } from "@sb-components/atoms/display/Avatar/Avatar"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { InputText } from "@sb-components/atoms/forms"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { ButtonRadioGroup } from "@sb-components/composites/buttons/ButtonRadioGroup/ButtonRadioGroup"
import { SurfaceCard } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { Callout } from "@sb-components/composites/feedback/Callout/Callout"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `MockInterviewSetup` — the green-room card: who is interviewing, what to call
 * this run, how hard it should be, and the button(s) that start it. Sibling of
 * `QuizSetup` (same resumable-banner-leads-the-form shape). Two start buttons are
 * two different interviews — Q&A always exists; Design shows only when the caller
 * sets `isDesignAvailable`. The persona row is built from `Avatar` + `Typography`
 * (the second line is a role, not a handle). The "Customize" deep-config body is a
 * separate, deferred leaf.
 */

/** How hard the interviewer's questions run. The block owns the label (§14d.1). */
export type MockInterviewTier = "junior" | "mid" | "senior"

const TIER_LABEL: Record<MockInterviewTier, string> = {
    junior: "Junior",
    mid: "Mid-level",
    senior: "Senior",
}

/** Which start action is in flight, so the busy affordance lands on the right button. */
export type MockInterviewStartMode = "qna" | "design"

/** The interviewer greeting the candidate. */
export interface MockInterviewPersona {
    /** Interviewer's display name. */
    name: string
    /** Role line under the name, e.g. "Senior Backend @ a digital bank" — NOT a handle. */
    role: string
    /** Uploaded avatar URL. Absent → `Avatar`'s own generated/initials fallback. */
    avatarSrc?: string
}

/** A run the candidate left unfinished. */
export interface MockInterviewResumable {
    /** What the run was called when it was started. */
    name: string
    /** Where the run left off, already worded by the caller — e.g. "Left off at question 3". */
    progressLabel: string
    /** Fired when the candidate picks the run back up. */
    onResume: () => void
}

/** Props for {@link MockInterviewSetup}. */
export interface MockInterviewSetupProps {
    /** Section label, localized by the caller — e.g. "Prepare for the interview". */
    label: string
    /** The interviewer greeting the candidate. */
    persona: MockInterviewPersona
    /** Current run name. */
    sessionName: string
    /** Fired as the candidate types a name. */
    onSessionNameChange: (value: string) => void
    /** Chosen difficulty. */
    tier: MockInterviewTier
    /** Fired when the candidate picks a tier. */
    onTierChange: (tier: MockInterviewTier) => void
    /**
     * `true` → this is a System-Design course, so the Design-mode start button
     * renders beside the Q&A one. The CALLER decides this (course kind lives on
     * the screen); the block never infers it.
     */
    isDesignAvailable: boolean
    /** Fired when the candidate starts the Q&A round. Always available. */
    onStartQna: () => void
    /** Fired when the candidate starts the Design round. Required once `isDesignAvailable` is set. */
    onStartDesign?: () => void
    /** A run left unfinished. Present → the resume banner leads the card. */
    resumable?: MockInterviewResumable
    /** Which start action is currently in flight — drives which button shows its own spinner. */
    startingMode?: MockInterviewStartMode
    /** `true` → a start is in flight; both start buttons lock while one of them runs. */
    isPending?: boolean
    /** Set → the last start attempt failed. Reported beside the action row that failed. */
    errorMessage?: string
    /** `true` → the card draws its own mirror while the setup data loads. */
    isSkeleton?: boolean
}

/**
 * The interview green-room card. See the file header for the full contract.
 *
 * @param props - {@link MockInterviewSetupProps}
 */
const MockInterviewSetup = ({
    label,
    persona,
    sessionName,
    onSessionNameChange,
    tier,
    onTierChange,
    isDesignAvailable,
    onStartQna,
    onStartDesign,
    resumable,
    startingMode,
    isPending = false,
    errorMessage,
    isSkeleton = false,
}: MockInterviewSetupProps) => {
    const showDesignStart = isDesignAvailable && onStartDesign != null

    // A candidate who left mid-interview almost always means to come back.
    // Making them scroll past a start button to find their own session is
    // how a run gets abandoned twice — same reasoning as `QuizSetup`.
    const resumeBanner = resumable != null ? (
        <Callout
            title={resumable.name}
            description={resumable.progressLabel}
            actionLabel="Continue"
            onAction={resumable.onResume}

        />
    ) : null

    // Interviewer identity — built from Avatar + Typography directly (not
    // `UserCell`): the second line is a ROLE, not an `@handle`.
    const identityRow = (
        <StackH
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <div>
                        <Avatar
                            name={persona.name}
                            src={persona.avatarSrc}
                            seed={persona.name}
                            size="md"
                            isSkeleton={isSkeleton}

                        />
                    </div>
                ),
                ({ isSkeleton }: SkeletonProps) => (
                    <StackV
                        gap={1}
                        isSkeleton={isSkeleton}
                        items={[
                            () => (
                                <Typography
                                    size="sm"
                                    weight="medium"
                                    isSkeleton={isSkeleton}
                                    text={persona.name}

                                />
                            ),
                            () => (
                                <Typography
                                    size="xs"
                                    color="muted"
                                    isSkeleton={isSkeleton}
                                    text={persona.role}

                                />
                            ),
                        ]}
                    />
                ),
            ]}
        />
    )

    const sessionNameField = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => <Typography isSkeleton={isSkeleton} size="sm" weight="medium" text="Session name" />,
                () => (
                    <InputText
                        value={sessionName}
                        onValueChange={onSessionNameChange}
                        placeholder="e.g. Round 1 - Backend"
                        ariaLabel="Session name"
                        isSkeleton={isSkeleton}

                    />
                ),
            ]}
        />
    )

    const tierField = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => <Typography isSkeleton={isSkeleton} size="sm" weight="medium" text="Level" />,
                () => (
                    <ButtonRadioGroup
                        ariaLabel="Interview level"
                        value={tier}
                        onChange={onTierChange}

                        items={(Object.keys(TIER_LABEL) as Array<MockInterviewTier>).map((key) => ({
                            value: key,
                            content: TIER_LABEL[key],
                        }))}
                    />
                ),
            ]}
        />
    )

    const actionsRow = (
        <StackH
            gap={3}
            principle="flex-action"
            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
            justify="end"
            isSkeleton={isSkeleton}
            items={[
                ...(showDesignStart ? [({ isSkeleton }: SkeletonProps) => (
                    <Button
                        isSkeleton={isSkeleton}
                        label="Start Design"
                        variant="secondary"
                        prefixIcon={FlowArrowIcon}
                        onPress={onStartDesign}
                        isPending={isPending && startingMode === "design"}
                        isDisabled={isPending && startingMode !== "design"}

                    />
                )] : []),
                ({ isSkeleton }: SkeletonProps) => (
                    <Button
                        isSkeleton={isSkeleton}
                        label="Start Q&A"
                        variant="primary"
                        prefixIcon={PlayIcon}
                        onPress={onStartQna}
                        isPending={isPending && startingMode === "qna"}
                        isDisabled={isPending && startingMode !== "qna"}

                    />
                ),
            ]}
        />
    )

    // The error sits WITH the action row that failed. At the top of the
    // card it would read as a problem with the whole form.
    const footer = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                ...(errorMessage != null ? [() => (
                    <Callout
                        status="danger"
                        title={errorMessage}

                    />
                )] : []),
                () => actionsRow,
            ]}
        />
    )

    return (
        <div>
            <SurfaceCard
                label={label}
                isSkeleton={isSkeleton}

                body={({ isSkeleton }: SkeletonProps) => (
                    <StackV
                        gap={6}
                        isSkeleton={isSkeleton}
                        items={[
                            ...(resumeBanner != null ? [() => resumeBanner] : []),
                            () => identityRow,
                            () => sessionNameField,
                            () => tierField,
                            () => footer,
                        ]}
                    />
                )}
            />
        </div>
    )
}

export { MockInterviewSetup }

import React from "react"
import { ClockIcon, PuzzlePieceIcon, StackIcon } from "@phosphor-icons/react"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { Breadcrumbs } from "@sb-components/atoms/navigation/Breadcrumbs/Breadcrumbs"
import { EnumChip, type EnumChipEntry } from "@sb-components/composites/chips/EnumChip/EnumChip"
import { HighlightChip } from "@sb-components/composites/chips/HighlightChip/HighlightChip"
import { PageHeader } from "@sb-components/composites/layout/Page/Page"
import { StackH } from "@sb-components/frames/Stack/Stack"

/**
 * `ModuleHeader` — the module-identity cluster at the top of a module's page,
 * answering "what is this module, and how big is it". Sibling of `ContentHeader`
 * and `CourseBrief`: places identity into `PageHeader`, but carries a module's tier
 * plus three `HighlightChip` counts (lessons, minutes, challenges) — the counts are
 * the headline figures, so they keep their chip shape while `tier` classifies the
 * module. Which chips draw stays states of one shape; losing the whole meta row
 * drops a `PageHeader` region and earns its own shape.
 */

/** Learning tier of a module — mirrors the `src` `CourseContentTier` enum (GraphQL / DB, shared across every course). */
export enum CourseContentTier {
    /** Entry-level material — always free. */
    Foundation = "foundation",
    /** Mid-level material — the later half is premium. */
    Intermediate = "intermediate",
    /** Advanced material — always premium. */
    Advanced = "advanced",
}

/** Tier → chip presentation. The block owns this table (§14d.1: no caller-supplied color/label). */
const TIER_MAP: Record<CourseContentTier, EnumChipEntry> = {
    [CourseContentTier.Foundation]: { color: "success", label: "Foundation" },
    [CourseContentTier.Intermediate]: { color: "warning", label: "Intermediate" },
    [CourseContentTier.Advanced]: { color: "danger", label: "Advanced" },
}

/** One breadcrumb link — plain data, the block builds the atom from it. */
export interface ModuleHeaderCrumb {
    /** Stable React key. */
    key: string
    /** Display label. */
    label: string
    /** Has a handler → the crumb is pressable; the current page leaves it out. */
    onPress?: () => void
}

/** Props for {@link ModuleHeader}. */
export interface ModuleHeaderProps {
    /** Breadcrumb trail as DATA — the block builds `Breadcrumbs` itself. A module is always reached through its course, so the trail is always required (no "no breadcrumb" case, same call `ContentHeader` makes). */
    breadcrumbItems: Array<ModuleHeaderCrumb>
    /** Module title. */
    title: string
    /** One-sentence summary of the module. */
    description?: string
    /** Learning tier — the ONE classifying fact, drives the `EnumChip` tone + label. Omit → no tier chip. */
    tier?: CourseContentTier
    /** How many lessons this module has — the block adds "lessons" itself. Omit or `0` → no chip. */
    lessonCount?: number
    /** Total reading/study minutes across the module — the block adds "minutes of study" itself. Omit or `0` → no chip. */
    minutesTotal?: number
    /** How many challenges hang off this module — the block adds "challenges" itself. Omit or `0` → no chip. */
    challengeCount?: number
    /**
     * `true` → every composed atom switches to its own shimmer. The flag FLOWS
     * DOWN into the real atoms rather than building a parallel skeleton tree
     * (§12c).
     */
    isSkeleton?: boolean
}

/**
 * The module identity cluster at the top of a module's own page. See the file
 * header for the full contract and why this is a sibling of `ContentHeader`/
 * `CourseBrief` rather than an edit of either.
 *
 * @param props - {@link ModuleHeaderProps}
 */
const ModuleHeader = ({
    breadcrumbItems,
    title,
    description,
    tier,
    lessonCount,
    minutesTotal,
    challengeCount,
    isSkeleton = false,
}: ModuleHeaderProps) => {
    const hasLessons = (lessonCount ?? 0) > 0
    const hasMinutes = (minutesTotal ?? 0) > 0
    const hasChallenges = (challengeCount ?? 0) > 0
    // The meta row only exists once it has something to show — otherwise `PageHeader`
    // gets `undefined` and drops the whole slot instead of an empty row with nothing in it.
    const hasMeta = isSkeleton || tier != null || hasLessons || hasMinutes || hasChallenges

    const metaRow = hasMeta ? (
        <StackH
            gap={3}
            align="center"
            at="sm"
            principle="chip-row"
            explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
            isSkeleton={isSkeleton}

            items={[
                () => (isSkeleton ? (
                    <EnumChip
                        value={CourseContentTier.Foundation}
                        map={TIER_MAP}
                        isSkeleton

                    />
                ) : tier != null ? (
                    <EnumChip value={tier} map={TIER_MAP} />
                ) : null),
                () => (isSkeleton ? (
                    <span>
                        <Chip isSkeleton icon={StackIcon} />
                    </span>
                ) : hasLessons ? (
                    <span>
                        <HighlightChip
                            icon={StackIcon}
                            value={lessonCount}
                            label="lessons"
                        />
                    </span>
                ) : null),
                () => (isSkeleton ? (
                    <span>
                        <Chip isSkeleton icon={ClockIcon} />
                    </span>
                ) : hasMinutes ? (
                    <span>
                        <HighlightChip
                            icon={ClockIcon}
                            value={minutesTotal}
                            label="minutes"
                        />
                    </span>
                ) : null),
                () => (isSkeleton ? (
                    <span>
                        <Chip isSkeleton icon={PuzzlePieceIcon} />
                    </span>
                ) : hasChallenges ? (
                    <span>
                        <HighlightChip
                            icon={PuzzlePieceIcon}
                            value={challengeCount}
                            label="challenges"
                        />
                    </span>
                ) : null),
            ]}
        />
    ) : undefined

    return (
        <div>
            <PageHeader

                isSkeleton={isSkeleton}
                breadcrumb={() => (
                    <div className="w-fit">
                        <Breadcrumbs
                            collapseOnMobile
                            collapseFrom={4}
                            items={breadcrumbItems}
                            isSkeleton={isSkeleton}
                        />
                    </div>
                )}
                title={title}
                description={description}
                meta={() => metaRow}
            />
        </div>
    )
}

export { ModuleHeader }

import React from "react"
import { Skeleton as HeroSkeleton } from "@heroui/react"
import { CheckIcon, CircleIcon, LockIcon, PlayIcon } from "@phosphor-icons/react"
import { SurfaceCardList, type SurfaceCardListItem } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { VariantChipDifficulty, type Difficulty } from "@sb-components/starci/blocks/learn/VariantChip/VariantChip"

/**
 * `ModuleLessonList` — the full, ordered lesson table of contents for one module —
 * every lesson, not just what's next. Sibling of `KeepGoingPath` (which trims to
 * the continue-learning queue and owns a heading); this block takes no heading of
 * its own. The block owns the per-row status icon (`resume`/`read`/`unread`), the
 * "N min read · M challenges" subtitle, and whether a difficulty chip and premium
 * lock ride on the trailing side. Row-level differences are states of one
 * `SurfaceCardList` tree; `isSkeleton` is its own leaf.
 */

/** Where this lesson sits in the reader's progress through the module. */
type LessonStatus = "resume" | "read" | "unread"

/** One lesson row — plain data; the block assembles the wording and the icon. */
export interface ModuleLessonListLesson {
    /** Stable id — also what `onSelectLesson`/`resumeLessonId` key off. */
    id: string
    /** Lesson title. */
    title: string
    /** Reading time in minutes — the block folds this into the subtitle itself. */
    minutesRead: number
    /** Practice-challenge count for this lesson — folded into the same subtitle. */
    challengeCount: number
    /** Already finished at least once. */
    isRead: boolean
    /** Behind the paid tier — shows the trailing lock marker. */
    isPremium: boolean
    /** Difficulty tier — the block builds `VariantChipDifficulty` itself. Omit → no chip. */
    difficulty?: Difficulty
}

/** Props for {@link ModuleLessonList}. */
export interface ModuleLessonListProps {
    /** Every lesson in the module, in reading order. */
    lessons: Array<ModuleLessonListLesson>
    /** The lesson to mark "resume" — wins over `isRead` for the leading icon (see file header). */
    resumeLessonId?: string
    /** Fired with the lesson id on ANY row press, premium or not (see the  note above). */
    onSelectLesson: (id: string) => void
    /**
     * `true` → the list draws its own row mirror. `lessons` empty while loading
     * (§12c) → guesses 3 rows, the SSOT convention this composite's siblings
     * (`KeepGoingPath`, `LearnNudges`) already use.
     */
    isSkeleton?: boolean
}

/** Resolves the leading-icon state: `resumeLessonId` wins over `isRead` (see file header). */
const lessonStatus = (lesson: ModuleLessonListLesson, resumeLessonId?: string): LessonStatus => {
    if (resumeLessonId != null && lesson.id === resumeLessonId) {
        return "resume"
    }
    return lesson.isRead ? "read" : "unread"
}

/** The leading mark one lesson status resolves to: which glyph, and how it is coloured. */
interface LessonLeadingStyle {
    /** Phosphor glyph component for this status. */
    Icon: typeof CircleIcon
    /** Size + colour classes. */
    className: string
}

/** Leading glyph + colour per status — the block owns this table, the caller never picks an icon. */
const STATUS_LEADING: Record<LessonStatus, LessonLeadingStyle> = {
    resume: { Icon: PlayIcon, className: "size-5 text-accent-soft-foreground" },
    read: { Icon: CheckIcon, className: "size-5 text-success-soft-foreground" },
    unread: { Icon: CircleIcon, className: "size-5 text-foreground" },
}

/** Placeholder rows for the guessed skeleton count (§12c) — never carry a press handler. */
const SKELETON_LESSONS: Array<ModuleLessonListLesson> = Array.from({ length: 3 }, (_unused, index) => ({
    id: `skeleton-${index}`,
    title: "",
    minutesRead: 0,
    challengeCount: 0,
    isRead: false,
    isPremium: false,
    difficulty: "beginner",
}))

/**
 * The module's full lesson table of contents. See the file header for the full
 * contract and the two judgement calls that set it apart from `KeepGoingPath`.
 *
 * @param props - {@link ModuleLessonListProps}
 */
const ModuleLessonList = ({
    lessons,
    resumeLessonId,
    onSelectLesson,
    isSkeleton = false,
}: ModuleLessonListProps) => {
    // Empty while loading (no real lessons yet) → guess 3 rows, keeping the right
    // shape for when real data arrives (§8). Once real `lessons` exist, keep the
    // EXACT row count already there — the placeholder set never mixes with real rows.
    const usingPlaceholders = isSkeleton && lessons.length === 0
    const source = usingPlaceholders ? SKELETON_LESSONS : lessons

    const rows: Array<SurfaceCardListItem> = source.map((lesson) => {
        const { Icon, className } = STATUS_LEADING[lessonStatus(lesson, resumeLessonId)]
        return {
            key: lesson.id,
            leading: () => (isSkeleton ? (
                // The status icon is chosen DIRECTLY by the block from `STATUS_LEADING`,
                // never through an atom in between — hand-roll a single shimmer dot in
                // its place instead of branching off to build a whole separate row (§12c).
                <HeroSkeleton className="size-5 shrink-0 rounded-full" />
            ) : (
                <Icon aria-hidden focusable="false" className={className} />
            )),
            title: lesson.title,
            // The subtitle sentence is assembled HERE — the caller hands over two
            // numbers, never a pre-formatted string (§14d.1).
            subtitle: `${lesson.minutesRead} min read · ${lesson.challengeCount} challenges`,
            // Placeholder rows never become press targets — nothing underneath can act
            // yet, and a clickable shimmer row would be a false affordance.
            onPress: usingPlaceholders ? undefined : () => onSelectLesson(lesson.id),
            // Difficulty is DESIGN's shape (`VariantChipDifficulty`, §14d.1) — the block
            // doesn't reshape the chip, only decides whether one is offered at all.
            meta: lesson.difficulty != null ? () => (
                <VariantChipDifficulty
                    difficulty={lesson.difficulty!}
                    isSkeleton={isSkeleton}

                />
            ) : undefined,
            // A quiet trailing marker, riding NEXT TO the chip rather than replacing the
            // leading icon (see the * judgement call above).
            trailingIcon: lesson.isPremium ? LockIcon : undefined,
        }
    })

    return (
        <SurfaceCardList

            isSkeleton={isSkeleton}
            items={rows}
        />
    )
}

export { ModuleLessonList }

import React from "react"
import { GithubLogoIcon } from "@phosphor-icons/react"
import { PageHeader } from "@sb-components/composites/layout/Page/Page"
import { Breadcrumbs, type BreadcrumbItem } from "@sb-components/atoms/navigation/Breadcrumbs/Breadcrumbs"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { AsyncContent, type AsyncContentEmptyProps } from "@sb-components/composites/async/AsyncContent/AsyncContent"
import { ProgressMeter } from "@sb-components/composites/stats/ProgressMeter/ProgressMeter"
import { SurfaceCard } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { Grid } from "@sb-components/frames/Grid/Grid"
import { StackV } from "@sb-components/frames/Stack/Stack"
import { ContinueCardHero, ContinueCardItem } from "@sb-components/starci/blocks/learn/ContinueCard/ContinueCard"

/**
 * `PersonalProjectDashboard` — the capstone landing overview ("where am I + what's
 * next"), shown when the personal-project route carries no `taskId`: breadcrumb →
 * title/description/GitHub-status header, over a continue hero + completion meter,
 * over the current milestone's tasks as a two-column grid.
 *
 * Shapes:
 *   • `Full` — a next task exists, so the continue hero renders; GitHub connected
 *     vs not are states inside it.
 *   • `AllDone` — no `currentTask`, so the hero is gone, replaced by an "all done" line.
 *   • `Loading` — `AsyncContent` falls to the shimmer mirror.
 *   • `Empty` — `AsyncContent` falls to the empty message; the header is unaffected.
 */

/** One breadcrumb link above the dashboard title — plain data, the block builds the atom. */
export interface PersonalProjectDashboardCrumb {
    /** Stable React key. */
    key: string
    /** Display label. */
    label: string
    /** Has a handler → the crumb is pressable; the current page leaves it out. */
    onPress?: () => void
}

/** GitHub connection status fed into the header's status chip. */
export interface PersonalProjectGithubStatus {
    /** `true` → the chip renders in its connected (success) tone. */
    isConnected: boolean
    /**
     * Already-formatted display text — `"owner/repo · branch"` when connected, or
     * the "not connected" copy otherwise. Parsing the raw GitHub URL is the
     * caller's job (business logic, not presentation); the block only reacts to
     * `isConnected` for the chip's tone/icon.
     */
    label: string
}

/** The task currently in progress, fed into the continue hero. */
export interface PersonalProjectCurrentTask {
    /** 1-based position inside its milestone — the block prefixes it onto the title. */
    sortIndex: number
    /** Task title, WITHOUT the index prefix. */
    title: string
}

/** Where one keep-going task stands — the block owns the subtitle wording per state. */
export type PersonalProjectTaskSubtitleState = "active" | "done" | "locked" | "todo"

/** One task row in the keep-going grid — plain data, the block builds the tile. */
export interface PersonalProjectDashboardTask {
    /** Stable React key + the id handed back to `onSelectTask`. */
    id: string
    /** 1-based position inside the milestone — the block prefixes it onto the title. */
    sortIndex: number
    /** Task title, WITHOUT the index prefix. */
    title: string
    /** Which subtitle line this row shows — see {@link PersonalProjectTaskSubtitleState}. */
    subtitleState: PersonalProjectTaskSubtitleState
}

/** Aggregate KPIs across the whole capstone, shown under the completion meter. */
export interface PersonalProjectStats {
    /** Tasks completed so far. */
    done: number
    /** Tasks in the whole project. */
    total: number
    /** Total submit attempts across every task. */
    attempts: number
    /**
     * Already-formatted average score, e.g. `"18/20"` or `"—"` with no scored
     * attempts yet — computing the fraction is arithmetic the caller already
     * has to do to pick the "—" fallback, so it stays one string, same as
     * `ContentLanguage.label`.
     */
    avgLabel: string
}

/** Props for {@link PersonalProjectDashboard}. */
export interface PersonalProjectDashboardProps {
    /** Breadcrumb trail as DATA — the block builds `Breadcrumbs` itself. */
    breadcrumbItems?: Array<PersonalProjectDashboardCrumb>
    /** Dashboard title, e.g. "Personal Project". */
    title: string
    /** One-line description under the title. */
    description?: string
    /** GitHub connection status shown as a chip in the header's meta row. */
    githubStatus: PersonalProjectGithubStatus
    /** The next task to work on. Omit once every task is completed. */
    currentTask?: PersonalProjectCurrentTask
    /** Fired when the learner presses the continue hero's CTA. */
    onContinue: () => void
    /** The current milestone's name — the block prefixes "Continue ·" onto it. */
    milestoneLabel?: string
    /** The current milestone's tasks, in display order. */
    tasks: Array<PersonalProjectDashboardTask>
    /** Fired with a task's id when its tile is pressed. */
    onSelectTask: (taskId: string) => void
    /** Aggregate KPIs — see {@link PersonalProjectStats}. */
    stats: PersonalProjectStats
    /**
     * `true` while the milestone/progress fetch is running (no cache yet) — the
     * continue hero + progress stats + keep-going grid fall to their shimmer
     * mirror. The header (trail/title/description) is unaffected: it never
     * waits on this fetch.
     */
    isLoading?: boolean
    /**
     * `true` → the course has no milestones/tasks configured at all. Only takes
     * effect once `isLoading` is false.
     */
    isEmpty?: boolean
    /**
     * `true` → the header's own dynamic part (the GitHub chip) mirrors instead
     * of waiting on data — independent of `isLoading`, since that chip's data
     * comes off the enrollment record, not the milestone fetch.
     */
    isSkeleton?: boolean
}

/** Block-owned constant — the one classifying fact of the continue hero's subtitle. */
const NEXT_TASK_SUBTITLE = "Next task"

/** Block-owned constant — shown instead of the hero once every task is done. */
const ALL_DONE_TEXT = "You've completed every task in your personal project"

/** Block-owned constant — the completion meter's own label. */
const PROGRESS_LABEL = "Completion progress"

/** Block-owned constant — the keep-going grid's heading prefix. */
const KEEP_GOING_PREFIX = "Continue"

/** Block-owned wording per {@link PersonalProjectTaskSubtitleState} — the caller only sends the enum. */
const TASK_SUBTITLE: Record<PersonalProjectTaskSubtitleState, string> = {
    active: "Next task",
    done: "Completed",
    locked: "Locked",
    todo: "Not started",
}

/** Block-owned empty-state copy — the course has no capstone tasks configured yet. */
const EMPTY_STATE: AsyncContentEmptyProps = {
    title: "No tasks yet",
    description: "This course's personal project has no milestones/tasks set up yet.",
}

/** Placeholder shape guessed while loading (§12c) — mirrors `src`'s 4-row skeleton. */
const SKELETON_TASKS: Array<PersonalProjectDashboardTask> = Array.from({ length: 4 }, (_unused, index) => ({
    id: `skeleton-${index}`,
    sortIndex: index + 1,
    title: "",
    subtitleState: "todo",
}))

/** Assembles the milestone-name prefix the same way `KeepGoingPath` assembles its own heading. */
const keepGoingLabel = (milestoneLabel: string | undefined) =>
    milestoneLabel ? `${KEEP_GOING_PREFIX} · ${milestoneLabel}` : KEEP_GOING_PREFIX

/** Assembles the block-owned stats sentence under the completion meter. */
const statsLine = (stats: PersonalProjectStats) =>
    `${stats.done}/${stats.total} tasks completed · ${stats.attempts} submissions · average score ${stats.avgLabel}`

/** Props for the internal {@link Body} — the two async leaves, real or their shimmer guess. */
interface BodyProps {
    currentTask?: PersonalProjectCurrentTask
    onContinue: () => void
    milestoneLabel?: string
    tasks: Array<PersonalProjectDashboardTask>
    onSelectTask: (taskId: string) => void
    stats: PersonalProjectStats
    isSkeleton: boolean
}

/**
 * `ContinueHero+ProgressStats` and `KeepGoingGrid` — built ONCE and reused for
 * both the real content branch and the loading mirror (guessed data + forced
 * `isSkeleton`), so the two never drift into two hand-kept shapes.
 */
const Body = ({
    currentTask,
    onContinue,
    milestoneLabel,
    tasks,
    onSelectTask,
    stats,
    isSkeleton,
}: BodyProps) => {
    const heroSection = (
        <StackV
            gap={4}
            isSkeleton={isSkeleton}

            items={[
                () => (isSkeleton || currentTask ? (
                    <ContinueCardHero
                        title={currentTask ? `${currentTask.sortIndex}. ${currentTask.title}` : ""}
                        subtitle={NEXT_TASK_SUBTITLE}
                        isSkeleton={isSkeleton}
                        onPress={onContinue}


                    />
                ) : (
                    <Typography weight="semibold" text={ALL_DONE_TEXT} />
                )),
                () => (
                    <ProgressMeter
                        value={stats.done}
                        max={stats.total || 1}
                        label={PROGRESS_LABEL}
                        showValue
                        isSkeleton={isSkeleton}

                    />
                ),
                () => (
                    <Typography
                        size="xs"
                        color="muted"
                        isSkeleton={isSkeleton}

                        text={statsLine(stats)}

                    />
                ),
            ]}
        />
    )

    return (
        <StackV
            gap={6}
            principle="block-boundary"
            explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
            isSkeleton={isSkeleton}

            items={[
                () => heroSection,
                () => (
                    <SurfaceCard
                        label={keepGoingLabel(milestoneLabel)}
                        isSkeleton={isSkeleton}


                        body={() => (
                            <Grid
                                columns={{ base: 1, sm: 2 }}
                                principle="content-row"
                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."

                                items={tasks.map((task) => ({
                                    key: task.id,
                                    content: () => (
                                        <ContinueCardItem
                                            title={`${task.sortIndex}. ${task.title}`}
                                            subtitle={TASK_SUBTITLE[task.subtitleState]}
                                            isSkeleton={isSkeleton}
                                            onPress={() => onSelectTask(task.id)}


                                        />
                                    ),
                                }))}
                            />
                        )}
                    />
                ),
            ]}
        />
    )
}

/**
 * The capstone landing overview. See the file header for the full contract.
 *
 * @param props - {@link PersonalProjectDashboardProps}
 */
const PersonalProjectDashboard = ({
    breadcrumbItems,
    title,
    description,
    githubStatus,
    currentTask,
    onContinue,
    milestoneLabel,
    tasks,
    onSelectTask,
    stats,
    isLoading = false,
    isEmpty = false,
    isSkeleton = false,
}: PersonalProjectDashboardProps) => {
    const crumbs: Array<BreadcrumbItem> = (breadcrumbItems ?? []).map((crumb) => ({
        key: crumb.key,
        label: crumb.label,
        onPress: crumb.onPress,
    }))

    const header = (
        <PageHeader

            isSkeleton={isSkeleton}
            breadcrumb={() =>
                isSkeleton || crumbs.length ? (
                    <div className="w-fit">
                        <Breadcrumbs collapseOnMobile items={crumbs} isSkeleton={isSkeleton} />
                    </div>
                ) : undefined
            }
            title={title}
            description={description}
            meta={() =>
                isSkeleton ? (
                    <Chip isSkeleton />
                ) : (
                    <Chip
                        tone={githubStatus.isConnected ? "success" : "default"}
                        icon={GithubLogoIcon}
                        text={githubStatus.label}
                    />
                )
            }
        />
    )

    const asyncBody = (
        <AsyncContent
            isLoading={isLoading}
            skeleton={() => (
                <Body
                    currentTask={{ sortIndex: 1, title: "" }}
                    onContinue={onContinue}
                    milestoneLabel={milestoneLabel}
                    tasks={SKELETON_TASKS}
                    onSelectTask={onSelectTask}
                    stats={{ done: 0, total: 0, attempts: 0, avgLabel: "" }}
                    isSkeleton

                />
            )}
            isEmpty={isEmpty}
            emptyContent={EMPTY_STATE}
            content={() => (
                <Body
                    currentTask={currentTask}
                    onContinue={onContinue}
                    milestoneLabel={milestoneLabel}
                    tasks={tasks}
                    onSelectTask={onSelectTask}
                    stats={stats}
                    isSkeleton={false}

                />
            )}
        />
    )

    return (
        <div>
            <StackV
                gap={6}
                isSkeleton={isSkeleton}

                items={[
                    () => header,
                    () => asyncBody,
                ]}
            />
        </div>
    )
}

export { PersonalProjectDashboard }

import React from "react"
import { CircleIcon } from "@phosphor-icons/react"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"
import { ContinueCardHero } from "@sb-components/starci/blocks/learn/ContinueCard/ContinueCard"
import { ProgressMeter } from "@sb-components/composites/stats/ProgressMeter/ProgressMeter"
import { SurfaceCard } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { StackV, StackH } from "@sb-components/frames/Stack/Stack"

/**
 * `PersonalProjectGatePreview` — the capstone teaser dropped into `EnrollGate`'s
 * `preview` slot inside `LearnShell`: what a trial viewer sees of the
 * personal-project workspace, behind the gate's fade/lock. Composes
 * `ContinueCardHero` for the headline, a standalone `ProgressMeter` for capstone
 * completion, and `SurfaceCard` with a `label`. Non-interactive — the fade/lock
 * affordance belongs to `EnrollGate`. Task count and names are data on one shape.
 */

/** One milestone-0 task title shown in the teaser's task list. */
export interface PersonalProjectGatePreviewTask {
    /** Task title. */
    title: string
}

/**
 * Capstone overall completion fed to the standalone `ProgressMeter` (see file
 * header for why this stays a separate meter from `ContinueCardHero`'s own bar).
 */
export interface ProgressMeterData {
    /** Current progress value. Should fall within `[0, max]`. */
    value: number
    /** The 100% mark. Defaults to `100` (`ProgressMeter`'s own default). */
    max?: number
    /** Label rendered above the bar, e.g. "Personal project progress". */
    label?: string
}

/** Section label the block owns itself — see file header. */
const TASK_LABEL = "Milestone 0 Tasks"

/** Props for {@link PersonalProjectGatePreview}. */
export interface PersonalProjectGatePreviewProps {
    /** Capstone project name/headline — becomes `ContinueCardHero`'s title. */
    heroTitle: string
    /** One-line pitch under the headline — becomes `ContinueCardHero`'s subtitle. */
    heroSubtitle: string
    /** The capstone's overall completion, shown in its own `ProgressMeter`. */
    progress: ProgressMeterData
    /** Milestone-0 task titles, in display order. */
    items: Array<PersonalProjectGatePreviewTask>
    /**
     * `true` → every composed leaf draws its own shimmer mirror instead of the
     * real content. Flows straight into `ContinueCardHero`, `SurfaceCard`, and
     * each task row's `Typography` (§12c) — no parallel skeleton tree built here.
     */
    isSkeleton?: boolean
    /** Placement class only (§14d.1) — not for restyling. */
    classNames?: Array<AllowedClassName>
}

/**
 * The capstone teaser dropped behind `EnrollGate`'s fade. See the file header
 * for the full contract.
 *
 * @param props - {@link PersonalProjectGatePreviewProps}
 */
const PersonalProjectGatePreview = ({
    heroTitle,
    heroSubtitle,
    progress,
    items,
    isSkeleton = false,
    classNames,
}: PersonalProjectGatePreviewProps) => {
    // Depends on the loop variable, so it cannot be hoisted to a const above the
    // return — a small named helper instead, in the style this file already uses.
    const renderTaskRow = (item: PersonalProjectGatePreviewTask, index: number) => (
        <StackH
            key={index}
            gap={2}
            principle="icon-text"
            explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
            align="center"
            isSkeleton={isSkeleton}

            items={[
                () => <CircleIcon aria-hidden focusable="false" className="size-4 shrink-0 text-muted" />,
                () => (
                    <Typography
                        size="sm"
                        truncate
                        isSkeleton={isSkeleton}
                        text={item.title}

                    />
                ),
            ]}
        />
    )

    const taskList = (
        <StackV
            gap={4}
            isSkeleton={isSkeleton}

            items={items.map((item, index) => () => renderTaskRow(item, index))}
        />
    )

    return (
        <StackV identity={{ tier: "block", component: "PersonalProjectGatePreview" }}
            gap={6}
            classNames={classNames}
            isSkeleton={isSkeleton}

            items={[
                () => (
                    <ContinueCardHero
                        title={heroTitle}
                        subtitle={heroSubtitle}
                        isSkeleton={isSkeleton}


                    />
                ),
                () => (
                    <ProgressMeter
                        value={progress.value}
                        max={progress.max}
                        label={progress.label}
                        showValue


                    />
                ),
                () => (
                    <SurfaceCard
                        label={TASK_LABEL}
                        isSkeleton={isSkeleton}


                        body={() => taskList}
                    />
                ),
            ]}
        />
    )
}

export { PersonalProjectGatePreview }

import React from "react"
import { Skeleton as HeroSkeleton } from "@heroui/react"
import { ArrowClockwiseIcon, CaretDownIcon, CaretUpIcon } from "@phosphor-icons/react"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { Chip, type ChipTone } from "@sb-components/atoms/chips/Chip/Chip"
import { Typography, type TypographyColor } from "@sb-components/atoms/text/Typography/Typography"
import { StatRibbon, type StatRibbonItem } from "@sb-components/composites/stats/StatRibbon/StatRibbon"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * BLOCK — `PlaygroundConnectSheet`: the docked connection console under the lab
 * canvas — a peek row (status + reconnect) that never leaves the screen, and a
 * body the learner opens to see device specs and the live agent log.
 *
 * ONE LEAF, THREE DATA STATES (see the component's file header for the full
 * reasoning): `connected` shows the real device panel, `waiting` and `dropped`
 * share the same not-connected hint body and differ only in the peek chip's
 * wording/tone — `dropped` cannot happen without a prior connection, so no
 * extra `everConnected` prop is needed to tell the two apart.
 */

/** How the lab's device pairing currently stands. */
export type PlaygroundConnectionState = "connected" | "waiting" | "dropped"

/** One line the local agent printed, already leveled by the caller. */
export type PlaygroundAgentLogLevel = "info" | "success" | "warn" | "error"

/** The learner's machine, as reported by the connected agent. */
export interface PlaygroundDeviceSpec {
    /** e.g. `"Windows"`, `"macOS"`, `"Linux"`. */
    platform: string
    /** e.g. `"x64"`, `"arm64"`. */
    arch: string
    hostname: string
    cpuCores: number
    cpuModel: string
    totalMemBytes: number
    freeMemBytes: number
    /** Omitted → the machine has no discrete GPU the agent could report. */
    gpu?: string
    vramTotalMb?: number
    vramFreeMb?: number
}

/** One printed line from the local agent's live log. */
export interface PlaygroundAgentLogLine {
    level: PlaygroundAgentLogLevel
    line: string
}

interface PlaygroundConnectSheetOwnProps {
    /** Round-trip time to the local agent. Only shown while `connection === "connected"`. */
    latencyMs?: number
    /**
     * The paired machine's specs. Present only once the agent has reported at
     * least once — its presence is how `"dropped"` differs from `"waiting"` in
     * spirit, even though both render the same hint body (see file header).
     */
    device?: PlaygroundDeviceSpec
    /** Fired when the learner presses the peek row's reconnect action. */
    onReconnect: () => void
    /** Whether the body (device specs + log, or the hint) is expanded. Controlled. */
    open: boolean
    /** Fired with the next expanded state when the learner presses the toggle. */
    onOpenChange: (open: boolean) => void
}

/**
 * Props for {@link PlaygroundConnectSheet}. `connection`/`agentLog` are
 * REQUIRED unless `isSkeleton` (§12b) — the pairing state itself hasn't
 * resolved yet on first mount.
 */
export type PlaygroundConnectSheetProps = PlaygroundConnectSheetOwnProps &
    (
        | { isSkeleton: true; connection?: PlaygroundConnectionState; agentLog?: Array<PlaygroundAgentLogLine> }
        | {
            isSkeleton?: false
            /** Current pairing state — drives the peek chip's tone and wording. */
            connection: PlaygroundConnectionState
            /** Live tail of the local agent's log, oldest first. Shown only while connected. */
            agentLog: Array<PlaygroundAgentLogLine>
        }
    )

const STATUS_TONE: Record<PlaygroundConnectionState, ChipTone> = {
    connected: "success",
    waiting: "warning",
    dropped: "danger",
}

const STATUS_DOT_CLASS: Record<PlaygroundConnectionState, string> = {
    connected: "text-success",
    waiting: "text-warning",
    dropped: "text-danger",
}

/** The block owns this vocabulary — the caller only ever hands over the enum. */
const STATUS_LABEL: Record<PlaygroundConnectionState, string> = {
    connected: "Connected",
    waiting: "Waiting to connect",
    dropped: "Disconnected",
}

const LOG_COLOR: Record<PlaygroundAgentLogLevel, TypographyColor> = {
    info: "muted",
    success: "success",
    warn: "warning",
    error: "danger",
}

/** Same hint for both not-connected states — see file header on `waiting` vs `dropped`. */
const NOT_CONNECTED_HINT =
    "Turn on the agent on your machine, then press Reconnect. Your device specs and log will show up here as soon as the connection is back."

/** `1 234 567 890` → `"1.1 GB"` / `"48 MB"` — the block owns this wording, not a shared util (one call site). */
const formatBytes = (bytes: number): string => {
    const GIB = 1024 ** 3
    if (bytes >= GIB) return `${(bytes / GIB).toFixed(1)} GB`
    return `${Math.round(bytes / 1024 ** 2)} MB`
}

/** Device spec → the 3–4 {@link StatRibbon} cells, GPU cell only when the machine reports one. */
const buildDeviceItems = (device: PlaygroundDeviceSpec): Array<StatRibbonItem> => {
    const items: Array<StatRibbonItem> = [
        { key: "host", value: device.hostname, label: `${device.platform} · ${device.arch}` },
        { key: "cpu", value: `${device.cpuCores} cores`, label: device.cpuModel },
        {
            key: "ram",
            value: `${formatBytes(device.freeMemBytes)} / ${formatBytes(device.totalMemBytes)}`,
            label: "RAM free / total",
        },
    ]
    if (device.gpu != null) {
        items.push({
            key: "gpu",
            value: device.gpu,
            label:
                device.vramTotalMb != null
                    ? `VRAM ${device.vramFreeMb != null ? `${device.vramFreeMb} / ` : ""}${device.vramTotalMb} MB`
                    : "GPU",
        })
    }
    return items
}

/**
 * The docked connection console. See the file header for the reuse check and
 * the judgement calls (no new composite file, scope-disciplined toggle instead
 * of drag-resize, shared not-connected hint).
 *
 * @param props - {@link PlaygroundConnectSheetProps}
 */
const PlaygroundConnectSheet = ({
    connection,
    latencyMs,
    device,
    agentLog,
    onReconnect,
    open,
    onOpenChange,
    isSkeleton = false,
}: PlaygroundConnectSheetProps) => {
    if (isSkeleton) {
        return (
            <div className="overflow-hidden rounded-t-3xl border border-default bg-surface shadow-surface">
                <StackV
                    gap={1}
                    principle="cell-pad"
                    explain="Tight cell inset — not card-padding, because this sits inside a dense table or list cell rather than a card body."
                    padding={4}
                    isSkeleton={isSkeleton}
                    items={[() => (
                        <StackH
                            gap={4}
                            principle="content-row"
                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                            align="center"
                            justify="between"
                            isSkeleton={isSkeleton}
                            items={[
                                () => <HeroSkeleton className="h-5 w-24 rounded-full" />,
                                () => <HeroSkeleton className="h-8 w-24 rounded-xl" />,
                            ]}
                        />
                    )]}
                />
            </div>
        )
    }
    // `connection` is REQUIRED whenever `isSkeleton` is false (the discriminated union
    // above, already guaranteed by the early return) — the fallback only satisfies
    // narrowing across the destructure, it never actually fires.
    const safeConnection = connection ?? "waiting"
    const isConnected = safeConnection === "connected"
    const showDeviceBody = isConnected && device != null

    const statusGroup = (
        <StackH
            gap={3}
            principle="sibling-stack"
            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
            align="center"
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <Chip
                        tone={STATUS_TONE[safeConnection]}
                        dotClassName={STATUS_DOT_CLASS[safeConnection]}
                        text={STATUS_LABEL[safeConnection]}
                        isSkeleton={isSkeleton}
                    />
                ),
                ...(isConnected && latencyMs != null ? [() => (
                    <Typography
                        size="sm"
                        color="muted"
                        tabularNums
                        isSkeleton={isSkeleton}
                        text={`${latencyMs} ms`}

                    />
                )] : []),
            ]}
        />
    )

    const actionsGroup = (
        <StackH
            gap={3}
            principle="flex-action"
            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
            align="center"
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <Button
                        label="Reconnect"
                        variant="secondary"
                        size="sm"
                        prefixIcon={ArrowClockwiseIcon}
                        onPress={onReconnect}
                        isSkeleton={isSkeleton}
                    />
                ),
                () => (
                    <Button
                        isIconOnly
                        size="sm"
                        variant="ghost"
                        prefixIcon={open ? CaretUpIcon : CaretDownIcon}
                        ariaLabel={open ? "Collapse connection panel" : "Expand connection panel"}
                        onPress={() => onOpenChange(!open)}
                        isSkeleton={isSkeleton}
                    />
                ),
            ]}
        />
    )

    // Depends on the loop variable, so it cannot be hoisted to a const above the
    // return — a small named helper instead, in the style this file already uses.
    const renderLogLine = (entry: PlaygroundAgentLogLine) => (
        <Typography
            size="xs"
            color={LOG_COLOR[entry.level]}
            tabularNums={false}
            text={entry.line}

        />
    )

    const sheetBody = showDeviceBody ? (
        <>
            <div>
                <StatRibbon items={buildDeviceItems(device)} valueType="body" bordered />
            </div>
            <StackV gap={2} isSkeleton={isSkeleton} items={(agentLog ?? []).map((entry) => () => renderLogLine(entry))} />
        </>
    ) : (
        <Typography size="sm" color="muted" text={NOT_CONNECTED_HINT} />
    )

    return (
        <div className="overflow-hidden rounded-t-3xl border border-default bg-surface shadow-surface">
            {/* PEEK — always visible: status + reconnect, plus the toggle that opens the body. */}
            <StackV
                gap={1}
                principle="cell-pad"
                explain="Tight cell inset — not card-padding, because this sits inside a dense table or list cell rather than a card body."
                padding={4}
                isSkeleton={isSkeleton}
                items={[() => (
                    <StackH
                        gap={4}
                        principle="content-row"
                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                        align="center"
                        justify="between"
                        isSkeleton={isSkeleton}
                        items={[
                            () => statusGroup,
                            () => actionsGroup,
                        ]}
                    />
                )]}
            />
            {/* BODY — mounted only while open, matching a real bottom-sheet's collapsed state. */}
            {open ? (
                <div className="border-t border-default">
                    <StackV
                        gap={1}
                        principle="cell-pad"
                        explain="Tight cell inset — not card-padding, because this sits inside a dense table or list cell rather than a card body."
                        padding={4}
                        isSkeleton={isSkeleton}
                        items={[() => (
                            <StackV gap={4} principle="card-caption"
                                explain="Holds caption text under card media so the caption stays attached to the image above it."
                                isSkeleton={isSkeleton} items={[() => sheetBody]}  />
                        )]}
                    />
                </div>
            ) : null}
        </div>
    )
}

