import React, { useState } from "react"
import { type SkeletonProps } from "@sb-components/frames/_slot"
import type { ReactNode } from "react"
import { Tabs } from "@heroui/react"
import {
    ArrowClockwiseIcon,
    ArrowsClockwiseIcon,
} from "@phosphor-icons/react"
import { SurfaceCard } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { EnumChip, type EnumChipEntry } from "@sb-components/composites/chips/EnumChip/EnumChip"
import { MarkdownContent } from "@sb-components/composites/viewers/MarkdownContent/MarkdownContent"
import { TabsExtended } from "@sb-components/atoms/navigation/Tabs/Tabs"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { Callout } from "@sb-components/composites/feedback/Callout/Callout"
import { ConfirmDialog } from "@sb-components/composites/feedback/ConfirmDialog/ConfirmDialog"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { StackV, StackH } from "@sb-components/frames/Stack/Stack"
import { CommandSkeleton } from "./CommandSkeleton"
import { OsTabsSkeleton } from "./OsTabsSkeleton"
import { type PlaygroundSetupOs, type PlaygroundSetupStepsProps } from "./types"

export type { PlaygroundSetupOs, PlaygroundSetupFlavor, PlaygroundSetupStepsProps } from "./types"

/**
 * BLOCK — `PlaygroundSetupSteps`: the ordered setup guide for a playground — pair
 * the local agent, install the engine (an OS-tabbed guide), and — Ollama flavor
 * only — pull the VRAM-sized models. Each step carries its own status chip,
 * why-it-matters line, runnable command(s), and re-check action.
 *
 * TWO LEAVES, ONE PER `flavor` (§14d.2 — see the component's file header for why
 * this differs from `ChallengeBrief`'s single "one leaf, N optional sections"):
 * `flavor` is chosen once per PLAYGROUND KIND, not per render, so a caller wired
 * to `"infra"` never even carries the model-readiness props the third step
 * needs — the third `SurfaceCard` is a structural fact of the ollama leaf, not a
 * data condition that could show up on the infra one.
 */

/** One `SurfaceCard` step, built by this block before render — named per §"every data shape has a name". */
interface StepEntry {
    key: string
    title: string
    status: StepStatus
    body: ReactNode
}

/** Fixed platform-wide embedding model — see file header: unlike the generation model, this never varies by device. */
const EMBEDDING_MODEL_NAME = "bge-m3"

const OS_ORDER: ReadonlyArray<PlaygroundSetupOs> = ["mac", "win", "linux"]
const OS_LABEL: Record<PlaygroundSetupOs, string> = { mac: "macOS", win: "Windows", linux: "Linux" }

/** The two-value readiness enum driving every step's trailing chip. */
type StepStatus = "ready" | "pending"

/** status → chip label/color — fixed Vietnamese copy this block owns (§14d.1), matching `PlaygroundReadinessChecklist`'s table. */
const STEP_STATUS_MAP: Record<StepStatus, EnumChipEntry> = {
    ready: { label: "Ready", color: "success" },
    pending: { label: "Not done", color: "default" },
}

/** Wraps a shell command in a fenced ```bash block for `MarkdownContent`. */
const bashBlock = (command: string): string => "```bash\n" + command + "\n```"

/**
 * The playground setup guide. See the file header for the reuse check, the
 * two-leaves-per-flavor call, and the skeleton-mirror judgement calls.
 *
 * @param props - {@link PlaygroundSetupStepsProps}
 */
const PlaygroundSetupSteps = ({
    flavor,
    engineName,
    osGuides,
    pairCommand,
    pairingCodeSecondsLeft = null,
    pairingCodeExpired = false,
    onRefreshPairingCode,
    isRefreshingPairingCode = false,
    agentReady,
    engineReady,
    genModelReady = false,
    embedModelReady = false,
    recommendedGenModel,
    deviceKnown = true,
    engineDetail,
    onVerify,
    isSkeleton = false,
}: PlaygroundSetupStepsProps) => {
    const [os, setOs] = useState<PlaygroundSetupOs>("mac")
    const [isRotateConfirmOpen, setRotateConfirmOpen] = useState(false)

    // Rotating a code nobody's agent holds yet is free; rotating a code the connected
    // agent depends on is disruptive, so THAT path confirms first (see file header).
    const onRotateClick = () => {
        if (!onRefreshPairingCode) return
        if (agentReady) {
            setRotateConfirmOpen(true)
        } else {
            onRefreshPairingCode()
        }
    }
    const onConfirmRotate = () => {
        onRefreshPairingCode?.()
        setRotateConfirmOpen(false)
    }

    // Shared by every step (see PROPS doc on `onVerify`) — built once as functions, not a
    // single JSX element re-used across positions, so each step gets its own element instance.
    const renderVerifyButton = (): ReactNode => {
        if (isSkeleton) return <Button isSkeleton size="sm" />
        if (!onVerify) return null
        return (
            <Button
                label="Check again"
                variant="tertiary"
                size="sm"
                prefixIcon={ArrowClockwiseIcon}
                onPress={onVerify}

            />
        )
    }
    const renderRotateButton = (): ReactNode => {
        if (isSkeleton) return <Button isSkeleton size="sm" />
        if (!onRefreshPairingCode) return null
        return (
            <Button
                label="Get new code"
                variant="tertiary"
                size="sm"
                prefixIcon={ArrowsClockwiseIcon}
                onPress={onRotateClick}
                isPending={isRefreshingPairingCode}

            />
        )
    }

    const pairingCodeNote: ReactNode = pairingCodeExpired
        ? (
            <Typography
                size="xs"
                color="danger"
                text="The pairing code has expired — get a new code to continue."

            />
        )
        : pairingCodeSecondsLeft != null
            ? (
                <Typography
                    size="xs"
                    color="muted"
                    text={`Code valid for ${pairingCodeSecondsLeft} more seconds`}

                />
            )
            : null

    const pairStepBody: ReactNode = (
        <StackV
            gap={3}
            principle="sibling-stack"
            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <Typography
                        size="sm"
                        color="muted"
                        isSkeleton={isSkeleton}
                        text="The local agent is the bridge that lets Playground control your machine — skip this step and every command in the following steps fails to run."

                    />
                ),
                () => (isSkeleton
                    ? <CommandSkeleton />
                    : <MarkdownContent source={bashBlock(pairCommand)} measure="compact" />),
                ...(!isSkeleton ? [() => pairingCodeNote] : []),
                ({ isSkeleton }: SkeletonProps) => (
                    <StackH
                        gap={3}
                        at="sm"
                        principle="flex-action"
                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                        isSkeleton={isSkeleton}
                        items={[
                            () => renderVerifyButton(),
                            () => renderRotateButton(),
                        ]}
                    />
                ),
            ]}
        />
    )

    const engineLabel = engineName ?? "engine"
    const osTabsRow: ReactNode = isSkeleton ? (
        <OsTabsSkeleton />
    ) : (
        <div>
            <TabsExtended
                variant="secondary"
                size="sm"
                selectedKey={os}
                onSelectionChange={(key) => setOs(key as PlaygroundSetupOs)}

            >
                <Tabs.ListContainer>
                    <Tabs.List aria-label="Choose operating system">
                        {OS_ORDER.map((key) => (
                            <Tabs.Tab key={key} id={key}>
                                <span>{OS_LABEL[key]}</span>
                                <Tabs.Indicator />
                            </Tabs.Tab>
                        ))}
                    </Tabs.List>
                </Tabs.ListContainer>
                {/* react-aria's useTab always computes an `aria-controls` id — this row shows no
                    panel content of its own (the guide below is a SEPARATE markdown render), so
                    these stay empty/`sr-only`, same convention as `Toolbar`/`Tabs` atom. */}
                {OS_ORDER.map((key) => (
                    <Tabs.Panel key={key} id={key} className="sr-only">{null}</Tabs.Panel>
                ))}
            </TabsExtended>
        </div>
    )

    const engineStepBody: ReactNode = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <Typography
                        size="sm"
                        color="muted"
                        isSkeleton={isSkeleton}
                        text={`${engineLabel} is where the model actually runs on your machine — once installed, Playground can handle local AI tasks.`}

                    />
                ),
                () => osTabsRow,
                () => (isSkeleton
                    ? <CommandSkeleton lines={3} />
                    : <MarkdownContent source={osGuides[os]} measure="compact" />),
                ...(!isSkeleton && engineReady && engineDetail ? [() => (
                    <Callout
                        status="success"
                        title={`${engineLabel} is ready`}
                        description={engineDetail}


                    />
                )] : []),
                ({ isSkeleton }: SkeletonProps) => <StackH gap={3} isSkeleton={isSkeleton} items={[() => renderVerifyButton()]} />,
            ]}
        />
    )

    const genModelCommand = recommendedGenModel != null ? bashBlock(`ollama pull ${recommendedGenModel}`) : null
    const embedModelCommand = bashBlock(`ollama pull ${EMBEDDING_MODEL_NAME}`)
    const modelsReady = genModelReady && embedModelReady

    const genModelSection = genModelCommand != null ? (
        <StackV
            gap={2}
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => (
                    <Typography
                        isSkeleton={isSkeleton}
                        size="xs"
                        color="muted"
                        text={`Model sinh — ${recommendedGenModel}`}

                    />
                ),
                () => <MarkdownContent source={genModelCommand} measure="compact" />,
            ]}
        />
    ) : null

    const embedModelSection = (
        <StackV
            gap={2}
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => (
                    <Typography
                        isSkeleton={isSkeleton}
                        size="xs"
                        color="muted"
                        text={`Model embedding — ${EMBEDDING_MODEL_NAME}`}

                    />
                ),
                () => <MarkdownContent source={embedModelCommand} measure="compact" />,
            ]}
        />
    )

    const modelsCommandsSection = (
        <StackV
            gap={4}
            isSkeleton={isSkeleton}
            items={[
                () => genModelSection,
                () => embedModelSection,
            ]}
        />
    )

    const modelsSkeletonCommands = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                () => <CommandSkeleton />,
                () => <CommandSkeleton />,
            ]}
        />
    )

    const modelsStepBody: ReactNode = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <Typography
                        size="sm"
                        color="muted"
                        isSkeleton={isSkeleton}
                        text="Models need to be pulled to your machine before use — the right size for your VRAM keeps things running smoothly, without freezing or running out of memory."

                    />
                ),
                () => (isSkeleton ? (
                    modelsSkeletonCommands
                ) : deviceKnown === false ? (
                    <Callout
                        status="warning"
                        title="Device configuration not detected yet"
                        description="Finish installing the engine, then press Check again — Playground will detect your VRAM and suggest the right model size."


                    />
                ) : modelsReady ? (
                    <Callout
                        status="success"
                        title="All models are ready"
                        description="Both the text-generation model and the embedding model are already downloaded on your machine."


                    />
                ) : (
                    modelsCommandsSection
                )),
                ({ isSkeleton }: SkeletonProps) => <StackH gap={3} isSkeleton={isSkeleton} items={[() => renderVerifyButton()]} />,
            ]}
        />
    )

    const agentStatus: StepStatus = agentReady ? "ready" : "pending"
    const engineStatus: StepStatus = engineReady ? "ready" : "pending"
    const modelsStatus: StepStatus = modelsReady ? "ready" : "pending"

    const steps: Array<StepEntry> = [
        { key: "pair", title: "1. Pair local agent", status: agentStatus, body: pairStepBody },
        { key: "engine", title: `2. Install ${engineLabel}`, status: engineStatus, body: engineStepBody },
    ]
    if (flavor === "ollama") {
        steps.push({ key: "models", title: "3. Pull models for your device", status: modelsStatus, body: modelsStepBody })
    }

    // Depends on the loop variable, so it cannot be hoisted to a const above the
    // return — a small named helper instead, in the style this file already uses.
    const renderStep = (step: StepEntry) => (
        <SurfaceCard
            key={step.key}
            label={step.title}
            action={() => (
                <EnumChip
                    value={step.status}
                    map={STEP_STATUS_MAP}
                    isSkeleton={isSkeleton}

                />
            )}
            isSkeleton={isSkeleton}


            body={() => step.body}
        />
    )

    const rotateConfirm = onRefreshPairingCode ? (
        <ConfirmDialog
            isOpen={isRotateConfirmOpen}
            onOpenChange={setRotateConfirmOpen}
            title="Get a new code while the agent is connected?"
            description="The agent is currently using the old code to hold its connection — getting a new code will break the current session until you paste the new code into the agent."
            confirmLabel="Get new code"
            cancelLabel="Not now"
            onConfirm={onConfirmRotate}
            isConfirming={isRefreshingPairingCode}

        />
    ) : null

    return (
        <StackV
            identity={{ tier: "block", component: "PlaygroundSetupSteps" }}
            gap={4}
            isSkeleton={isSkeleton}
            items={[
                ...steps.map((step) => () => renderStep(step)),
                () => rotateConfirm,
            ]}
        />
    )
}

export { PlaygroundSetupSteps }

import React from "react"
import { Skeleton as HeroSkeleton } from "@heroui/react"
import { CheckCircleIcon } from "@phosphor-icons/react"
import { MarkdownContent } from "@sb-components/composites/viewers/MarkdownContent/MarkdownContent"
import { EmptyState } from "@sb-components/composites/feedback/EmptyState/EmptyState"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { Spinner } from "@sb-components/atoms/display/Spinner/Spinner"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `PlaygroundStepGuide` — the left pane of a playground run: read the current step,
 * run its command on your own machine, ask the agent to verify it. Three shapes:
 *   • `Step` — a step with a command fence; `verifyState` moves through its four
 *     data states inside the one action slot.
 *   • `StepNoCommand` — a read-only explainer step with `commandHint` missing, so the
 *     second `MarkdownContent` node is gone.
 *   • `Complete` — `step` is `undefined`, so the pane is replaced end to end by `EmptyState`.
 */

/** Fenced-code wrapper so the command reuses `MarkdownContent`'s own code-block skin. */
const commandFence = (command: string) => "```bash\n" + command + "\n```"

/** One step's authored content. */
export interface PlaygroundStep {
    /** Step heading, e.g. "Step 2 · Build image". */
    title: string
    /** Instructions body, markdown — what to do and why. */
    body: string
    /** The exact shell command to run. Omitted → a read-only explainer step with no command fence. */
    commandHint?: string
}

/** Where the verify action stands right now. */
export type PlaygroundStepVerifyState =
    | "waitingForConnection"
    | "ready"
    | "pending"
    | "missed"

/** Props for {@link PlaygroundStepGuide}. */
export interface PlaygroundStepGuideProps {
    /** The step being read. `undefined` → every step is done, render the completion leaf. */
    step?: PlaygroundStep
    /** State of the verify action for the current step. Ignored once `step` is `undefined`. */
    verifyState: PlaygroundStepVerifyState
    /** Fired when the learner presses `Verify` (from `ready` or to retry from `missed`). */
    onVerify: () => void
    /** Fired from the completion leaf's back-to-hub action. */
    onLeaveComplete: () => void
    /**
     * `true` → shimmer the step-reading shape, DISTINCT from `step` being
     * `undefined` (which means "run complete", a real business state, not a
     * loading one — see `step`'s own doc).
     */
    isSkeleton?: boolean
}

/**
 * The step-reading pane. See the file header for the leaf/state split and why
 * the pending state draws its own spinner instead of `Button`'s.
 *
 * @param props - {@link PlaygroundStepGuideProps}
 */
const PlaygroundStepGuide = ({
    step,
    verifyState,
    onVerify,
    onLeaveComplete,
    isSkeleton = false,
}: PlaygroundStepGuideProps) => {
    if (isSkeleton) {
        return (
            <div>
                <StackV
                    gap={6}
                    isSkeleton={isSkeleton}
                    items={[
                        () => <HeroSkeleton className="h-6 w-48 rounded" />,
                        () => (
                            <StackV
                                gap={2}
                                isSkeleton={isSkeleton}
                                items={[
                                    () => <HeroSkeleton className="h-4 w-full rounded" />,
                                    () => <HeroSkeleton className="h-4 w-2/3 rounded" />,
                                ]}
                            />
                        ),
                        () => <HeroSkeleton className="h-9 w-36 rounded-xl" />,
                    ]}
                />
            </div>
        )
    }
    if (step == null) {
        return (
            <div>
                <EmptyState
                    icon={CheckCircleIcon}
                    tone="neutral"
                    title="All steps completed!"
                    description="You've made it through this playground path. Head back to the hub to pick the next exercise."
                    body={() => (
                        <Button
                            label="Back to Playground hub"
                            variant="secondary"
                            onPress={onLeaveComplete}
                        />
                    )}
                />
            </div>
        )
    }

    // Manual spinner, not `Button`'s own `isPending` skin — see the file header
    // for why an open-ended remote check gets a status row instead of a parked
    // button.
    const verifyPendingStatus = (
        <StackH
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                () => <Spinner size="sm" tone="accent" />,
                () => <Typography size="sm" color="muted" text="Checking…" />,
            ]}
        />
    )

    const verifyControls = (
        <StackV
            gap={2}
            isSkeleton={isSkeleton}
            items={[
                ...(verifyState === "waitingForConnection" ? [() => (
                    <Typography
                        size="sm"
                        color="muted"
                        text="Waiting for a connection to your learning machine…"

                    />
                )] : []),
                ...(verifyState === "ready" || verifyState === "missed" ? [() => (
                    <Button
                        label="Verify this step"
                        variant="primary"
                        onPress={onVerify}

                    />
                )] : []),
                ...(verifyState === "pending" ? [() => verifyPendingStatus] : []),
                ...(verifyState === "missed" ? [() => (
                    <Typography
                        size="xs"
                        color="danger"
                        text="Didn't see the expected result yet — rerun the command and verify again."

                    />
                )] : []),
            ]}
        />
    )

    const commandSection = step.commandHint != null ? (
        <StackV
            gap={2}
            isSkeleton={isSkeleton}
            items={[
                () => <Typography size="xs" weight="medium" color="muted" text="Command to run" />,
                () => (
                    <MarkdownContent
                        source={commandFence(step.commandHint ?? "")}
                        measure="compact"

                    />
                ),
            ]}
        />
    ) : null

    return (
        <div>
            <StackV
                gap={6}
                isSkeleton={isSkeleton}
                items={[
                    () => <Typography size="h4" weight="bold" text={step.title} />,
                    () => <MarkdownContent source={step.body} measure="reading" />,
                    ...(commandSection != null ? [() => commandSection] : []),
                    () => verifyControls,
                ]}
            />
        </div>
    )
}

export { PlaygroundStepGuide }

import type { ReactNode } from "react"
import { cn } from "@heroui/react"

/**
 * BLOCK — `QaChatBubble`: the one surface every message in a Q&A
 * conversation renders inside — accent+right for the viewer's own message,
 * neutral+left for anyone else's. `rounded-2xl`, the documented chat
 * exception to the usual card `rounded-3xl`.
 */

/** Props for {@link QaChatBubble}. */
export interface QaChatBubbleProps {
    /** `"user"` → the viewer's own message (accent, tail on the right). `"assistant"` → anyone else's (neutral, tail on the left). */
    role: "user" | "assistant"
    /** Bubble content — typically a compact {@link import("@sb-components/composites/viewers/MarkdownContent/MarkdownContent").MarkdownContent}. */
    children: ReactNode
    /** `true` → the bubble draws a shimmer block instead of `children`. */
    isSkeleton?: boolean
}

/**
 * The one message-bubble surface a `QaQuestionThread` conversation renders,
 * tinted and tailed toward the viewer's own side or the other party's.
 *
 * @param props - {@link QaChatBubbleProps}
 */
const QaChatBubble = ({ role, children, isSkeleton = false }: QaChatBubbleProps) => (
    <div

        className={cn(
            "min-w-0 rounded-2xl px-3 py-3",
            role === "user"
                ? "rounded-tr-md bg-accent-soft text-accent-soft-foreground"
                : "rounded-tl-md bg-default text-foreground",
            isSkeleton && "h-10 w-40 animate-pulse",
        )}
    >
        {!isSkeleton ? children : null}
    </div>
)

export { QaChatBubble }

import { ArrowLeftIcon, SealCheckIcon } from "@phosphor-icons/react"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { Avatar } from "@sb-components/atoms/display/Avatar/Avatar"
import { AvatarGroup } from "@sb-components/composites/lists/AvatarGroup/AvatarGroup"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * BLOCK — `QaConversationHeader`: the top of an EXPANDED question thread —
 * collapse control, asker identity, who joined in, reply count.
 */

/** Minimal identity this header needs for the asker or a participant. */
export interface QaConversationHeaderPerson {
    /** Stable id. */
    id: string
    /** Display name, already resolved by the caller. */
    displayName: string
    /** Avatar image url. Omitted → generated/initials fallback. */
    avatarUrl?: string
}

/** Props for {@link QaConversationHeader}. */
export interface QaConversationHeaderProps {
    /** Who asked the question. */
    asker: QaConversationHeaderPerson
    /** `true` → a verified badge rides beside the asker's name. */
    isFounderAsker?: boolean
    /** Distinct people who have answered so far — rendered as an overlapping avatar row. */
    participants: ReadonlyArray<QaConversationHeaderPerson>
    /** Total replies (top-level + flattened). `0` swaps the count for a "be first" nudge. */
    replyCount: number
    /** Collapse back to the inbox-row view. */
    onCollapse: () => void
    /** `true` → the viewer can follow this thread for updates. Omit to hide the control entirely. */
    canFollow?: boolean
    /** `true` → the viewer already follows this thread. Only read when {@link canFollow}. */
    isFollowing?: boolean
    /** Follow/unfollow toggle. Only rendered when {@link canFollow}. */
    onToggleFollow?: () => void
    /** `true` → the follow toggle is mid-request (disables it). */
    isFollowPending?: boolean
    /** `true` → every part draws its own shimmer mirror. */
    isSkeleton?: boolean
}

/** The block's own count → label vocabulary (§14d.1) — never handed in pre-formatted. */
const replyLabel = (replyCount: number): string =>
    replyCount > 0 ? `${replyCount} people have answered` : "Be the first to answer"

/**
 * Collapse control + asker identity + who joined in + reply-count nudge, atop
 * an expanded {@link QaQuestionThread}.
 *
 * @param props - {@link QaConversationHeaderProps}
 */
const QaConversationHeader = ({
    asker,
    isFounderAsker,
    participants,
    replyCount,
    onCollapse,
    canFollow,
    isFollowing,
    onToggleFollow,
    isFollowPending,
    isSkeleton = false,
}: QaConversationHeaderProps) => {
    const nameRow = (
        <StackH
            gap={2}
            principle="icon-text"
            explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
            align="center"
            isSkeleton={isSkeleton}

            items={isSkeleton
                ? [() => <Typography size="sm" weight="medium" isSkeleton />]
                : [
                    () => <Typography size="sm" weight="medium" text={asker.displayName} />,
                    ...(isFounderAsker ? [() => (
                        <SealCheckIcon weight="fill" aria-hidden focusable="false" className="size-3.5 shrink-0 text-accent-soft-foreground" />
                    )] : []),
                ]}
        />
    )

    const identityColumn = (
        <StackV
            gap={1}
            classNames={["min-w-0", "flex-1"]}
            isSkeleton={isSkeleton}

            items={[
                () => nameRow,
                () => (isSkeleton ? (
                    <Typography size="xs" color="muted" isSkeleton />
                ) : (
                    <Typography size="xs" color="muted" text={replyLabel(replyCount)} />
                )),
            ]}
        />
    )

    return (
        <div>
            <StackH
                gap={4}
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                align="center"
                isSkeleton={isSkeleton}
                items={[
                    () => (
                        <Button
                            isIconOnly
                            variant="ghost"
                            size="sm"
                            prefixIcon={ArrowLeftIcon}
                            ariaLabel="Collapse conversation"
                            onPress={onCollapse}
                            isDisabled={isSkeleton}

                        />
                    ),
                    () => (
                        <Avatar
                            src={asker.avatarUrl}
                            name={asker.displayName}
                            seed={asker.id}
                            size="sm"
                            isSkeleton={isSkeleton}

                        />
                    ),
                    () => identityColumn,
                    ...(participants.length > 0 ? [() => (
                        <AvatarGroup
                            items={participants.map((p) => ({ key: p.id, src: p.avatarUrl, name: p.displayName, seed: p.id }))}
                            size="sm"
                            isSkeleton={isSkeleton}

                        />
                    )] : []),
                    ...(canFollow ? [() => (
                        <Button
                            variant={isFollowing ? "secondary" : "primary"}
                            size="sm"
                            label={isFollowing ? "Following" : "Follow"}
                            onPress={onToggleFollow}
                            isDisabled={isSkeleton || isFollowPending}

                        />
                    )] : []),
                ]}
            />
        </div>
    )
}

