import React from "react"
import { type SkeletonProps } from "@sb-components/frames/_slot"
import type { ComponentType, SVGProps } from "react"
import { ChartBarIcon, ChartLineIcon, ClockCounterClockwiseIcon } from "@phosphor-icons/react"
import { Tabs, type TabItem } from "@sb-components/atoms/navigation/Tabs/Tabs"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { SurfaceCard, SurfaceCardList, type SurfaceCardListItem } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { EmptyState } from "@sb-components/composites/feedback/EmptyState/EmptyState"
import { StatGridCard, type StatGridCardItem } from "@sb-components/composites/stats/StatGridCard/StatGridCard"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `QuizProgressPanel` — how has this learner been drilling: lifetime numbers and the
 * sessions behind them. Sits beside `QuizSetup` in the setup pane. `Empty` is its
 * own shape — with zero sessions both views would be empty, so the whole panel
 * collapses to one invitation rather than letting the learner flip between two empty
 * views. The `stats` ⇄ `history` view switch is a state inside `Content` (swapping
 * `StatGridCard` vs `SurfaceCardList`) since both read the same already-loaded data.
 */

/** Which half of the panel is showing. */
export type QuizProgressView = "stats" | "history"

/** Icon passed as a COMPONENT reference (§4/§5) — the block renders it at its own fixed scale. */
type StatIcon = ComponentType<SVGProps<SVGSVGElement> & { weight?: "regular" | "bold" }>

/**
 * Label + icon per view. The BLOCK owns this table — same reasoning as
 * `FlashcardModeSwitch`/`ContentModeNav`: it is the vocabulary of THIS switch,
 * and a caller that could pass it would own wording that belongs here.
 */
const VIEW_LABEL: Record<QuizProgressView, string> = {
    stats: "Stats",
    history: "History",
}

const VIEW_ICON: Record<QuizProgressView, StatIcon> = {
    stats: ChartBarIcon,
    history: ClockCounterClockwiseIcon,
}

/** One lifetime number — already reduced/formatted by the caller (a count, a percentage, a streak). */
export interface QuizProgressStat {
    /** Stable React key. */
    key: string
    /** Optional leading glyph, a COMPONENT reference — the block owns its size/tone. */
    icon?: StatIcon
    /** What the number is, e.g. "Accuracy". */
    label: string
    /** The number itself, already formatted by the caller, e.g. "82%", "7 days". */
    value: string
}

/** One past drill in the history view. */
export interface QuizProgressSession {
    /** Stable React key. */
    key: string
    /** What the run was called when it was started. */
    name: string
    /** Already-formatted relative/absolute date from the caller, e.g. "2 days ago". */
    dateLabel: string
    /** Already-formatted result from the caller, e.g. "8/10 correct". */
    scoreLabel: string
    /** Fired when the learner opens this run. Omit for a run that can't be reopened. */
    onPress?: () => void
}

/** Props for {@link QuizProgressPanel}. */
export interface QuizProgressPanelProps {
    /** Section label above the card, localized by the caller — e.g. "How you've been practicing". */
    label: string
    /** Which view is showing now. */
    view: QuizProgressView
    /** Fired with the view the learner picked. */
    onViewChange: (view: QuizProgressView) => void
    /** Accessible name for the view switch, localized by the caller (blocks carry no i18n). */
    viewAriaLabel: string
    /** Lifetime numbers for the stats view. */
    stats: Array<QuizProgressStat>
    /** Past runs for the history view, most recent first. EMPTY (and not loading) → the whole panel becomes one invitation. */
    sessions: Array<QuizProgressSession>
    /** `true` → the card draws its own mirror while progress data loads. */
    isSkeleton?: boolean
}

/** Fixed shape for the loading mirror — a stable 4-cell grid, known ahead of any real data (same reasoning as `ContentDiscussion`'s `SKELETON_ROWS`). */
const SKELETON_STATS: Array<QuizProgressStat> = [
    { key: "s1", label: "", value: "" },
    { key: "s2", label: "", value: "" },
    { key: "s3", label: "", value: "" },
    { key: "s4", label: "", value: "" },
]

/** Fixed shape for the loading mirror — three placeholder rows, same reasoning as {@link SKELETON_STATS}. */
const SKELETON_SESSIONS: Array<QuizProgressSession> = [
    { key: "s1", name: "", dateLabel: "", scoreLabel: "" },
    { key: "s2", name: "", dateLabel: "", scoreLabel: "" },
    { key: "s3", name: "", dateLabel: "", scoreLabel: "" },
]

/** Builds one {@link StatGridCardItem}'s free-form content — icon + label over the value, shimmering together via `isSkeleton`. */
const statCell = (stat: QuizProgressStat, isSkeleton: boolean): StatGridCardItem => {
    const Icon = stat.icon
    return {
        key: stat.key,
        content: () => (
            <StackV
                gap={2}
                principle="title-subtitle"
                explain="Title over supporting line — not label-field, because neither line is a form control label."
                isSkeleton={isSkeleton}
                items={[
                    ({ isSkeleton }: SkeletonProps) => (
                        <StackH
                            gap={2}
                            principle="icon-text"
                            explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
                            align="center"
                            isSkeleton={isSkeleton}
                            items={[
                                ...(Icon ? [() => <Icon aria-hidden focusable="false" className="size-4 text-muted" />] : []),
                                () => <Typography size="xs" color="muted" isSkeleton={isSkeleton} text={stat.label} />,
                            ]}
                        />
                    ),
                    () => <Typography size="lg" weight="semibold" isSkeleton={isSkeleton} text={stat.value} />,
                ]}
            />
        ),
    }
}

/**
 * The practice-progress panel. See the file header for the full contract.
 *
 * @param props - {@link QuizProgressPanelProps}
 */
const QuizProgressPanel = ({
    label,
    view,
    onViewChange,
    viewAriaLabel,
    stats,
    sessions,
    isSkeleton = false,
}: QuizProgressPanelProps) => {
    const tabItems: Array<TabItem> = (Object.keys(VIEW_LABEL) as Array<QuizProgressView>).map((key) => ({
        key,
        label: VIEW_LABEL[key],
        icon: VIEW_ICON[key],
    }))

    // No run has ever happened — see the file header's judgment call.
    const isEmpty = !isSkeleton && sessions.length === 0

    const statItems = (isSkeleton ? SKELETON_STATS : stats).map((stat) => statCell(stat, isSkeleton))

    const historyItems: Array<SurfaceCardListItem> = (isSkeleton ? SKELETON_SESSIONS : sessions).map((session) => ({
        key: session.key,
        title: session.name,
        subtitle: session.dateLabel,
        metaText: session.scoreLabel,
        onPress: isSkeleton ? undefined : session.onPress,
    }))

    return (
        <div>
            <SurfaceCard
                label={label}

                body={() =>
                    isEmpty ? (
                        <EmptyState
                            icon={ChartLineIcon}
                            title="No practice sessions yet"
                            description="Start a session in the panel beside this one — your first run will show its stats and history here."

                        />
                    ) : (
                        <StackV
                            gap={6}
                            isSkeleton={isSkeleton}
                            items={[
                                () => (
                                    <div>
                                        <Tabs
                                            items={tabItems}
                                            selectedKey={view}
                                            onSelectionChange={(key) => onViewChange(key as QuizProgressView)}
                                            ariaLabel={viewAriaLabel}
                                            isSkeleton={isSkeleton}

                                        />
                                    </div>
                                ),
                                () => (
                                    view === "stats" ? (
                                        <div>
                                            <StatGridCard items={statItems} />
                                        </div>
                                    ) : (
                                        <SurfaceCardList
                                            items={historyItems}
                                            isSkeleton={isSkeleton}


                                        />
                                    )
                                ),
                            ]}
                        />
                    )
                }
            />
        </div>
    )
}

export { QuizProgressPanel }

import React from "react"
import { CheckCircleIcon, XCircleIcon } from "@phosphor-icons/react"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { InputTextarea } from "@sb-components/atoms/forms"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { SurfaceCard } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { MarkdownContent } from "@sb-components/composites/viewers/MarkdownContent/MarkdownContent"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `QuizQuestion` — one question, the learner's answer, and the verdict. The answer
 * field turns read-only after grading rather than emptying (the value of a drill is
 * comparing what you said with what was expected). The expected answer appears only
 * after grading. The verdict is a chip; the reasoning rides as a document below it.
 * No score number — the running total lives in `WorkSessionHeader`.
 */

/** How the answer was judged. */
export type QuizVerdict = "correct" | "incorrect"

/** Props for {@link QuizQuestion}. */
export interface QuizQuestionProps {
    /** The question, as authored markdown. */
    question: string
    /** Seniority this question aims at, e.g. "Middle" — already localized. */
    levelLabel?: string
    /** What the learner has typed. */
    answer: string
    /** Fired as the learner types. Ignored once graded. */
    onAnswerChange: (value: string) => void
    /** Fired when the learner submits for grading. */
    onSubmit: () => void
    /** Set → the answer has been judged; the field locks and the verdict shows. */
    verdict?: QuizVerdict
    /** The expected answer, as markdown. Shown ONLY after grading. */
    expectedAnswer?: string
    /** Why the answer was judged that way, as markdown. Shown only after grading. */
    explanation?: string
    /** Label of the submit control, localized by the caller. */
    submitLabel: string
    /** Label of the move-on control shown after grading. */
    nextLabel: string
    /** Fired when the learner moves to the next question. */
    onNext: () => void
    /** `true` → grading is in flight; the submit control owns the busy affordance. */
    isPending?: boolean
    /** `true` → the card mirrors itself while the question is drawn. */
    isSkeleton?: boolean
}

/**
 * One drill question. See the file header for the full contract.
 *
 * @param props - {@link QuizQuestionProps}
 */
const QuizQuestion = ({
    question,
    levelLabel,
    answer,
    onAnswerChange,
    onSubmit,
    verdict,
    expectedAnswer,
    explanation,
    submitLabel,
    nextLabel,
    onNext,
    isPending = false,
    isSkeleton = false,
}: QuizQuestionProps) => {
    const isGraded = verdict != null

    const levelRow = levelLabel != null ? (
        <StackH
            gap={3}
            principle="chip-row"
            explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
            align="center"
            isSkeleton={isSkeleton}
            items={[() => <Chip tone="default" text={levelLabel} isSkeleton={isSkeleton} />]}
        />
    ) : null

    const expectedAnswerBlock = expectedAnswer != null ? (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                () => <Typography size="sm" weight="medium" isSkeleton={isSkeleton} text="Expected answer" />,
                () => (
                    <MarkdownContent
                        source={expectedAnswer}
                        measure="compact"

                    />
                ),
            ]}
        />
    ) : null

    const gradedDetails = isGraded ? (
        <StackV
            gap={6}
            principle="block-boundary"
            explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <StackH
                        gap={3}
                        principle="chip-row"
                        explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                        align="center"
                        isSkeleton={isSkeleton}
                        items={[
                            // One chip for the classifying axis. The reasoning below is an
                            // ordinary document — two loud signals and the learner reads the
                            // verdict twice.
                            () => (
                                <Chip
                                    tone={verdict === "correct" ? "success" : "danger"}
                                    icon={verdict === "correct" ? CheckCircleIcon : XCircleIcon}
                                    text={verdict === "correct" ? "Correct" : "Not quite"}
                                    isSkeleton={isSkeleton}
                                />
                            ),
                        ]}
                    />
                ),
                () => expectedAnswerBlock,
                ...(explanation != null ? [() => (
                    <MarkdownContent
                        source={explanation}
                        measure="compact"

                    />
                )] : []),
            ]}
        />
    ) : null

    const actionRow = (
        <StackH
            gap={3}
            principle="flex-action"
            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
            justify="end"
            isSkeleton={isSkeleton}
            items={[
                () =>
                    isGraded ? (
                        <Button label={nextLabel} variant="primary" onPress={onNext} />
                    ) : (
                        <Button
                            label={submitLabel}
                            variant="primary"
                            onPress={onSubmit}
                            isDisabled={answer.trim().length === 0}
                            isPending={isPending}

                        />
                    ),
            ]}
        />
    )

    return (
        <div>
            <SurfaceCard
                isSkeleton={isSkeleton}

                body={() => (
                    <StackV
                        gap={6}
                        items={[
                            ...(levelRow != null ? [() => levelRow] : []),
                            () => (
                                <MarkdownContent
                                    source={question}
                                    measure="reading"

                                />
                            ),
                            // Read-only rather than emptied: the whole value of a drill is comparing
                            // what you SAID with what was expected, and clearing the field takes that
                            // comparison away exactly when it becomes useful.
                            () => (
                                <InputTextarea
                                    value={answer}
                                    onValueChange={onAnswerChange}
                                    placeholder="Answer as if you're speaking to the interviewer"
                                    ariaLabel="Answer"
                                    rows={4}
                                    isDisabled={isGraded}

                                />
                            ),
                            ...(gradedDetails != null ? [() => gradedDetails] : []),
                            () => actionRow,
                        ]}
                    />
                )}
            />
        </div>
    )
}

export { QuizQuestion }

import React from "react"
import type { ReactNode } from "react"
import { Skeleton as HeroSkeleton } from "@heroui/react"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { SurfaceCard } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { MarkdownContent } from "@sb-components/composites/viewers/MarkdownContent/MarkdownContent"
import { RatingBar, type RatingOption } from "@sb-components/starci/blocks/learn/RatingBar/RatingBar"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `QuizRecapList` — the run is over: go back over what you answered and say how well
 * you actually knew each one. This learner-supplied grade is not the run's verdict —
 * a card can be marked correct yet be one the learner wants back tomorrow (the
 * `CorrectButShaky` case), which the spaced-repetition schedule needs. Already-graded
 * cards keep their rating bar — nothing locks after a tap, so a changed mind still
 * counts. Card count and which are rated are states of one shape; finishing changes
 * only the counter line.
 */

/** One answered card in the recap. */
export interface QuizRecapCard {
    /** Stable React key. */
    key: string
    /** The question, as authored markdown. */
    question: string
    /** The expected answer, as authored markdown. */
    expectedAnswer: string
    /** What the learner typed during the run. */
    givenAnswer?: string
    /** How the run judged it. */
    wasCorrect: boolean
    /** The learner's own recall grade, once they have given one. */
    rating?: number
}

interface QuizRecapListOwnProps {
    /** Recall grades offered per card. */
    ratingOptions: Array<RatingOption>
    /** Fired with the card key and the grade the learner picked. */
    onRate: (cardKey: string, grade: number) => void
    /** Accessible name for each card's rating group, localized by the caller. */
    ratingAriaLabel: string
    /** Card count to shimmer while `isSkeleton` (no real `cards` yet). Defaults to `3`. */
    skeletonCount?: number
}

/**
 * Props for {@link QuizRecapList}. `cards` is REQUIRED unless `isSkeleton`
 * (§12b) — a shimmer recap has no real cards to show yet.
 */
export type QuizRecapListProps = QuizRecapListOwnProps &
    (
        | { isSkeleton: true; cards?: Array<QuizRecapCard> }
        | { isSkeleton?: false; cards: Array<QuizRecapCard> }
    )

/**
 * One recap card's content — verdict chip, question, given/expected answers,
 * rating bar. Extracted to a helper (rather than hoisted to a const) because
 * it depends on the loop variable `card` from the `.map()` that calls it.
 */
const recapCardBody = (
    card: QuizRecapCard,
    ratingOptions: Array<RatingOption>,
    onRate: (cardKey: string, grade: number) => void,
    ratingAriaLabel: string,
): ReactNode => (
    <StackV
        gap={6}
        principle="block-boundary"
        explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
        items={[
            () => (
                <StackH
                    gap={3}
                    principle="chip-row"
                    explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                    align="center"

                    items={[
                        () => (
                            <Chip
                                tone={card.wasCorrect ? "success" : "danger"}
                                text={card.wasCorrect ? "Correct" : "Incorrect"}

                            />
                        ),
                    ]}
                />
            ),
            () => (
                <MarkdownContent
                    source={card.question}
                    measure="compact"

                />
            ),
            ...(card.givenAnswer != null ? [() => (
                <StackV
                    gap={3}

                    items={[
                        () => <Typography size="xs" color="muted" text="Your answer" />,
                        () => <Typography size="sm" text={card.givenAnswer} />,
                    ]}
                />
            )] : []),
            () => (
                <StackV
                    gap={3}

                    items={[
                        () => <Typography size="xs" color="muted" text="Expected answer" />,
                        () => (
                            <MarkdownContent
                                source={card.expectedAnswer}
                                measure="compact"

                            />
                        ),
                    ]}
                />
            ),
            // Stays put after a tap. A learner going back over a run changes
            // their mind, and removing the control would make the first tap
            // final without ever saying so.
            () => (
                <RatingBar
                    options={ratingOptions}
                    onRate={(grade) => onRate(card.key, grade)}
                    ariaLabel={ratingAriaLabel}


                />
            ),
        ]}
    />
)

/**
 * The end-of-run recap. See the file header for the full contract.
 *
 * @param props - {@link QuizRecapListProps}
 */
const QuizRecapList = ({
    cards,
    ratingOptions,
    onRate,
    ratingAriaLabel,
    isSkeleton = false,
    skeletonCount = 3,
}: QuizRecapListProps) => {
    if (isSkeleton) {
        return (
            <div>
                <StackV
                    gap={6}
                    isSkeleton={isSkeleton}
                    items={[
                        () => <HeroSkeleton className="h-3.5 w-40 rounded" />,
                        ...Array.from({ length: skeletonCount }, (_unused, index) => () => (
                            <SurfaceCard
                                key={index}

                                body={() => (
                                    <StackV
                                        gap={6}
                                        isSkeleton={isSkeleton}
                                        items={[
                                            () => <HeroSkeleton className="h-5 w-16 rounded-full" />,
                                            () => <HeroSkeleton className="h-4 w-full rounded" />,
                                            () => <HeroSkeleton className="h-4 w-2/3 rounded" />,
                                        ]}
                                    />
                                )}
                            />
                        )),
                    ]}
                />
            </div>
        )
    }
    const unrated = (cards ?? []).filter((card) => card.rating == null).length

    return (
        <div>
            <StackV
                gap={6}
                isSkeleton={isSkeleton}
                items={[
                    // Counted, not celebrated. The recap is work; the learner is here to finish
                    // it, not to be congratulated for starting it.
                    () => (
                        <Typography
                            size="sm"
                            color="muted"
                            text={unrated > 0 ? `${unrated}/${(cards ?? []).length} cards left to self-grade` : `All ${(cards ?? []).length} cards self-graded`}

                        />
                    ),
                    ...(cards ?? []).map((card) => () => (
                        <SurfaceCard
                            key={card.key}

                            body={() => recapCardBody(card, ratingOptions, onRate, ratingAriaLabel)}
                        />
                    )),
                ]}
            />
        </div>
    )
}

export { QuizRecapList }

import React from "react"
import { type SkeletonProps } from "@sb-components/frames/_slot"
import { PlayIcon } from "@phosphor-icons/react"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { ButtonRadioGroup } from "@sb-components/composites/buttons/ButtonRadioGroup/ButtonRadioGroup"
import { InputText } from "@sb-components/atoms/forms"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { SurfaceCard } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { Callout } from "@sb-components/composites/feedback/Callout/Callout"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `QuizSetup` — choose the shape of a drill (length, seniority, name), then start
 * it. The block owns the domain wording and the lengths behind it: the learner
 * picks "quick" or "deep" and the block turns that into 5 or 10 cards, saying so on
 * the button. A run already in progress takes priority — the resume strip leads the
 * card above the form. A failed draw is reported next to the button that failed.
 */

/** How long a drill runs. */
export type QuizLength = "quick" | "deep"

/** Seniority the questions aim at. */
export type QuizLevel = "junior" | "middle" | "senior" | "staff"

/** Card count per length. The BLOCK owns this — it is the judgement, not a prop. */
const LENGTH_CARDS: Record<QuizLength, number> = { quick: 5, deep: 10 }

const LENGTH_LABEL: Record<QuizLength, string> = { quick: "Quick", deep: "Deep" }

const LEVEL_LABEL: Record<QuizLevel, string> = {
    junior: "Junior",
    middle: "Middle",
    senior: "Senior",
    staff: "Staff",
}

/** A run the learner left unfinished. */
export interface QuizResumable {
    /** What the run was called when it was started. */
    name: string
    /** How many cards were answered already. */
    answered: number
    /** How many cards the run has in total. */
    total: number
    /** Fired when the learner picks the run back up. */
    onResume: () => void
}

/** Props for {@link QuizSetup}. */
export interface QuizSetupProps {
    /** Section label, localized by the caller — e.g. "Set up session". */
    label: string
    /** Current run name. */
    name: string
    /** Fired as the learner types a name. */
    onNameChange: (value: string) => void
    /** Chosen length. */
    length: QuizLength
    /** Fired when the learner picks a length. */
    onLengthChange: (length: QuizLength) => void
    /** Chosen seniority. */
    level: QuizLevel
    /** Fired when the learner picks a seniority. */
    onLevelChange: (level: QuizLevel) => void
    /** Fired when the learner starts the run. */
    onStart: () => void
    /** A run left unfinished. Present → the resume strip leads the card. */
    resumable?: QuizResumable
    /** `true` → the draw is in flight; the start button owns the busy affordance. */
    isPending?: boolean
    /** Set → the draw failed. Reported beside the action that failed. */
    errorMessage?: string
    /** `true` → the card draws its own mirror while the setup data loads. */
    isSkeleton?: boolean
}

/**
 * The drill setup form. See the file header for the full contract.
 *
 * @param props - {@link QuizSetupProps}
 */
const QuizSetup = ({
    label,
    name,
    onNameChange,
    length,
    onLengthChange,
    level,
    onLevelChange,
    onStart,
    resumable,
    isPending = false,
    errorMessage,
    isSkeleton = false,
}: QuizSetupProps) => {
    const nameField = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => <Typography size="sm" weight="medium" isSkeleton={isSkeleton} text="Session name" />,
                ({ isSkeleton }: SkeletonProps) => (
                    <InputText
                        value={name}
                        onValueChange={onNameChange}
                        placeholder="e.g. review Docker before the interview"
                        ariaLabel="Session name"
                        isSkeleton={isSkeleton}

                    />
                ),
            ]}
        />
    )

    const lengthField = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => <Typography size="sm" weight="medium" isSkeleton={isSkeleton} text="Length" />,
                () => (
                    <ButtonRadioGroup
                        ariaLabel="Session length"
                        value={length}
                        onChange={onLengthChange}

                        items={(Object.keys(LENGTH_LABEL) as Array<QuizLength>).map((key) => ({
                            value: key,
                            content: `${LENGTH_LABEL[key]} · ${LENGTH_CARDS[key]} questions`,
                        }))}
                    />
                ),
            ]}
        />
    )

    const levelField = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => <Typography size="sm" weight="medium" isSkeleton={isSkeleton} text="Level" />,
                () => (
                    <ButtonRadioGroup
                        ariaLabel="Question level"
                        value={level}
                        onChange={onLevelChange}

                        items={(Object.keys(LEVEL_LABEL) as Array<QuizLevel>).map((key) => ({
                            value: key,
                            content: LEVEL_LABEL[key],
                        }))}
                    />
                ),
            ]}
        />
    )

    const submitRow = (
        <StackH
            gap={3}
            principle="flex-action"
            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
            justify="end"
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => (
                    <Button
                        label={`Start · ${LENGTH_CARDS[length]} questions`}
                        variant="primary"
                        prefixIcon={PlayIcon}
                        onPress={onStart}
                        isPending={isPending}
                        isSkeleton={isSkeleton}

                    />
                ),
            ]}
        />
    )

    // The error sits WITH the action that failed. At the top of the card it
    // would read as a problem with the whole form.
    const actionField = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                ...(errorMessage != null ? [() => (
                    <Callout
                        status="danger"
                        title={errorMessage}

                    />
                )] : []),
                () => submitRow,
            ]}
        />
    )

    return (
        <div>
            <SurfaceCard
                label={label}
                isSkeleton={isSkeleton}

                body={() => (
                    <StackV
                        gap={6}
                        isSkeleton={isSkeleton}
                        items={[
                            ...(resumable != null ? [() => (
                                // A learner who left mid-run almost always means to come back. Making
                                // them scroll past a start button to find their own session is how one
                                // run gets abandoned twice.
                                <Callout
                                    title={resumable.name}
                                    description={`In progress · ${resumable.answered}/${resumable.total} questions`}
                                    actionLabel="Continue"
                                    onAction={resumable.onResume}

                                />
                            )] : []),
                            () => nameField,
                            () => lengthField,
                            () => levelField,
                            () => actionField,
                        ]}
                    />
                )}
            />
        </div>
    )
}

export { QuizSetup }

import React from "react"
import type { ReactNode } from "react"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { SurfaceCardPressableGroup, type SurfaceCardPressableGroupItem } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `RatingBar` — how well did you remember it: four tiles tapped after an answer is
 * revealed, feeding the spaced-repetition schedule. Shared between flashcard review
 * and quiz recap. Grading is an action, not a selection — nothing stays lit after
 * the tap. The colour ramp (rose → emerald) is a tier, not a status: "I forgot" is
 * not an error and "easy" is not a success, just positions on one axis. The hint
 * line and the pending lock are states; `isSkeleton` is its own leaf.
 */

/** One recall grade offered to the learner. */
export interface RatingOption {
    /** SM-2 grade reported to {@link RatingBarProps.onRate}, 0 = forgot … 3 = easy. */
    grade: number
    /** Button label, localized by the caller (blocks carry no i18n). */
    label: string
    /** Optional second line, usually the next-interval preview. */
    hint?: string
}

/**
 * Grade → palette colour for the tile's verdict band. A grade is a TIER, so it
 * uses the difficulty ramp rather than the status palette.
 */
const GRADE_COLOR: Record<number, string> = {
    0: "rose-500",
    1: "orange-500",
    2: "amber-500",
    3: "emerald-500",
}

/** Props for {@link RatingBar}. */
export interface RatingBarProps {
    /** Grades to offer, weakest recall first. */
    options: Array<RatingOption>
    /** Called with the grade the learner picked. */
    onRate: (grade: number) => void
    /**
     * Accessible name for the group, localized by the caller. Without it a screen
     * reader hears four loose buttons with nothing tying them together.
     */
    ariaLabel: string
    /** `true` → a grade is in flight; every tile stops accepting taps. */
    isPending?: boolean
    /** `true` → the group draws its own tile mirror. */
    isSkeleton?: boolean
}

/**
 * One rating tile's content — label + key-hint chip, plus an optional interval
 * hint. Extracted to a helper (rather than hoisted to a const) because it
 * depends on the loop variables `option`/`position` from the `.map()` that
 * calls it.
 */
const ratingTileBody = (option: RatingOption, position: number): ReactNode => (
    <StackV
        gap={3}
        principle="sibling-stack"
        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."

        items={[
            () => (
                <StackH
                    gap={3}
                    principle="chip-row"
                    explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                    align="center"
                    justify="between"

                    items={[
                        () => <Typography size="sm" weight="medium" text={option.label} />,
                        // One chip per tile, and it goes to the KEY — that is the classifying
                        // mark. The interval below is a quiet fact, so it stays as text.
                        () => <Chip tone="default" text={String(position + 1)} />,
                    ]}
                />
            ),
            ...(option.hint != null ? [() => (
                <Typography size="xs" color="muted" text={option.hint} />
            )] : []),
        ]}
    />
)

/**
 * The recall-grade row. See the file header for the full contract.
 *
 * @param props - {@link RatingBarProps}
 */
const RatingBar = ({
    options,
    onRate,
    ariaLabel,
    isPending = false,
    isSkeleton = false,
}: RatingBarProps) => {
    const items: Array<SurfaceCardPressableGroupItem> = options.map((option, position) => ({
        key: String(option.grade),
        onPress: () => onRate(option.grade),
        isDisabled: isPending,
        withVerdict: { enable: true, color: GRADE_COLOR[option.grade] },
        content: () => ratingTileBody(option, position),
    }))

    return (
        <div>
            <div>
                <SurfaceCardPressableGroup ariaLabel={ariaLabel} columns={{ base: 2, md: 4 }} keyboardShortcut items={items} isSkeleton={isSkeleton} principle="content-row"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title." />
            </div>
        </div>
    )
}

export { RatingBar }

import { cn } from "@heroui/react"
import { REACTION_BY_TYPE, type ReactionType } from "../types"

/** Props for the {@link ReactionGlyph} helper below. */
interface ReactionGlyphProps {
    type: ReactionType
    size: "xs" | "sm" | "md"
    className?: string
}

const REACTION_GLYPH_CLS: Record<ReactionGlyphProps["size"], string> = {
    xs: "size-4",
    sm: "size-5",
    md: "size-7",
}

/** Real Fluent Emoji SVG for a reaction (`public/reactions/<type>.svg` — same asset `src` serves). */
export const ReactionGlyph = ({ type, size, className }: ReactionGlyphProps) => (
    <img
        src={`/reactions/${type}.svg`}
        alt={REACTION_BY_TYPE[type].label}
        aria-hidden
        draggable={false}
        className={cn("inline-block select-none", REACTION_GLYPH_CLS[size], className)}
    />
)

import React from "react"
import { CheckCircleIcon, XCircleIcon } from "@phosphor-icons/react"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { ButtonRadioGroup, type ButtonRadioGroupItem } from "@sb-components/composites/buttons/ButtonRadioGroup/ButtonRadioGroup"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import {
    AsyncContent,
    type AsyncContentEmptyProps,
    type AsyncContentErrorProps,
} from "@sb-components/composites/async/AsyncContent/AsyncContent"
import { Cluster } from "@sb-components/frames/Cluster/Cluster"

/**
 * `SubmissionAttemptSelector` — which graded attempt the reader is looking at: a
 * flex-wrap row of attempt buttons (verdict + "Attempt N" + score) plus an optional
 * "+N" trigger for the rest of the history. The select chrome is `ButtonRadioGroup`
 * and each button's content is a `Chip`; the block turns `{ attemptNumber, score,
 * isPassing }` into that composition, and the "+N" trigger uses the group's own
 * `trailing` slot. Pressing "+N" only fires `onOverflowPress` — what it opens is a
 * screen decision. Loading, empty, error, few, and many attempts are all states of
 * the one chip strip.
 */

/** One graded attempt the reader can switch to. */
export interface SubmissionAttempt {
    /** Stable id — the value reported to {@link SubmissionAttemptSelectorProps.onSelect}. */
    id: string
    /** 1-based order the attempt was made in — the block turns this into "Attempt N". */
    attemptNumber: number
    /** `null` → not graded yet (or ungraded by design); shown without a score. */
    score: number | null
    /** Drives the verdict glyph + `Chip` tone — pass (`success`) or fail (`danger`). */
    isPassing: boolean
}

/** Props for {@link SubmissionAttemptSelector}. */
export interface SubmissionAttemptSelectorProps {
    /** The attempts offered, in display order. */
    attempts: Array<SubmissionAttempt>
    /** The attempt currently being viewed. Unset → none selected yet. */
    selectedId?: string
    /** Fired with the id of the attempt the reader picked. */
    onSelect: (id: string) => void
    /** Accessible name for the row, localized by the caller (blocks carry no i18n). */
    ariaLabel: string
    /** How many MORE attempts exist beyond this row — set (and > 0) → the "+N" trigger shows. */
    overflowCount?: number
    /** Label for the "+N" trigger. Defaults to `+{overflowCount}` when omitted. */
    overflowLabel?: string
    /**
     * Fired when the reader presses "+N". What that opens is the CALLER's call
     * (Rule 7) — a history drawer, a modal, a route change — this block only
     * reports the press.
     */
    onOverflowPress?: () => void
    /** `true` → this row's own fetch is in flight; the strip shows its skeleton mirror. */
    isLoading?: boolean
    /** `true` (once loading has finished) → the row falls to its empty message. */
    isEmpty?: boolean
    /** Empty-state message. Defaults to a standard "no attempts yet" line. */
    emptyLabel?: string
    /** Truthy → the row falls to its error message (beats loading, per `AsyncContent`). */
    error?: unknown
    /** Retry handler — paired with `retryLabel` to show a retry button on the error branch. */
    onRetry?: () => void
    /** Label of the retry button — required alongside `onRetry` for it to appear. */
    retryLabel?: string
    /** `true` → a parent-forced skeleton paint, same branch as `isLoading` (see file header). */
    isSkeleton?: boolean
}

const EMPTY_LABEL_DEFAULT = "No attempts to choose from yet"
const ERROR_TITLE = "Couldn't load the attempt list"

/** No attempt id is ever the empty string, so `""` safely reads as "none selected". */
const NONE_SELECTED = ""

/** How many skeleton pills mirror the strip while `attempts` hasn't landed yet. */
const SKELETON_ITEM_COUNT = 3

/** Turns one attempt into its `Chip` — the verdict glyph, "Attempt N", and its score. */
const attemptChip = (attempt: SubmissionAttempt) => (
    <Chip
        icon={attempt.isPassing ? CheckCircleIcon : XCircleIcon}
        tone={attempt.isPassing ? "success" : "danger"}
        text={attempt.score != null ? `Attempt ${attempt.attemptNumber} · ${attempt.score}` : `Attempt ${attempt.attemptNumber}`}

    />
)

/** Mirrors the real strip's footprint while attempts are loading — pill-for-pill, no data. */
const AttemptRowSkeleton = () => (
    <Cluster
        gap={3}

        items={Array.from({ length: SKELETON_ITEM_COUNT }, () => () => <Button isSkeleton size="sm" />)}
    />
)

/**
 * The graded-attempt row. See the file header for what it owns (verdict+label
 * wording, the few-vs-many decision) and what it deliberately does not (what
 * "+N" opens).
 *
 * @param props - {@link SubmissionAttemptSelectorProps}
 */
const SubmissionAttemptSelector = ({
    attempts,
    selectedId,
    onSelect,
    ariaLabel,
    overflowCount,
    overflowLabel,
    onOverflowPress,
    isLoading = false,
    isEmpty = false,
    emptyLabel,
    error,
    onRetry,
    retryLabel,
    isSkeleton = false,
}: SubmissionAttemptSelectorProps) => {
    const hasOverflow = (overflowCount ?? 0) > 0

    const emptyContent: AsyncContentEmptyProps = {
        title: emptyLabel ?? EMPTY_LABEL_DEFAULT,

    }

    const errorContent: AsyncContentErrorProps = {
        title: ERROR_TITLE,
        onRetry,
        retryLabel,

    }

    const items: Array<ButtonRadioGroupItem<string>> = attempts.map((attempt) => ({
        value: attempt.id,
        content: attemptChip(attempt),
    }))

    return (
        <div>
            <AsyncContent
                // A parent-forced skeleton and this row's own in-flight fetch share the
                // one loading branch `AsyncContent` exposes (see file header).
                isLoading={isLoading || isSkeleton}
                skeleton={() => <AttemptRowSkeleton />}
                isEmpty={isEmpty}
                emptyContent={emptyContent}
                error={error}
                errorContent={errorContent}

                content={() => (
                    <ButtonRadioGroup
                        ariaLabel={ariaLabel}
                        value={selectedId ?? NONE_SELECTED}
                        onChange={onSelect}
                        items={items}

                        trailing={
                            hasOverflow ? (
                                <Button
                                    variant="ghost"
                                    size="sm"
                                    label={overflowLabel ?? `+${overflowCount}`}
                                    onPress={onOverflowPress}

                                />
                            ) : undefined
                        }
                    />
                )}
            />
        </div>
    )
}

export { SubmissionAttemptSelector }

import React from "react"
import type { ComponentType, ReactNode, SVGProps } from "react"
import { InfoIcon, LightbulbIcon, MapPinIcon, WarningCircleIcon } from "@phosphor-icons/react"
import { cn } from "@heroui/react"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import {
    AsyncContentEmpty,
    AsyncContentError,
} from "@sb-components/composites/async/AsyncContent/AsyncContent"
import { SurfaceCardAccordion, type SurfaceCardAccordionItem } from "@sb-components/composites/cards/SurfaceCard/SurfaceCard"
import { MarkdownContent } from "@sb-components/composites/viewers/MarkdownContent/MarkdownContent"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `SubmissionFindingsList` — "Feedback": one accordion row per quality-gate finding
 * on a graded attempt — severity icon + plain-text message (backtick code only) +
 * location chip in the trigger; markdown detail, a linked file location, and a
 * markdown suggestion in the panel. The frame is `SurfaceCard.Accordion` end to end;
 * the block supplies the domain (severity → icon/tone/sort-rank, the high→low sort,
 * the repo-URL → file-link builder). Loading, empty, error, and populated are all
 * states of the one accordion card, routed through its own `isSkeleton`/`emptyState`
 * axes.
 */

/** Severity a finding carries — drives the trigger icon/tone and the sort rank (high sorts first). */
export type SubmissionFeedbackSeverity = "high" | "medium" | "low"

/** An icon passed as a COMPONENT, rendered by this block at the size the text beside it uses. */
type SeverityIconComponent = ComponentType<SVGProps<SVGSVGElement> & { weight?: "regular" | "bold" }>

/** One severity's trigger icon + text tone + sort rank — see {@link SEVERITY_VISUAL}. */
interface SeverityVisual {
    /** Trigger icon for this severity. */
    icon: SeverityIconComponent
    /** Tailwind text-color class for the icon (matches the severity's weight). */
    toneClassName: string
    /** Sort rank — lower sorts first (high = 0). */
    rank: number
}

/**
 * Severity → trigger icon + text tone + sort rank. This is the block's own
 * domain vocabulary, never something a caller hands in.
 */
const SEVERITY_VISUAL: Record<SubmissionFeedbackSeverity, SeverityVisual> = {
    high: { icon: WarningCircleIcon, toneClassName: "text-danger", rank: 0 },
    medium: { icon: WarningCircleIcon, toneClassName: "text-warning", rank: 1 },
    low: { icon: InfoIcon, toneClassName: "text-muted", rank: 2 },
}

/** One quality-gate finding for a graded attempt. */
export interface SubmissionFinding {
    /** Stable id — also the accordion row's expand key. */
    id: string
    /**
     * Short summary shown (clamped to one line) in the accordion trigger — plain
     * text, at most `` `code` `` spans (never bold/italic/link: a trigger title
     * is tier 1). Full markdown
     * belongs in `detail`/`suggestion`, which render in the panel body instead.
     */
    message: string
    /** Longer explanation, authored as markdown, shown in the panel. */
    detail?: string
    /** Suggested fix, authored as markdown, shown in the panel. */
    suggestion?: string
    /** Repo-relative file path this finding points at, e.g. `src/app/page.tsx`. */
    location?: string
    /** High/medium/low — decides the trigger icon/tone and the sort order. */
    severity: SubmissionFeedbackSeverity
    /** Author-authored order among findings that share a severity. Defaults to `0`. */
    sortIndex?: number
}

/** Props for {@link SubmissionFindingsList}. */
export interface SubmissionFindingsListProps {
    /** The findings, in ANY order — the block re-sorts them itself (severity, then `sortIndex`). */
    findings: Array<SubmissionFinding>
    /**
     * Repo URL the attempt was submitted from — turns each `location` into a
     * `blob/HEAD` deep-link. Omit → `location` still shows, as plain text.
     */
    repositoryUrl?: string
    /** Section label rendered above the card (e.g. `"Feedback"`). */
    label: string
    /** `true` → this list's own fetch is in flight; the card falls to its self-mirror. */
    isLoading?: boolean
    /** `true` (once loading has finished) → the card falls to its empty message. */
    isEmpty?: boolean
    /** Empty-state title. Defaults to a standard "no findings yet" line. */
    emptyLabel?: string
    /** Truthy → the card falls to its error message (beats loading/empty — see file header). */
    error?: unknown
    /** Retry handler — paired with `retryLabel` to show a retry button on the error branch. */
    onRetry?: () => void
    /** Label of the retry button — required alongside `onRetry` for it to appear. */
    retryLabel?: string
    /** `true` → a parent-forced skeleton paint, same branch as `isLoading` (see file header). */
    isSkeleton?: boolean
}

const EMPTY_LABEL_DEFAULT = "No feedback yet"
const ERROR_TITLE = "Could not load feedback"

/**
 * High → low, then by each finding's own authored order. The block's own
 * vocabulary, so a caller never has to pre-sort what it hands in.
 */
const sortFindings = (findings: ReadonlyArray<SubmissionFinding>): Array<SubmissionFinding> =>
    [...findings].sort((a, b) => {
        const rankDiff = SEVERITY_VISUAL[a.severity].rank - SEVERITY_VISUAL[b.severity].rank
        return rankDiff !== 0 ? rankDiff : (a.sortIndex ?? 0) - (b.sortIndex ?? 0)
    })

/**
 * `repositoryUrl` + a repo-relative `location` → a `blob/HEAD` deep-link. Ported
 * from `FindingAccordionItem` unchanged.
 */
const buildLocationHref = (location: string, repositoryUrl?: string): string | undefined =>
    repositoryUrl ? `${repositoryUrl.replace(/\.git$/, "")}/blob/HEAD/${location.replace(/^\//, "")}` : undefined

/**
 * Trigger icon: the severity glyph, its OWN tone colour independent of the
 * title text — rides `titleStart`, not composed into `title` itself (§ same
 * rule as `ChallengeDeliverableList`'s status icon).
 */
const findingIcon = (finding: SubmissionFinding): ReactNode => {
    const { icon: Icon, toneClassName } = SEVERITY_VISUAL[finding.severity]
    return (
        <Icon
            aria-hidden
            focusable="false"
            weight="bold"

            className={cn("size-3.5 shrink-0", toneClassName)}
        />
    )
}

/** Trailing trigger slot: the finding's file location, as a quiet chip. */
const findingLocationChip = (finding: SubmissionFinding): ReactNode | undefined =>
    finding.location ? (
        <Chip
            tone="default"
            text={finding.location}


        />
    ) : undefined

/**
 * Panel content: the markdown detail, the linked file location, and the markdown
 * suggested fix — each optional, each its own row (`related`: independent facts
 * about one finding, not a single unit of meaning).
 */
const findingPanel = (finding: SubmissionFinding, repositoryUrl: string | undefined): ReactNode => {
    const locationHref = finding.location ? buildLocationHref(finding.location, repositoryUrl) : undefined
    const locationRow = finding.location ? (
        <StackH
            gap={2}
            align="center"
            principle="icon-text"
            explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
            items={[
                () => <MapPinIcon aria-hidden focusable="false" weight="bold" className="size-3 shrink-0 text-muted" />,
                () =>
                    locationHref ? (
                        <Typography
                            size="xs"
                            color="muted"
                            isLink
                            underlineOnHover
                            href={locationHref}
                            target="_blank"
                            rel="noopener noreferrer"
                            text={finding.location}

                        />
                    ) : (
                        <Typography size="xs" color="muted" text={finding.location} />
                    ),
            ]}
        />
    ) : null
    const suggestionRow = finding.suggestion ? (
        <StackH
            gap={2}
            align="start"
            principle="icon-text"
            explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
            items={[
                () => <LightbulbIcon aria-hidden focusable="false" weight="bold" className="size-3.5 shrink-0 text-muted" />,
                () => (
                    <div className="min-w-0 flex-1 text-muted [&_p]:m-0">
                        <MarkdownContent
                            source={finding.suggestion ?? ""}
                            measure="compact"

                        />
                    </div>
                ),
            ]}
        />
    ) : null
    return (
        <StackV
            gap={3}

            items={[
                ...(finding.detail ? [() => (
                    <div className="text-muted [&_p]:m-0">
                        <MarkdownContent
                            source={finding.detail ?? ""}
                            measure="compact"

                        />
                    </div>
                )] : []),
                () => locationRow,
                () => suggestionRow,
            ]}
        />
    )
}

interface FindingsErrorEmptyStateProps {
    onRetry?: () => void
    retryLabel?: string
}
const ErrorEmptyState = ({ onRetry, retryLabel }: FindingsErrorEmptyStateProps) => (
    <AsyncContentError
        title={ERROR_TITLE}
        onRetry={onRetry}
        retryLabel={retryLabel}
    />
)

interface FindingsPlainEmptyStateProps {
    title: string
}
const PlainEmptyState = ({ title }: FindingsPlainEmptyStateProps) => (
    <AsyncContentEmpty title={title} />
)

/**
 * The "Feedback" findings card. See the file header for what this block owns
 * (severity vocabulary, sort order, the repo-URL→file-link builder) and why
 * loading/empty/error all stay bounded inside the one `SurfaceCard.Accordion`
 * frame instead of swapping it out for `AsyncContent`'s own switch.
 *
 * @param props - {@link SubmissionFindingsListProps}
 */
const SubmissionFindingsList = ({
    findings,
    repositoryUrl,
    label,
    isLoading = false,
    isEmpty,
    emptyLabel,
    error,
    onRetry,
    retryLabel,
    isSkeleton = false,
}: SubmissionFindingsListProps) => {
    // Error outranks even a stale loading/skeleton flag — same priority order
    // `AsyncContent` itself documents ("error → loading → empty → content") — so a
    // caller handing both `error` and `isLoading` still sees the error, not a
    // skeleton pretending the fetch is still running.
    const skeleton = !error && (isLoading || isSkeleton)
    const resolvedEmpty = !error && (isEmpty ?? findings.length === 0)

    const items: Array<SurfaceCardAccordionItem> = error
        ? []
        : sortFindings(findings).map((finding) => ({
            id: finding.id,
            titleStart: () => findingIcon(finding),
            title: finding.message,
            titleEnd: () => findingLocationChip(finding),
            body: () => findingPanel(finding, repositoryUrl),
        }))

    const emptyState = error
        ? () => <ErrorEmptyState onRetry={onRetry} retryLabel={retryLabel} />
        : resolvedEmpty
            ? () => <PlainEmptyState title={emptyLabel ?? EMPTY_LABEL_DEFAULT} />
            : undefined

    return (
        <div>
            <SurfaceCardAccordion
                label={label}
                items={items}
                isSkeleton={skeleton}
                emptyState={emptyState}


            />
        </div>
    )
}

export { SubmissionFindingsList }

import React from "react"
import { LinkBack } from "@sb-components/atoms/navigation/Link/Link"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { PageHeader } from "@sb-components/composites/layout/Page/Page"

/**
 * `SubmissionResultHeader` — the identity band of a graded-result page: a way back
 * to the challenge, plus the requirement's title and description. Sibling of
 * `ContentHeader`, but a result page has left the material — no read-state chip,
 * minutes, or outcomes card, just "where am I, what is this, how do I leave". The
 * breadcrumb slot holds a `LinkBack` composed from `backLabel` + `onBack`. One
 * shape: `isSkeleton` is a state, since only the data changes.
 */

/** Props for {@link SubmissionResultHeader}. */
export interface SubmissionResultHeaderProps {
    /** Back-link label, localized by the caller, e.g. "Back to the solution". */
    backLabel: string
    /** Fired when the learner leaves the result page for the challenge solve page. */
    onBack: () => void
    /** The graded requirement's title. */
    title: string
    /** The requirement's own description/prompt. Omitted → the header ends at the title. */
    description?: string
    /**
     * `true` → every composed atom switches to its own shimmer. The flag FLOWS
     * DOWN into the real atoms (or their skeleton mirror when the atom has none
     * of its own) rather than building a parallel skeleton tree (§12c).
     */
    isSkeleton?: boolean
}

/**
 * Identity band of a graded-result page. See the file header for the full
 * contract and why the breadcrumb slot holds a back-link instead of a trail.
 *
 * @param props - {@link SubmissionResultHeaderProps}
 */
const SubmissionResultHeader = ({
    backLabel,
    onBack,
    title,
    description,
    isSkeleton = false,
}: SubmissionResultHeaderProps) => {
    return (
        <div>
            <PageHeader

                isSkeleton={isSkeleton}
                breadcrumb={() =>
                    isSkeleton ? (
                        <Typography size="sm" isSkeleton />
                    ) : (
                        <LinkBack label={backLabel} onPress={onBack} />
                    )
                }
                title={title}
                description={description}
            />
        </div>
    )
}

