                                    ),
                                    () => <StackV gap={4} items={[() => metaRows]} />,
                                ]}
                            />
                        </div>
                    ),
                    () => (
                        <StackV
                            gap={6}
                            classNames={["min-w-0", "flex-1"]}
                            items={[
                                () => (
                                    <StackV
                                        gap={4}
                                        principle="card-caption"
                                        explain="Section title over its readiness cluster — not title-subtitle, because the cluster is a separate surface stack rather than a continuing subtitle line."
                                        items={[
                                            () => <Typography size="h4" isSkeleton />,
                                            () => (
                                                <StackV
                                                    gap={4}
                                                    principle="card-caption"
                                                    explain="Readiness summary card stacked above its track list — not sibling-stack, because the list captions the summary rather than repeating the same kind of peer."
                                                    items={[
                                                        () => (
                                                            <SurfaceCard
                                                                padding={4}
                                                                body={() => (
                                                                    <StackV
                                                                        gap={3}
                                                                        items={[
                                                                            () => <Typography size="h3" isSkeleton />,
                                                                            () => <Typography size="sm" isSkeleton />,
                                                                            () => <Typography size="xs" isSkeleton />,
                                                                        ]}
                                                                    />
                                                                )}
                                                            />
                                                        ),
                                                        () => <SurfaceCardList items={readinessItems} />,
                                                    ]}
                                                />
                                            ),
                                        ]}
                                    />
                                ),
                                () => (
                                    <StackV
                                        gap={4}
                                        items={[
                                            () => <Typography size="h4" isSkeleton />,
                                            () => <SurfaceCardList items={courseItems} />,
                                        ]}
                                    />
                                ),
                                () => (
                                    <StackV
                                        gap={4}
                                        items={[
                                            () => <Typography size="h4" isSkeleton />,
                                            () => (
                                                <StackV
                                                    gap={4}
                                                    items={[
                                                        () => <HeroSkeleton className="h-40 w-full rounded-xl" />,
                                                        () => (
                                                            <StackH
                                                                gap={3}
                                                                items={[
                                                                    () => <HeroSkeleton className="size-4 rounded-full" />,
                                                                    () => <Typography size="sm" isSkeleton />,
                                                                ]}
                                                            />
                                                        ),
                                                    ]}
                                                />
                                            ),
                                        ]}
                                    />
                                ),
                                () => (
                                    <Grid
                                        columns={{ base: 1, md: 2 }}
                                        principle="block-boundary"
                                        explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                                        items={skillItems}
                                    />
                                ),
                            ]}
                        />
                    ),
                ]}
            />
        </div>
    )

    return (
        <div
            aria-busy="true"
            aria-label="Loading profile"
            className="flex w-full flex-col"
        >
            {/* tab strip — full-bleed row under the navbar, same footprint as `ProfileTabsBar`.
                `px-6 py-3` is a one-off placement wrapper (a full-width strip flush under a sticky
                navbar, not a repeating list nor a generic card seam), same allowance `ContinueCard`
                uses for its own content wrapper — both padding digits (6, 3) are on the §10c scale.
                Carried via `Container`'s own `padding` prop (house-scale {{ x: 6, y: 4 }} = `px-6 py-3`)
                instead of a raw div — no `patterns.mjs` token names this asymmetric shape yet. */}
            <Container
                size="full"
                padding={{ x: 6, y: 4 }}
                body={() => (
                    <Tabs
                        items={TAB_ITEMS}
                        selectedKey={TAB_ITEMS[0].key}
                        onSelectionChange={() => {}}
                        ariaLabel="Profile sections loading"
                        variant="secondary"
                        isSkeleton
                    />
                )}
            />

            <Container size="lg" padding={6} body={() => overviewBody} />
        </div>
    )
}

import { HouseIcon, UserCircleMinusIcon } from "@phosphor-icons/react"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import { EmptyState } from "@sb-components/composites/feedback/EmptyState/EmptyState"

/**
 * `ProfileNotFoundState` — the 404-style whole-route message for a profile
 * that cannot be read (not found, soft-deleted, or a failed fetch). Composes
 * `EmptyState` in its plain icon+title+description+action form. One leaf: the
 * shape never branches, so different inputs are states.
 */

/** Props for {@link ProfileNotFoundState}. */
export interface ProfileNotFoundStateProps {
    /** Headline saying the profile could not be found, localized by the caller — e.g. "Profile not found". */
    title: string
    /** Supporting sentence explaining why (removed, private, or never existed), localized by the caller. */
    description: string
    /** Fired when the reader takes the one way out: back to the home route. */
    onGoHome: () => void
}

/**
 * Whole-route 404-style message for an unresolvable public profile. See the
 * file header for the full contract and the numeral-shell judgement call.
 *
 * @param props - {@link ProfileNotFoundStateProps}
 */
const ProfileNotFoundState = ({
    title,
    description,
    onGoHome,
}: ProfileNotFoundStateProps) => (
    <div>
        <EmptyState
            icon={UserCircleMinusIcon}
            title={title}
            description={description}
            action={() => (
                <Button
                    label="Back to home"
                    variant="primary"
                    prefixIcon={HouseIcon}
                    onPress={onGoHome}
                />
            )}

        />
    </div>
)

export { ProfileNotFoundState }
